'use strict';

const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const view = $('#route-view');
const overlayRoot = $('#overlay-root');
const toastRoot = $('#toast-root');

const SEARCH_KINDS=[['all','Everything'],['projects','Projects'],['logs','Build Logs'],['questions','Questions'],['discussions','Discussions'],['notes','Shop Notes'],['build-alongs','Build Alongs'],['briefs','Open Briefs'],['library','Library'],['instruments','Field Instruments'],['people','People'],['crews','Maker Crews'],['gearhead','GearHead Crew']];

const state = {
  me: null,
  meta: { version:'7.1.1' },
  home: null,
  theme: localStorage.getItem('workshop-theme') || (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'),
  deep: localStorage.getItem('workshop-mode') === 'deep',
  draftTimer: null,
  lastFocus: null,
  routeToken: 0,
};

document.documentElement.dataset.theme = state.theme;
document.body.classList.toggle('deep', state.deep);

function esc(v='') { return String(v).replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])); }
function fmtDate(v, long=false) {
  if (!v) return '';
  const d = new Date(v);
  return new Intl.DateTimeFormat(undefined, long ? {month:'short',day:'numeric',year:'numeric'} : {month:'short',day:'numeric'}).format(d);
}
function ago(v) {
  const sec = Math.max(0, (Date.now() - new Date(v).getTime()) / 1000);
  if (sec < 3600) return `${Math.max(1,Math.floor(sec/60))}m ago`;
  if (sec < 86400) return `${Math.floor(sec/3600)}h ago`;
  if (sec < 604800) return `${Math.floor(sec/86400)}d ago`;
  return fmtDate(v);
}
function initials(name='?') { return name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase() || '?'; }
function toast(message, kind='ok') {
  const el=document.createElement('div');
  el.className=`toast ${kind==='error'?'error':''}`;
  el.setAttribute('role', kind==='error' ? 'alert' : 'status');
  el.setAttribute('aria-live', kind==='error' ? 'assertive' : 'polite');
  el.innerHTML=`<span aria-hidden="true">${kind==='error'?'!':'✓'}</span><span>${esc(message)}</span>`;
  toastRoot.append(el);
  requestAnimationFrame(()=>el.classList.add('is-visible'));
  setTimeout(()=>{el.classList.remove('is-visible');setTimeout(()=>el.remove(),220)},3200);
}
const offlineState={online:navigator.onLine,queueKey:'workshop-offline-queue-v1',cacheKey:'workshop-api-cache-v1'};
function offlineCache(){try{return JSON.parse(localStorage.getItem(offlineState.cacheKey)||'{}')}catch{return {}}}
function saveOfflineCache(c){try{localStorage.setItem(offlineState.cacheKey,JSON.stringify(c))}catch{}}
function offlineQueue(){try{return JSON.parse(localStorage.getItem(offlineState.queueKey)||'[]')}catch{return []}}
function saveOfflineQueue(q){localStorage.setItem(offlineState.queueKey,JSON.stringify(q));updateConnectivityUI()}
function queueable(path,opts){return ['POST','PUT','PATCH','DELETE'].includes(String(opts.method||'GET').toUpperCase())&&!/^\/api\/(auth|admin|membership)/.test(path)&&!path.includes('/files')}
async function api(path, options={}) {
  const opts={...options,headers:{...(options.body ? {'Content-Type':'application/json'} : {}),...(options.headers||{})}};
  const method=String(opts.method||'GET').toUpperCase();
  try{
    const res=await fetch(path,opts); const data=await res.json().catch(()=>({}));
    if(!res.ok) throw new Error(data.error || `Request failed (${res.status})`);
    if(method==='GET'){const c=offlineCache();c[path]={at:Date.now(),data};saveOfflineCache(c)}
    return data;
  }catch(err){
    if(method==='GET'){const hit=offlineCache()[path];if(hit){updateConnectivityUI(false);return {...hit.data,__offline:true}}}
    if(!navigator.onLine&&queueable(path,opts)){const q=offlineQueue();q.push({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()+Math.random()),path,method,body:opts.body||'',queuedAt:new Date().toISOString()});saveOfflineQueue(q);updateConnectivityUI(false);toast('Saved offline. It will sync when the connection returns.');return {queued:true,offline:true};}
    throw err;
  }
}
async function flushOfflineQueue(){if(!navigator.onLine)return;let q=offlineQueue();if(!q.length){updateConnectivityUI(true);return}const left=[];for(const item of q){try{const res=await fetch(item.path,{method:item.method,headers:item.body?{'Content-Type':'application/json'}:{},body:item.body||undefined});if(!res.ok){if(res.status>=500)left.push(item);else toast(`Offline item needs attention (${res.status}).`,'error')}}catch{left.push(item);break}}saveOfflineQueue(left);updateConnectivityUI(true);if(q.length&&!left.length){toast('Offline work synced.');renderRoute()}}
function updateConnectivityUI(force){offlineState.online=force===undefined?navigator.onLine:force;let el=document.getElementById('offline-status');if(!el){el=document.createElement('button');el.id='offline-status';el.className='offline-status';el.type='button';el.setAttribute('aria-live','polite');el.setAttribute('aria-label','Connection and offline queue status');el.addEventListener('click',()=>flushOfflineQueue());document.body.append(el)}const n=offlineQueue().length;el.textContent=!offlineState.online?`OFFLINE · ${n} queued`:n?`SYNC · ${n} queued`:'ONLINE';el.classList.toggle('is-offline',!offlineState.online||n>0);}

function setTitle(title) { document.title = title ? `${title} — THE WORKSHOP` : 'THE WORKSHOP — Green Shoe Garage'; }
function closeOverlay(){
  if(state.me?.forcePasswordReset && $('#forced-reset-form',overlayRoot))return;
  if(!overlayRoot.firstElementChild)return;
  overlayRoot.innerHTML='';
  document.body.classList.remove('modal-open');
  if(state.lastFocus && document.contains(state.lastFocus)){
    try{state.lastFocus.focus({preventScroll:true})}catch{state.lastFocus.focus()}
  }
  state.lastFocus=null;
}
function modal({title,eyebrow='',body='',size='',onOpen}){
  state.lastFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;
  const titleId=`modal-title-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;
  overlayRoot.innerHTML=`<div class="overlay"><section class="modal ${size}" role="dialog" aria-modal="true" aria-labelledby="${titleId}" data-stop-close><header class="modal-head"><div>${eyebrow?`<div class="eyebrow">${esc(eyebrow)}</div>`:''}<h2 id="${titleId}">${esc(title)}</h2></div><button class="close-btn dialog-exit" type="button" data-action="close-overlay" aria-label="Exit dialog">EXIT</button></header><div class="modal-body">${body}</div></section></div>`;
  document.body.classList.add('modal-open');
  const m=$('.modal',overlayRoot);
  m.addEventListener('click',e=>{
    const actionTarget=e.target.closest('[data-action]');
    if(actionTarget && m.contains(actionTarget)) handleClick(e);
    e.stopPropagation();
  });
  m.addEventListener('keydown',e=>{
    if(e.key!=='Tab')return;
    const focusable=$$('button:not([disabled]),a[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])',m).filter(x=>x.offsetParent!==null);
    if(!focusable.length)return;
    const first=focusable[0],last=focusable[focusable.length-1];
    if(e.shiftKey && document.activeElement===first){e.preventDefault();last.focus()}
    else if(!e.shiftKey && document.activeElement===last){e.preventDefault();first.focus()}
  });
  $$('.field label:not(.check-line)',m).forEach((label,index)=>{
    if(label.htmlFor)return;
    const field=label.parentElement?.querySelector('input:not([type="hidden"]),textarea,select');
    if(!field)return;
    if(!field.id)field.id=`modal-field-${Date.now()}-${index}`;
    label.htmlFor=field.id;
  });
  if(onOpen) onOpen(m);
  requestAnimationFrame(()=>{
    const preferred=$('input:not([type="hidden"]):not([disabled]),textarea:not([disabled]),select:not([disabled]),button:not(.close-btn):not([disabled]),a[href]',m);
    (preferred||$('.close-btn',m)||m).focus({preventScroll:true});
  });
}
function tags(items=[], limit=4){ return (items||[]).slice(0,limit).map(t=>`<span class="tag">${esc(t)}</span>`).join(''); }
function imageSrc(raw){
  const value=String(raw||'').trim();
  if(!value)return '';
  if(value.startsWith('/')||value.startsWith('data:')||value.startsWith('blob:'))return value;
  try{const u=new URL(value,location.href);if(u.protocol==='http:'||u.protocol==='https:'){if(u.origin===location.origin)return u.href;return `/api/image-proxy?url=${encodeURIComponent(u.href)}`;}}catch{}
  return value;
}
function projectCard(p){
  const visual=p.coverUrl
    ? `<img src="${esc(imageSrc(p.coverUrl))}" alt="${esc(p.title||'Project cover')}" loading="lazy" decoding="async">`
    : `<span>${esc(p.coverEmoji||'✦')}</span>`;
  const latest=`${Number(p.logCount||0)} ${Number(p.logCount)===1?'notebook entry':'notebook entries'}`;
  return `<a class="project-card" href="#/projects/${encodeURIComponent(p.id)}">
    <div class="project-visual">${visual}<div class="project-visual-label">${esc((p.disciplines||[])[0]||p.projectType||'PROJECT')}</div></div>
    <div class="project-body">
      <div class="project-state-line">${p.crewCode?`<span class="crew-badge">${esc(p.crewCode)}</span>`:''}<span class="stage-badge stage-${esc(String(p.stage||'idea').toLowerCase().replace(/\s+/g,'-'))}">${esc(p.stage)}</span><span class="project-maker">${esc(p.owner||'')}</span></div>
      <h3>${esc(p.title)}</h3><p>${esc(p.description)}</p>
      <div class="project-tags">${tags(p.disciplines,3)}</div>
      <div class="project-footer"><span>${latest}</span><span>Updated ${ago(p.updatedAt)}</span></div>
    </div></a>`;
}
function empty(title,copy,action='',actionLabel='Start Something'){
  return `<div class="empty"><h3>${esc(title)}</h3><p>${esc(copy)}</p>${action?`<button class="button" data-action="${esc(action)}">${esc(actionLabel)}</button>`:''}</div>`;
}
function pageHead(eyebrow,title,copy='',actions=''){
  return `<header class="page-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1>${copy?`<p>${esc(copy)}</p>`:''}</div>${actions?`<div class="head-actions">${actions}</div>`:''}</header>`;
}
const NAV_PARENT={'gearhead-vault':'library','gearhead-requests':'library','gearhead-archive':'library',gearhead:'library',sessions:'builds',session:'builds',assignment:'builds','maker-id':'people',crews:'people',crew:'people',projects:'builds','build-along':'builds','open-brief':'builds',wall:'builds',discussion:'workshop',question:'workshop',critiques:'workshop',critique:'workshop',weekly:'workshop',mysteries:'workshop',mystery:'workshop',teardown:'workshop',scrap:'workshop',lab:'library',saved:'library',clinic:'live','skill-exchange':'people'};
const CONTEXT_NAV={
  builds:[['#/builds','PROJECTS'],['#/sessions','SESSIONS'],['#/builds#programs','BUILD ALONGS + BRIEFS'],['#/wall','THE WALL']],
  workshop:[['#/workshop','DISCUSSIONS'],['#/critiques','CRITIQUE'],['#/weekly','QUESTION OF THE WEEK'],['#/mysteries','WHAT IS THIS?'],['#/teardown','TEARDOWN CLUB'],['#/scrap','SCRAP BIN']],
  library:[['#/library','SHOP MANUAL'],['#/lab','FIELD INSTRUMENT LAB'],['#/gearhead','GEARHEAD CREW'],['#/gearhead-vault','FILE VAULT'],['#/gearhead-requests','CREW REQUESTS'],['#/gearhead-archive','ARCHIVE'],['#/saved','SAVED']],
  live:[['#/live','LIVE FROM THE GARAGE'],['#/clinic','PROJECT CLINIC']],
  people:[['#/people','PEOPLE'],['#/crews','MAKER CREWS'],['#/skill-exchange','SKILL EXCHANGE'],['#/maker-id','MAKER ID']]
};
function setActiveNav(route){
  const parent=NAV_PARENT[route]||route;
  $$('[data-route]').forEach(a=>{const active=a.dataset.route===parent;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
  const host=$('#context-nav'); if(!host)return;
  const items=CONTEXT_NAV[parent]||[];
  host.innerHTML=items.length?`<div class="context-label">${esc(parent.toUpperCase())}</div>${items.map(([href,label])=>`<a href="${href}" class="${href.includes('#/'+route)||href===location.hash?'active':''}">${esc(label)}</a>`).join('')}`:'';
  host.hidden=!items.length;
}
function routeParts(){ const raw=location.hash.replace(/^#\/?/,'')||'home'; return raw.split('/').filter(Boolean); }

async function bootstrap(){
  try { state.meta=await api('/api/meta'); } catch {}
  $('#version-label').textContent=`THE WORKSHOP v${state.meta.version||'7.1.1'}`;
  try { state.me=(await api('/api/me')).user; } catch { state.me=null; }
  updateUserUI();
  if('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').catch(()=>{});
  window.addEventListener('hashchange',renderRoute);
  window.addEventListener('online',()=>{updateConnectivityUI(true);flushOfflineQueue()});
  window.addEventListener('offline',()=>updateConnectivityUI(false));
  updateConnectivityUI();
  if(navigator.onLine) flushOfflineQueue();
  document.addEventListener('click',handleClick);
  document.addEventListener('keydown',handleKeys);
  $('#global-search').addEventListener('submit',e=>{e.preventDefault();const q=$('#search-input').value.trim();if(q)location.hash=`#/search/${encodeURIComponent(q)}`;});
  $('#theme-toggle').addEventListener('click',toggleTheme);
  $('#mode-toggle').addEventListener('click',toggleMode);
  $('#notification-button').addEventListener('click',showNotifications);
  $('#user-button').addEventListener('click',showAccount);
  $('#start-button').addEventListener('click',showStart);
  $('#mobile-start').addEventListener('click',showStart);
  await renderRoute();
  enforceAccountRequirements();
}
function updateUserUI(){
  $('#user-avatar').textContent=state.me?initials(state.me.displayName):'?';
  $('#user-name').textContent=state.me?state.me.displayName:'ENTER';
  $('#mode-toggle span').textContent=state.deep?'DEEP':'SIMPLE';
  if(state.me) refreshNotificationDot(); else $('#notification-dot').hidden=true;
}
async function refreshNotificationDot(){ try{const d=await api('/api/notifications');$('#notification-dot').hidden=!d.items.some(n=>!Number(n.read));}catch{$('#notification-dot').hidden=true;} }
function toggleTheme(){ state.theme=state.theme==='dark'?'light':'dark'; document.documentElement.dataset.theme=state.theme; localStorage.setItem('workshop-theme',state.theme); }
function toggleMode(){ state.deep=!state.deep; document.body.classList.toggle('deep',state.deep); localStorage.setItem('workshop-mode',state.deep?'deep':'simple'); updateUserUI(); toast(`${state.deep?'Deep':'Simple'} mode`); }
function handleKeys(e){ if(e.key==='/' && !/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName) && !document.activeElement.isContentEditable){e.preventDefault();$('#search-input').focus();} }

function routeSkeleton(){
  return `<div class="view route-skeleton" aria-label="Loading workshop content"><div class="skeleton-line short"></div><div class="skeleton-line title"></div><div class="skeleton-line copy"></div><div class="skeleton-grid">${Array.from({length:3},()=>'<div class="skeleton-card"><i></i><b></b><span></span><span></span></div>').join('')}</div></div>`;
}

async function renderRoute(){
  const token=++state.routeToken;
  const parts=routeParts(), route=parts[0]||'home';
  setActiveNav(route);
  view.setAttribute('aria-busy','true');
  view.innerHTML=routeSkeleton();
  try{
    if(route==='reset' && parts[1]) await renderResetRoute(parts[1]);
    else if(route==='home') await renderHome();
    else if(route==='bench') await renderBench(parts[1]||'');
    else if(route==='builds') await renderBuilds();
    else if(route==='sessions') await renderSessions();
    else if(route==='session' && parts[1]) await renderSession(parts[1]);
    else if(route==='assignment' && parts[1]) await renderAssignment(parts[1]);
    else if(route==='projects' && parts[1]) await renderProject(parts[1]);
    else if(route==='workshop') await renderWorkshop();
    else if(route==='discussion' && parts[1]) await renderDiscussion(parts[1]);
    else if(route==='question' && parts[1]) await renderQuestion(parts[1]);
    else if(route==='library' && parts[1]) await renderLibraryItem(parts[1]);
    else if(route==='library') await renderLibrary();
    else if(route==='gearhead-vault') await renderGearheadVault();
    else if(route==='gearhead-contributions') await renderGearheadContributions();
    else if(route==='gearhead-projects') await renderGearheadCrewProjects();
    else if(route==='gearhead-requests') await renderGearheadRequests();
    else if(route==='gearhead-archive') await renderGearheadArchive();
    else if(route==='gearhead' && parts[1]) await renderGearheadEntry(parts[1]);
    else if(route==='gearhead') await renderGearhead();
    else if(route==='people') await renderPeople();
    else if(route==='crews') await renderCrews(parts[1]?decodeURIComponent(parts[1]):'');
    else if(route==='crew' && parts[1]) await renderCrew(parts[1],parts[2]||'');
    else if(route==='maker-id') await renderMakerId(parts[1]||'');
    else if(route==='saved') await renderSaved(parts[1]||'');
    else if(route==='search' && parts[1]) await renderSearch(decodeURIComponent(parts[1]),parts[2]||'all');
    else if(route==='build-along' && parts[1]) await renderBuildAlong(parts[1]);
    else if(route==='open-brief' && parts[1]) await renderOpenBrief(parts[1]);
    else if(route==='critiques') await renderCritiques();
    else if(route==='critique' && parts[1]) await renderCritique(parts[1]);
    else if(route==='live' && parts[1]) await renderLiveEvent(parts[1]);
    else if(route==='live') await renderLive();
    else if(route==='clinic' && parts[1]) await renderClinic(parts[1]);
    else if(route==='clinic') await renderClinics();
    else if(route==='skill-exchange') await renderSkillExchange();
    else if(route==='lab' && parts[1]) await renderInstrument(parts[1]);
    else if(route==='lab') await renderInstrumentLab();
    else if(route==='wall' && parts[1]) await renderWallExhibition(parts[1]);
    else if(route==='wall') await renderWall();
    else if(route==='weekly' && parts[1]) await renderWeeklyQuestion(parts[1]);
    else if(route==='weekly') await renderWeeklyQuestions();
    else if(route==='mystery' && parts[1]) await renderMystery(parts[1]);
    else if(route==='mysteries') await renderMysteries();
    else if(route==='teardown' && parts[1]) await renderTeardown(parts[1]);
    else if(route==='teardown') await renderTeardownClub();
    else if(route==='scrap' && parts[1]) await renderScrapListing(parts[1]);
    else if(route==='scrap') await renderScrapBin();
    else if(route==='admin') await renderAdmin();
    else if(route==='terms') renderTerms();
    else if(route==='about') renderAbout();
    else await renderHome();
    if(token===state.routeToken){
      view.setAttribute('aria-busy','false');
      requestAnimationFrame(()=>{
        const heading=$('h1',view);
        const announcer=$('#route-announcer');
        if(announcer){
          const label=(heading?.textContent||document.title.split(' — ')[0]||'Workshop').replace(/\s+/g,' ').trim();
          announcer.textContent='';
          setTimeout(()=>{announcer.textContent=`${label} loaded`;},20);
        }
        window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});
      });
    }
  }catch(err){
    view.setAttribute('aria-busy','false');
    view.innerHTML=`<div class="view narrow error-state-v4">${pageHead('Something slipped','That didn’t work',err.message)}<div class="error-actions-v4"><button class="button" data-action="retry-route">RETRY</button><a class="button-secondary" href="#/home">RETURN HOME</a></div></div>`;
  }
}

