async function renderProject(pid){
  const d=await api(`/api/projects/${encodeURIComponent(pid)}`), p=d.project; setTitle(p.title);
  const isOwner=state.me && state.me.id===p.ownerId;
  const canWork=Boolean(d.canCollaborate);
  view.innerHTML=`<div class="view">
    <header class="project-header"><div class="project-title-row"><div class="project-glyph">${esc(p.coverEmoji)}</div><div><div class="eyebrow">${esc(p.stage)} · ${esc(p.status)}</div><h1>${esc(p.title)}</h1><div class="project-meta-line">By ${esc(p.owner)} · updated ${ago(p.updatedAt)}</div></div><div class="head-actions"><button class="button-secondary" data-action="save-project" data-id="${esc(p.id)}">${p.saved?'★ SAVED':'☆ SAVE'}</button>${isOwner?`<button class="button" data-action="add-log" data-id="${esc(p.id)}">+ ADD UPDATE</button>`:''}</div></div><p class="project-description">${esc(p.description)}</p><div class="project-tags">${tags(p.disciplines,9)}${tags(p.tags,9)}</div></header>
    <div class="project-layout"><section><div class="section-head"><h2>Build Log</h2>${isOwner?`<button class="text-button" data-action="failure-log" data-id="${esc(p.id)}">+ THIS DIDN’T WORK</button>`:''}</div>
      ${d.logs.length?`<div class="filter-bar" id="log-filters"><button class="active" data-log-filter="all">All</button>${[...new Set(d.logs.map(l=>l.type))].map(x=>`<button data-log-filter="${esc(x)}">${esc(x)}</button>`).join('')}</div><div class="timeline" id="timeline">${d.logs.map(l=>`<article class="log-entry ${l.type==='Failure'?'failure':''}" data-log-type="${esc(l.type)}"><span class="log-dot"></span><div class="log-type">${esc(l.type)}</div><h3>${esc(l.title||l.type)}</h3><p>${esc(l.body)}</p><time>${esc(l.author)} · ${fmtDate(l.created_at,true)}</time></article>`).join('')}</div>`:empty('NO BUILD LOG ENTRIES YET','What happened first?',isOwner?'add-log':'',isOwner?'ADD ENTRY':'')}
      <section class="comments"><div class="section-head"><h2>Shop Talk</h2><p>${d.comments.length} ${d.comments.length===1?'comment':'comments'}</p></div><div>${d.comments.map(c=>`<div class="comment"><div class="comment-avatar">${esc(initials(c.author))}</div><div class="comment-body"><strong>${esc(c.author)}</strong><p>${esc(c.body)}</p></div></div>`).join('')}</div>${state.me?`<form id="comment-form" class="form-grid"><div class="field full"><label for="comment-body">Add to the discussion</label><textarea id="comment-body" name="body" rows="3" placeholder="Useful questions and practical feedback beat applause."></textarea></div><div class="field full"><button class="button" type="submit">ADD COMMENT</button></div></form>`:`<button class="button-secondary" data-action="login">ENTER TO JOIN THE DISCUSSION</button>`}</section>
    </section>
    <aside class="side-panel"><div class="detail-card"><h3>Project</h3><dl class="detail-list"><dt>Stage</dt><dd>${esc(p.stage)}</dd><dt>Status</dt><dd>${esc(p.status)}</dd><dt>Difficulty</dt><dd>${esc(p.difficulty)}</dd><dt>Visibility</dt><dd>${esc(p.visibility)}</dd><dt>Cost</dt><dd>${esc(p.estimatedCost||'—')}</dd></dl></div><div class="detail-card deep-only"><h3>Deep details</h3><dl class="detail-list"><dt>License</dt><dd>${esc(p.license)}</dd><dt>Files</dt><dd>Coming later</dd><dt>Collaborators</dt><dd>Coming later</dd></dl></div><div class="detail-card"><h3>Tools</h3><div class="project-tags">${p.tools.length?tags(p.tools,12):'<span class="tag">Not listed</span>'}</div></div>${`<div class="detail-card project-files-card"><div class="section-head compact-head"><h3>Project Files</h3>${canWork?`<button class="text-button" data-action="upload-file" data-id="${esc(p.id)}">+ UPLOAD</button>`:''}</div>${d.files?.length?d.files.map(f=>`<div class="file-row">${f.locked?`<div><strong>${esc(f.logical_name)}</strong><small>v${f.version} · GEARHEAD CREW ONLY</small></div>`:`<a href="${esc(f.url||`/uploads/${encodeURIComponent(f.stored_name)}`)}" target="_blank" rel="noopener"><strong>${esc(f.logical_name)}</strong><small>v${f.version} · ${Math.max(1,Math.round(f.size_bytes/1024))} KB · ${esc(f.mime_type)}</small></a>`}${isOwner?`<button class="text-button danger-text" data-action="delete-file" data-id="${esc(f.id)}" data-project-id="${esc(p.id)}">REMOVE</button>`:''}</div>`).join(''):`<p class="muted-copy">No project files yet.</p>`}</div>`}${p.parentType?`<div class="detail-card"><h3>Started from</h3><a class="linked-project" href="#/${p.parentType==='Build Along'?'build-along':'open-brief'}/${esc(p.parentId)}">↗ ${esc(p.parentType)}</a></div>`:''}</aside></div>
  </div>`;
  const commentForm=$('#comment-form'); if(commentForm) commentForm.addEventListener('submit',async e=>{e.preventDefault();const body=new FormData(commentForm).get('body');try{await api(`/api/projects/${p.id}/comments`,{method:'POST',body:JSON.stringify({body})});toast('Added to the discussion.');await renderProject(p.id);}catch(err){toast(err.message,'error')}});
}

