function shopNoteRow(n){const canEdit=state.me&&(state.me.id===n.user_id||['Owner','Administrator','Editor'].includes(state.me.role));return `<article class="note-row shop-note-row"><div class="row-meta">${esc(n.author)}<br>${ago(n.created_at)}</div><div class="row-content"><div class="kicker-row"><strong>${esc(n.title)}</strong>${n.status==='Draft'?'<span class="stage-badge">DRAFT</span>':''}${n.visibility&&n.visibility!=='Public'?`<span class="tag">${esc(n.visibility)}</span>`:''}</div><p>${esc(n.body)}</p>${n.project_id?`<a class="linked-project" href="#/projects/${n.project_id}">↗ ${esc(n.project_title||'Linked project')}</a>`:''}${n.external_link?`<p><a href="${esc(n.external_link)}" target="_blank" rel="noopener">Open reference ↗</a></p>`:''}${attachmentLinks(n.media_refs)}${state.me&&n.status!=='Draft'?`<div class="note-actions"><button class="text-button" data-action="toggle-save" data-item-type="shop-note" data-id="${esc(n.id)}">☆ SAVE</button>${canEdit?`<button class="text-button" data-action="edit-shop-note" data-id="${esc(n.id)}">EDIT</button><button class="text-button danger-text" data-action="delete-shop-note" data-id="${esc(n.id)}">REMOVE</button>`:''}</div>`:canEdit?`<div class="note-actions"><button class="text-button" data-action="edit-shop-note" data-id="${esc(n.id)}">EDIT</button><button class="text-button danger-text" data-action="delete-shop-note" data-id="${esc(n.id)}">REMOVE</button></div>`:''}</div></article>`}
async function shopNoteForm(existing=null){
  if(!requireSignIn())return;let projects=[];try{projects=(await api('/api/projects?mine=1')).projects}catch{};const d=existing||{};
  modal({title:existing?'Edit Shop Note':'New Shop Note',eyebrow:'QUICK NOTES FROM THE GARAGE',size:'lg',body:`<form id="shop-note-form" class="form-grid"><div class="field full"><label>Title</label><input name="title" required value="${esc(d.title||'')}" placeholder="What happened at the bench?"></div><div class="field full"><label>Note</label><textarea name="body" required>${esc(d.body||'')}</textarea></div><div class="field"><label>Status</label><select name="status"><option ${d.status!=='Draft'?'selected':''}>Published</option><option ${d.status==='Draft'?'selected':''}>Draft</option></select></div><div class="field"><label>Visibility</label><select name="visibility">${['Public','Members','Supporter'].map(x=>`<option value="${x}" ${d.visibility===x?'selected':''}>${x==='Supporter'?'GEARHEAD CREW ONLY':x}</option>`).join('')}</select></div><div class="field full"><label>Related project · optional</label><select name="projectId"><option value="">No linked project</option>${projects.map(p=>`<option value="${p.id}" ${d.project_id===p.id?'selected':''}>${esc(p.title)}</option>`).join('')}</select></div><div class="field full deep-only"><label>Image / media references · one per line</label><textarea name="mediaRefs">${esc((d.media_refs||[]).join('\n'))}</textarea></div><div class="field full"><label>External link · optional</label><input name="externalLink" value="${esc(d.external_link||'')}"></div><div class="field full"><div class="form-actions"><span class="autosave-state" id="draft-state"><i></i><b>UNSAVED</b></span><button class="button">${d.status==='Draft'?'SAVE NOTE':'SAVE SHOP NOTE'}</button></div></div></form>`,onOpen:m=>{const f=$('#shop-note-form',m),key=`workshop-draft-shop-note-${existing?.id||'new'}`;restoreDraft(f,key,{});wireAutosave(f,key);f.addEventListener('submit',async e=>{e.preventDefault();try{const body=Object.fromEntries(new FormData(f));if(existing)await api(`/api/shop-notes/${existing.id}`,{method:'PUT',body:JSON.stringify(body)});else await api('/api/shop-notes',{method:'POST',body:JSON.stringify(body)});localStorage.removeItem(key);closeOverlay();toast(body.status==='Draft'?'Shop Note draft saved.':'Shop Note published.');renderShopNotes()}catch(err){toast(err.message,'error')}})}});
}
async function editShopNote(id){const d=await api('/api/shop-notes?mine=1');const n=d.notes.find(x=>x.id===id);if(!n)return toast('Shop Note not found.','error');shopNoteForm(n)}
async function deleteShopNote(id){if(!confirm('Remove this Shop Note?'))return;try{await api(`/api/shop-notes/${id}`,{method:'DELETE'});toast('Shop Note removed.');renderShopNotes()}catch(err){toast(err.message,'error')}}

async function renderLibrary(){
  setTitle('Library'); const d=await api('/api/library');
  const sections=[...new Set(d.items.map(x=>x.section))], types=[...new Set(d.items.map(x=>x.type))];
  view.innerHTML=`<div class="view">${pageHead('Curated references','The Library','A deliberately maintained shop manual: useful guides, references, templates, files, videos, and Field Instruments.',d.canEdit?`<button class="button deep-only" data-action="new-library-item">+ ADD RESOURCE</button>`:'')}
    <div class="library-toolbar"><input id="library-local-search" class="toolbar-search" placeholder="Search this shelf…" aria-label="Search library"><div class="filter-bar" id="library-filters"><button class="active" data-library-filter="all">All sections</button>${sections.map(x=>`<button data-library-filter="${esc(x)}">${esc(x)}</button>`).join('')}</div><div class="filter-bar subtle" id="library-type-filters"><button class="active" data-library-type="all">All types</button>${types.map(x=>`<button data-library-type="${esc(x)}">${esc(x)}</button>`).join('')}</div></div>
    <div class="library-count"><strong id="library-visible-count">${d.items.length}</strong> curated resources <span>· editorial, not an endless dump</span></div>
    <div class="grid three" id="library-grid">${d.items.map(l=>`<div data-library-section="${esc(l.section)}" data-library-type="${esc(l.type)}" data-library-text="${esc((l.title+' '+l.summary+' '+l.tags.join(' ')).toLowerCase())}">${libraryCard(l,d.canEdit)}</div>`).join('')}</div></div>`;
  const inp=$('#library-local-search'); if(inp)inp.addEventListener('input',applyLibraryFilters);
}
function libraryCard(l,canEdit=false){return `<article class="library-card ${l.featured?'featured-library':''}"><div class="kicker-row"><span class="stage-badge">${esc(l.type)}</span><span>${esc(l.section)}</span>${l.featured?'<span class="tag">FEATURED</span>':''}</div><h3><a href="#/library/${encodeURIComponent(l.id)}">${esc(l.title)}</a></h3><p>${esc(l.summary)}</p><div class="project-tags">${tags(l.tags,5)}</div><div class="library-actions"><a class="text-button" href="#/library/${encodeURIComponent(l.id)}">READ / DETAILS →</a>${state.me?`<button class="text-button" data-action="save-library" data-id="${esc(l.id)}">${l.saved?'★ SAVED':'☆ SAVE'}</button>`:''}${canEdit?`<button class="text-button deep-only" data-action="edit-library-item" data-id="${esc(l.id)}">EDIT</button>`:''}</div></article>`;}
function applyLibraryFilters(){const sec=$('#library-filters .active')?.dataset.libraryFilter||'all',typ=$('#library-type-filters .active')?.dataset.libraryType||'all',q=($('#library-local-search')?.value||'').trim().toLowerCase();let n=0;$$('#library-grid>[data-library-section]').forEach(x=>{const show=(sec==='all'||x.dataset.librarySection===sec)&&(typ==='all'||x.dataset.libraryType===typ)&&(!q||x.dataset.libraryText.includes(q));x.hidden=!show;if(show)n++});const c=$('#library-visible-count');if(c)c.textContent=n;}
async function renderLibraryItem(id){const d=await api(`/api/library/${encodeURIComponent(id)}`),l=d.item;setTitle(l.title);view.innerHTML=`<div class="view narrow">${pageHead(l.section,l.title,l.summary,`${state.me?`<button class="button-secondary" data-action="save-library" data-id="${l.id}">${l.saved?'★ SAVED':'☆ SAVE'}</button>`:''}${d.canEdit?`<button class="button deep-only" data-action="edit-library-item" data-id="${l.id}">EDIT RESOURCE</button>`:''}`)}<div class="resource-meta"><span>${esc(l.type)}</span>${l.featured?'<span>Featured</span>':''}<span>Updated ${fmtDate(l.updated_at||l.created_at,true)}</span></div><div class="project-tags">${tags(l.tags,20)}</div>${l.body?`<article class="library-body">${esc(l.body).replace(/\n/g,'<br>')}</article>`:'<p class="muted-copy">This resource is an indexed reference; use the source link for the full material.</p>'}${l.url?`<p><a class="button" href="${esc(l.url)}" target="_blank" rel="noopener">OPEN RESOURCE ↗</a></p>`:''}</div>`;}
function libraryItemForm(existing=null){if(!requireSignIn())return;const d=existing||{};modal({title:existing?'Edit Library Resource':'Add Library Resource',eyebrow:'CURATE THE SHOP MANUAL',size:'lg',body:`<form id="library-item-form" class="form-grid"><div class="field"><label>Type</label><select name="type">${['Guide','Reference','Article','Template','Video','File Collection','Field Instrument','Project Template','Tool Recommendation'].map(x=>`<option ${d.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Section</label><select name="section">${['How To','Design References','Materials','Tools','Processes','Electronics','Embedded Systems','Software','CAD','Fabrication','Repair','Books','Suppliers','Open Source','Green Shoe Garage Projects','Field Instruments','Project Templates'].map(x=>`<option ${d.section===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Title</label><input name="title" required value="${esc(d.title||'')}"></div><div class="field full"><label>Summary</label><textarea name="summary" required>${esc(d.summary||'')}</textarea></div><div class="field full"><label>Body / curator notes</label><textarea name="body">${esc(d.body||'')}</textarea></div>${['Early Access','Field Instrument Preview'].includes(d.entryType)?`<div class="field"><label>Preview status</label><select name="earlyStatus">${['Experimental','Preview','Release Candidate'].map(x=>`<option ${(d.earlyStatus||'Experimental')===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Public target date</label><input type="date" name="publicTargetAt" value="${esc((d.publicTargetAt||'').slice(0,10))}"></div><div class="field full"><label>Requirements</label><textarea name="requirements">${esc(d.requirements||'')}</textarea></div><div class="field full"><label>Known issues</label><textarea name="knownIssues">${esc(d.knownIssues||'')}</textarea></div><div class="field full"><label>Release notes</label><textarea name="releaseNotes">${esc(d.releaseNotes||'')}</textarea></div><div class="field full"><label class="check-line"><input type="checkbox" name="feedbackOpen" ${d.feedbackOpen!==false?'checked':''}> <span>Accept GearHead test feedback</span></label></div>`:''}<div class="field full"><label>Tags</label><input name="tags" value="${esc((d.tags||[]).join(', '))}"></div><div class="field full"><label>Resource URL · optional</label><input name="url" value="${esc(d.url||'')}"></div><div class="field"><label>Visibility</label><select name="visibility"><option ${d.visibility!=='Members'?'selected':''}>Public</option><option ${d.visibility==='Members'?'selected':''}>Members</option></select></div><div class="field"><label>Status</label><select name="status"><option ${d.status!=='Draft'?'selected':''}>Published</option><option ${d.status==='Draft'?'selected':''}>Draft</option></select></div><div class="field full"><label class="check-line"><input type="checkbox" name="featured" value="1" ${d.featured?'checked':''}> Feature this resource in the Library</label></div><div class="field full"><div class="form-actions"><span></span><button class="button">${existing?'SAVE RESOURCE':'ADD TO LIBRARY'}</button></div></div></form>`,onOpen:m=>{$('#library-item-form',m).addEventListener('submit',async e=>{e.preventDefault();try{const raw=Object.fromEntries(new FormData(e.currentTarget));raw.featured=Boolean(raw.featured);const out=await api(existing?`/api/library/${existing.id}`:'/api/library',{method:existing?'PUT':'POST',body:JSON.stringify(raw)});closeOverlay();toast(existing?'Library resource updated.':'Resource added to the Library.');location.hash=`#/library/${existing?.id||out.id}`;renderRoute();}catch(err){toast(err.message,'error')}})}});}
async function editLibraryItem(id){const d=await api(`/api/library/${id}`);libraryItemForm(d.item)}
async function saveLibrary(id){if(!requireSignIn())return;try{const d=await api(`/api/library/${id}/save`,{method:'POST'});toast(d.saved?'Saved to your shelf.':'Removed from your shelf.');renderRoute();}catch(err){toast(err.message,'error')}}

async function renderPeople(){
  setTitle('People'); const d=await api('/api/people');
  const cards=d.people.map(p=>{const searchable=[p.display_name,p.city_region,p.bio,...(p.skills||[]),...(p.can_help||[]),...(p.want_learn||[])].join(' ').toLowerCase();return `<article class="person-card-v4" data-person-search="${esc(searchable)}"><a href="#/bench/${p.id}" class="person-card-main"><div class="person-card-head"><div class="person-avatar-v4">${esc(p.avatar_seed||initials(p.display_name))}</div><div><span class="technical-index">MEMBER BENCH</span><h3>${esc(p.display_name)}</h3>${p.city_region?`<p>⌖ ${esc(p.city_region)}</p>`:''}</div></div><p class="person-bio-v4">${esc(p.bio||'A member of the workshop.')}</p><div class="person-current-v4"><span>${p.project_count||0}</span><small>PROJECT${Number(p.project_count)===1?'':'S'} ON RECORD</small></div></a><div class="person-practice-v4">${(p.skills||[]).length?`<div><span>MAKES / KNOWS</span><p>${esc(p.skills.slice(0,4).join(' · '))}</p></div>`:''}${(p.can_help||[]).length?`<div><span>CAN HELP WITH</span><p>${esc(p.can_help.slice(0,4).join(' · '))}</p></div>`:''}${(p.want_learn||[]).length?`<div><span>WANTS TO LEARN</span><p>${esc(p.want_learn.slice(0,4).join(' · '))}</p></div>`:''}</div><div class="person-card-foot"><a href="#/bench/${p.id}">VISIT BENCH →</a><a href="#/maker-id/${p.id}">MAKER ID →</a>${state.me&&state.me.id!==p.id?`<button class="text-button" data-action="skill-request" data-id="${p.id}" data-name="${esc(p.display_name)}">ASK ABOUT A SKILL</button>`:''}</div></article>`}).join('');
  view.innerHTML=`<div class="view people-view-v4">${pageHead('People make the place','People','Find a bench by what someone makes, knows, can help with, or wants to learn—not by follower counts.','<div class="head-actions"><a class="button" href="#/crews">FIND A MAKER CREW →</a><a class="button-secondary" href="#/skill-exchange">SKILL EXCHANGE →</a></div>')}
    <section class="people-discovery-v4"><div><span class="technical-index">FIND ANOTHER BENCH</span><h2>Who knows something useful?</h2><p>Search a skill, tool, material, process, or thing somebody wants to learn.</p></div><div class="people-search-wrap"><input id="people-search-v4" type="search" placeholder="Try ‘bookbinding’, ‘electronics’, ‘casting’…" aria-label="Search people"><span id="people-count-v4">${d.people.length} people</span></div></section>
    <div class="people-grid-v4" id="people-grid-v4">${cards}</div>
    <div id="people-empty-v4" class="empty" hidden><h3>NOTHING ON THAT BENCH YET</h3><p>Try another skill, tool, or interest.</p></div>
  </div>`;
  const input=$('#people-search-v4'); if(input)input.addEventListener('input',()=>{const q=input.value.trim().toLowerCase();let n=0;$$('#people-grid-v4 .person-card-v4').forEach(card=>{const show=!q||card.dataset.personSearch.includes(q);card.hidden=!show;if(show)n++});$('#people-count-v4').textContent=`${n} ${n===1?'person':'people'}`;$('#people-empty-v4').hidden=n>0;});
}

async function renderSaved(collectionId=''){
  setTitle('Saved'); if(!state.me){view.innerHTML=`<div class="view narrow">${pageHead('Your shelf','Saved','Keep useful projects and references close without turning saving into a popularity score.')}${empty('NOTHING SAVED HERE','Enter the workshop to keep a personal shelf.','login','ENTER THE WORKSHOP')}</div>`;return;}
  const d=await api('/api/saved');
  const all=[
    ...d.projects.map(x=>({type:'project',id:x.id,title:x.title,copy:x.description,href:`#/projects/${x.id}`,meta:`Project · ${x.stage}`})),
    ...d.library.map(x=>({type:'library',id:x.id,title:x.title,copy:x.summary,href:`#/library/${x.id}`,meta:`Library · ${x.section}`})),
    ...d.questions.map(x=>({type:'question',id:x.id,title:x.title,copy:`Asked by ${x.author}`,href:`#/question/${x.id}`,meta:`Question · ${x.status}`})),
    ...d.shopNotes.map(x=>({type:'shop-note',id:x.id,title:x.title,copy:x.body,href:'#/home',meta:`Shop Note · ${x.author}`})),
    ...d.buildAlongs.map(x=>({type:'build-along',id:x.id,title:x.title,copy:x.overview,href:`#/build-along/${x.id}`,meta:'Build Along'})),
    ...d.openBriefs.map(x=>({type:'open-brief',id:x.id,title:x.title,copy:x.objective,href:`#/open-brief/${x.id}`,meta:`Open Brief · ${x.status||'Open'}`}))
  ];
  let current=null,items=all;
  if(collectionId){const cd=await api(`/api/collections/${encodeURIComponent(collectionId)}`);current=cd.collection;const keys=new Set(cd.items.map(x=>`${x.item_type}:${x.item_id}`));items=all.filter(x=>keys.has(`${x.type}:${x.id}`));}
  const actions=`<button class="button" data-action="new-collection">+ NEW COLLECTION</button>${current?`<button class="button-secondary" data-action="edit-collection" data-id="${current.id}">EDIT COLLECTION</button>`:''}`;
  view.innerHTML=`<div class="view">${pageHead('Your private research shelf',current?current.name:'Saved',current?(current.description||'A personal collection of things worth returning to.'):'Projects, questions, notes, references, Build Alongs, and briefs you deliberately kept close.',actions)}
    ${d.collections.length?`<section class="section"><div class="section-head"><h2>Collections</h2><a href="#/saved">All saved →</a></div><div class="collection-strip">${d.collections.map(c=>`<a class="collection-card ${current?.id===c.id?'active':''}" href="#/saved/${c.id}"><strong>${esc(c.name)}</strong><span>${c.item_count} ${Number(c.item_count)===1?'item':'items'}</span><small>${esc(c.description||'Personal collection')}</small></a>`).join('')}</div></section>`:''}
    <section class="section"><div class="section-head"><h2>${current?'In this collection':'Everything saved'}</h2><p>${items.length} ${items.length===1?'item':'items'} · private</p></div>${items.length?`<div class="saved-grid">${items.map(x=>savedTile(x,d.collections,current?.id||'')).join('')}</div>`:empty(current?'THIS COLLECTION IS EMPTY':'NOTHING SAVED HERE',current?'Add saved items from your shelf.':'Save something useful when you want to find it again.')}</section>
  </div>`;
}
function savedTile(x,collections,currentId=''){return `<article class="saved-item"><a href="${esc(x.href)}"><div class="eyebrow">${esc(x.meta)}</div><h3>${esc(x.title)}</h3><p>${esc(String(x.copy||'').slice(0,220))}</p></a><div class="saved-item-actions">${collections.length?`<button class="text-button" data-action="organize-saved" data-item-type="${esc(x.type)}" data-id="${esc(x.id)}">ORGANIZE</button>`:''}${currentId?`<button class="text-button danger-text" data-action="remove-from-collection" data-collection-id="${esc(currentId)}" data-item-type="${esc(x.type)}" data-id="${esc(x.id)}">REMOVE HERE</button>`:''}<button class="text-button" data-action="toggle-save" data-item-type="${esc(x.type)}" data-id="${esc(x.id)}">UNSAVE</button></div></article>`}
function collectionForm(existing=null){if(!requireSignIn())return;modal({title:existing?'Edit Collection':'New Collection',eyebrow:'PRIVATE ORGANIZATION',size:'sm',body:`<form id="collection-form" class="form-grid"><div class="field full"><label>Name</label><input name="name" required value="${esc(existing?.name||'')}" placeholder="Repair references"></div><div class="field full"><label>What belongs here?</label><textarea name="description">${esc(existing?.description||'')}</textarea></div><div class="field full"><button class="button">${existing?'SAVE COLLECTION':'CREATE COLLECTION'}</button></div></form>${existing?`<button class="text-button danger-text" data-action="delete-collection" data-id="${existing.id}">DELETE COLLECTION</button>`:''}`,onOpen:m=>{$('#collection-form',m).addEventListener('submit',async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.currentTarget));try{const out=await api(existing?`/api/collections/${existing.id}`:'/api/collections',{method:existing?'PUT':'POST',body:JSON.stringify(body)});closeOverlay();toast(existing?'Collection updated.':'Collection created.');location.hash=`#/saved/${existing?.id||out.id}`;}catch(err){toast(err.message,'error')}})}})}
async function editCollection(id){const d=await api(`/api/collections/${id}`);collectionForm(d.collection)}
async function organizeSaved(type,itemId){const d=await api('/api/saved');if(!d.collections.length)return collectionForm();modal({title:'Add to Collection',eyebrow:'PRIVATE ORGANIZATION',size:'sm',body:`<div class="collection-picker">${d.collections.map(c=>`<button data-action="add-to-collection" data-collection-id="${c.id}" data-item-type="${esc(type)}" data-id="${esc(itemId)}"><strong>${esc(c.name)}</strong><small>${c.item_count} items</small></button>`).join('')}</div><button class="button-secondary" data-action="new-collection">+ NEW COLLECTION</button>`})}
async function toggleSave(type,itemId){if(!requireSignIn())return;try{const d=await api('/api/saved/toggle',{method:'POST',body:JSON.stringify({itemType:type,itemId})});toast(d.saved?'Saved privately.':'Removed from Saved.');renderRoute()}catch(err){toast(err.message,'error')}}
async function renderSearch(q,kind='all'){
  setTitle(`Search: ${q}`);$('#search-input').value=q;const hashParts=routeParts(),selected=hashParts[2]||kind||'all',d=await api(`/api/search?q=${encodeURIComponent(q)}&kind=${encodeURIComponent(selected)}`);
  const groups=[['Projects',d.projects, x=>`<a class="search-item" href="#/projects/${x.id}"><strong>${esc(x.title)}</strong><p>${esc(x.description)}</p><small>${esc(x.stage)} · ${esc(x.owner)}</small></a>`],['Build logs',d.buildLogs,x=>`<a class="search-item" href="#/projects/${x.project_id}"><strong>${esc(x.title||x.type)}</strong><p>${esc(x.body)}</p><small>${esc(x.project_title)} · ${esc(x.author)}</small></a>`],['Questions',d.questions,x=>`<a class="search-item" href="#/question/${x.id}"><strong>${esc(x.title)}</strong><p>${esc(x.trying)}</p><small>${esc(x.status)} · ${esc(x.author)}</small></a>`],['Discussions',d.discussions,x=>`<a class="search-item" href="#/discussion/${x.id}"><strong>${esc(x.title)}</strong><p>${esc(x.body)}</p><small>${esc(x.area)} / ${esc(x.category)} · ${esc(x.author)}</small></a>`],['Shop Notes',d.shopNotes,x=>`<div class="search-item"><strong>${esc(x.title)}</strong><p>${esc(x.body)}</p><small>${esc(x.author)}</small></div>`],['Build Alongs',d.buildAlongs,x=>`<a class="search-item" href="#/build-along/${x.id}"><strong>${esc(x.title)}</strong><p>${esc(x.overview)}</p></a>`],['Open Briefs',d.openBriefs,x=>`<a class="search-item" href="#/open-brief/${x.id}"><strong>${esc(x.title)}</strong><p>${esc(x.objective)}</p></a>`],['Library',d.library,x=>`<a class="search-item" href="#/library/${x.id}"><strong>${esc(x.title)}</strong><p>${esc(x.summary)}</p><small>${esc(x.section)} · ${esc(x.type)}</small></a>`],['Field Instruments',d.instruments,x=>`<a class="search-item" href="#/lab/${x.id}"><strong>${esc(x.name)}</strong><p>${esc(x.description)}</p><small>${esc(x.status)} · v${esc(x.version)}</small></a>`],['People',d.people,x=>`<a class="search-item" href="#/bench/${x.id}"><strong>${esc(x.display_name)}</strong><p>${esc(x.bio)}</p><small>${esc(x.city_region||'Location hidden')}</small></a>`],['Maker Crews',d.crews,x=>`<a class="search-item" href="#/crew/${x.id}"><strong>${esc(x.code)} · ${esc(x.name)}</strong><p>${esc(x.description)}</p><small>${esc(x.city_region)} · anchor ${esc(x.anchor_postal_code)}</small></a>`],['GearHead Crew',d.gearhead,x=>`<a class="search-item" href="#/gearhead/${x.id}"><strong>${esc(x.title)}</strong><p>${esc(x.deck)}</p><small>${x.locked?'GEARHEAD CREW ONLY':esc(x.entry_type)}</small></a>`]];
  const total=groups.reduce((n,g)=>n+(g[1]?.length||0),0);
  view.innerHTML=`<div class="view narrow">${pageHead('Search the whole shop',`“${q}”`,`${total} matches in ${selected==='all'?'the workshop':SEARCH_KINDS.find(x=>x[0]===selected)?.[1]||selected}.`)}<div class="filter-bar search-kind-bar">${SEARCH_KINDS.map(([k,label])=>`<a class="${selected===k?'active':''}" href="#/search/${encodeURIComponent(q)}/${k}">${esc(label)}</a>`).join('')}</div><div class="search-results">${groups.filter(g=>selected==='all'||SEARCH_KINDS.find(x=>x[1]===g[0])?.[0]===selected).map(([title,items,render])=>resultGroup(title,(items||[]).map(render).join(''),items?.length||0)).join('')}</div></div>`;
}
function resultGroup(title,items,count){return `<section class="result-group"><h2>${esc(title)} <span class="search-count">${count}</span></h2>${items||'<p class="muted-copy">Nothing on this bench yet.</p>'}</section>`;}

function bomTable(items=[]){
  if(!items.length)return '<p class="muted-copy">No formal BOM. Use the materials list as the starting point.</p>';
  return `<div class="bom-table"><div class="bom-head"><span>Item</span><span>Qty</span><span>Notes</span></div>${items.map(x=>`<div class="bom-row"><strong>${esc(x.item||x)}</strong><span>${esc(x.qty||'—')}</span><span>${esc(x.notes||'')}</span></div>`).join('')}</div>`;
}
