function renderTerms(){
  setTitle('Terms & Community Conduct');
  const version=esc(state.meta.termsVersion||'2026-08-16');
  view.innerHTML=`<div class="view narrow terms-document">${pageHead('HOUSE RULES','Terms & Community Conduct','Practical terms for using THE WORKSHOP. Clear enough to read, serious enough to enforce.')}
    <div class="terms-summary"><div class="eyebrow">THE SHORT VERSION</div><h2>Don’t be an idiot.</h2><p>Make things. Share what you learn. Disagree about ideas without being awful to people. Don’t use the Workshop to hurt, exploit, deceive, harass, or endanger anyone.</p><small>Terms version ${version}</small></div>
    <section class="section legal-copy"><h2>1. Eligibility</h2><p>You must be at least 18 years old to create an account. By creating or continuing to use an account, you confirm that you meet that requirement and that the information you provide is reasonably accurate.</p></section>
    <section class="section legal-copy"><h2>2. Be decent</h2><p>No harassment, hate, threats, stalking, doxxing, predatory behavior, impersonation, targeted abuse, spam, scams, or deliberate disruption. Technical disagreement and blunt critique are welcome; personal attacks are not.</p></section>
    <section class="section legal-copy"><h2>3. Keep it lawful and reasonably safe</h2><p>Do not use THE WORKSHOP to plan, facilitate, encourage, or distribute unlawful activity or malicious content. Making carries real physical risk. You are responsible for your own tools, materials, workspace, protective equipment, procedures, and judgment. Community posts are not a substitute for qualified engineering, medical, legal, safety, or other professional advice.</p></section>
    <section class="section legal-copy"><h2>4. Respect privacy</h2><p>Do not publish another person’s private information without permission. Do not pressure members to disclose home addresses, exact locations, personal contact information, or private meetup details. Crew and meetup privacy controls must be respected.</p></section>
    <section class="section legal-copy"><h2>5. Your work and other people’s work</h2><p>You keep ownership of content you create. By posting it, you give THE WORKSHOP a non-exclusive permission to host, copy, display, format, and distribute that content only as reasonably needed to operate, moderate, back up, and present the service. Only upload material you have the right to share. Respect attribution, licenses, trademarks, copyrights, and other creators’ rights.</p></section>
    <section class="section legal-copy"><h2>6. Moderation</h2><p>THE WORKSHOP may remove or restrict content, limit features, suspend accounts, ban accounts, or permanently anonymize/remove login access when reasonably necessary to protect the community, enforce these terms, respond to abuse, or comply with legal obligations. Moderation decisions may consider context, pattern, severity, safety, and prior behavior.</p></section>
    <section class="section legal-copy"><h2>7. Local meetups and exchanges</h2><p>Maker Crew events, tool help, Scrap Bin exchanges, and other in-person activity are arranged between participants. THE WORKSHOP does not inspect venues, tools, people, materials, or transactions. Use ordinary judgment, protect private addresses, meet in appropriate places, and leave any situation that feels unsafe.</p></section>
    <section class="section legal-copy"><h2>8. Accounts and security</h2><p>Keep your credentials secure and do not share access to your account. You are responsible for activity performed through your account unless you promptly report unauthorized access. Administrators may invalidate sessions or require password resets when account security is in question.</p></section>
    <section class="section legal-copy"><h2>9. Service availability and information quality</h2><p>THE WORKSHOP is provided on an as-available basis. Features may change, break, be removed, or be unavailable. Community information can be incomplete, experimental, outdated, or wrong. Verify anything important before relying on it, especially where safety, money, property, or legal obligations are involved.</p></section>
    <section class="section legal-copy"><h2>10. Responsibility and limits</h2><p>To the extent permitted by applicable law, you use THE WORKSHOP and act on community information at your own risk. The service operator is not responsible for losses arising from another member’s project, advice, meetup, exchange, tool, file, or off-platform conduct. Nothing in these terms excludes rights or responsibilities that cannot legally be excluded.</p></section>
    <section class="section legal-copy"><h2>11. Changes to these terms</h2><p>These terms may be updated as the community or service changes. When a material revision requires renewed agreement, THE WORKSHOP may ask you to accept the new version before continuing to use account features.</p></section>
    <section class="section legal-copy"><h2>12. Reporting problems</h2><p>Use the in-app reporting and moderation tools for harmful content, member conduct, account abuse, or safety concerns. Copyright or other rights complaints should identify the material, the right involved, and enough information for the operator to investigate.</p></section>
    <div class="notice"><strong>Plain-language terms</strong><p>These are intentionally readable community terms. They should still be reviewed by qualified counsel before you rely on them as final production legal terms for a public service.</p></div>
  </div>`;
}
function enforceAccountRequirements(){
  if(!state.me)return;
  if(!state.me.termsCurrentAccepted){setTimeout(showTermsAcceptance,80);return;}
  if(state.me.forcePasswordReset)setTimeout(showForcedPasswordReset,80);
}
function showTermsAcceptance(){
  if(!state.me||state.me.termsCurrentAccepted)return;
  const version=esc(state.meta.termsVersion||'2026-08-16');
  modal({title:'Terms & Community Conduct',eyebrow:'AGREEMENT REQUIRED',size:'sm',body:`<div class="terms-accept-summary"><strong>THE SHORT VERSION: DON’T BE AN IDIOT.</strong><p>Be decent. Be lawful. Make safely. Respect privacy, other people, and their work. Moderators can remove harmful content or accounts.</p><p><a href="#/terms" target="_blank" rel="noopener">READ THE FULL TERMS · VERSION ${version}</a></p></div><form id="terms-accept-form" class="form-grid"><div class="field full"><label class="check-line signup-age-confirm"><input type="checkbox" name="accept" value="yes" required><span>I have read and agree to the current Terms &amp; Community Conduct.</span></label></div><div class="field full"><button class="button" type="submit">AGREE &amp; CONTINUE</button></div><div class="field full"><button class="text-button" type="button" id="terms-logout">LOG OUT INSTEAD</button></div></form>`,onOpen:m=>{$('.close-btn',m).hidden=true;const form=$('#terms-accept-form',m);form.addEventListener('submit',async e=>{e.preventDefault();try{const d=await api('/api/account/terms',{method:'POST',body:JSON.stringify({accept:'yes'})});state.me=d.user;updateUserUI();closeOverlay();toast('Terms accepted. Welcome back to the Workshop.');if(state.me.forcePasswordReset)setTimeout(showForcedPasswordReset,80)}catch(err){toast(err.message,'error')}});$('#terms-logout',m).addEventListener('click',logout);}});
}
function renderAbout(){setTitle('About');view.innerHTML=`<div class="view narrow">${pageHead('Why this exists','A virtual communal workshop','THE WORKSHOP is designed around making, documentation, useful failure, practical questions, and shared craft—not attention metrics.')}
  <div class="feature-card"><div class="feature-copy"><div class="label">The product test</div><h3>Does this help someone make, understand, repair, design, discover, teach, or collaborate?</h3><p>If not, it probably does not belong here.</p></div><div class="feature-art">✦</div></div>
  <section class="section"><div class="grid two"><div class="detail-card"><h3>This build</h3><dl class="detail-list"><dt>Version</dt><dd>v${esc(state.meta.version)}</dd><dt>Frontend</dt><dd>Vanilla web app</dd><dt>Backend</dt><dd>Node.js</dd><dt>Database</dt><dd>SQLite</dd><dt>Mode</dt><dd>${esc(state.meta.mode||'production-ready')}</dd></dl></div><div class="detail-card"><h3>Operations</h3><p style="font-size:12px;line-height:1.6;color:var(--muted)">Moderation console, audit trail, backups, request hardening, security headers, account controls, and deployment health checks are active. PostgreSQL/S3 migration, live video, direct messaging, and later community systems remain future work.</p></div></div></section><section class="section"><div class="detail-card"><div class="eyebrow">HOUSE RULES</div><h3>Terms &amp; Community Conduct</h3><p class="muted-copy">The short version: don’t be an idiot. The longer version explains eligibility, conduct, privacy, safety, ownership, moderation, meetups, and account responsibilities.</p><a class="button-secondary" style="display:inline-grid;place-items:center" href="#/terms">READ THE TERMS</a></div></section>
  </div>`;}

async function renderAdmin(){
  if(!state.me||!['Owner','Administrator','Moderator'].includes(state.me.role)){view.innerHTML=`<div class="view narrow">${pageHead('Restricted bench','Operations Console','Moderator access is required.')}</div>`;return;}
  setTitle('Operations Console');const [o,reports,users]=await Promise.all([api('/api/admin/overview'),api('/api/admin/reports'),api('/api/admin/users')]);
  const canAdmin=['Owner','Administrator'].includes(state.me.role);
  view.innerHTML=`<div class="view">${pageHead('OPERATIONS','Workshop Console','Moderation, account security, member state, backups, and accountable administrative actions.',canAdmin?'<button class="button-secondary" data-action="admin-email">EMAIL DELIVERY</button><button class="button-secondary" data-action="crew-requests-admin">MAKER CREW REQUESTS</button><button class="button" data-action="admin-backup">CREATE BACKUP</button>':'')}
    <div class="admin-stats"><div><strong>${o.stats.users}</strong><span>Members</span></div><div><strong>${o.stats.activeProjects}</strong><span>Active projects</span></div><div><strong>${o.stats.openReports}</strong><span>Open reports</span></div><div><strong>${o.stats.suspended}</strong><span>Restricted accounts</span></div></div>
    <section class="section"><div class="section-head"><h2>Moderation Queue</h2><p>Reports are reviewed, not scored.</p></div>${reports.items.length?`<div class="admin-table">${reports.items.map(adminReportRow).join('')}</div>`:empty('QUEUE CLEAR','Nothing currently needs moderator review.')}</section>
    <section class="section"><div class="section-head"><div><div class="eyebrow">ACCOUNT MANAGEMENT</div><h2>Members</h2></div><p>Password recovery, sessions, roles, restriction, and removal</p></div>${canAdmin?`<div class="admin-account-toolbar"><label class="admin-search"><span>SEARCH ACCOUNTS</span><input id="admin-user-search" type="search" placeholder="Name, email, role, or state"></label><p class="muted-copy">Administrative security actions require a reason and are recorded in the audit trail.</p></div>`:''}<div class="admin-table" id="admin-user-table">${users.items.map(u=>`<div class="admin-row" data-admin-user-row data-search="${esc(`${u.display_name} ${u.email} ${u.role} ${u.account_status||'Active'}`.toLowerCase())}"><div><strong>${esc(u.display_name)}</strong><small>${esc(u.email)} · ${u.project_count} projects · ${u.session_count||0} sessions${u.force_password_reset?' · RESET REQUIRED':''}</small></div><span class="tag">${esc(u.role)}</span><span class="tag">${esc(u.account_status||'Active')}</span>${canAdmin?`<button class="text-button" data-action="admin-user" data-id="${u.id}">MANAGE</button>`:''}</div>`).join('')}</div></section>
    ${canAdmin?`<section class="section"><div class="section-head"><h2>Audit Trail</h2><button class="text-button" data-action="admin-audit">OPEN AUDIT LOG</button></div><p class="muted-copy">Administrative and moderation changes are recorded with actor, target, action, reason, and timestamp.</p></section>`:''}
  </div>`;
  const q=$('#admin-user-search');if(q)q.addEventListener('input',()=>{$$('[data-admin-user-row]').forEach(r=>r.hidden=!r.dataset.search.includes(q.value.trim().toLowerCase()))});
}
async function adminUser(id){
  let d;try{d=await api(`/api/admin/users/${id}/details`)}catch(err){return toast(err.message,'error')}
  const u=d.user,isSelf=state.me?.id===u.id,ownerLocked=u.role==='Owner'&&state.me?.role!=='Owner';
  modal({title:u.display_name,eyebrow:'ACCOUNT MANAGEMENT',body:`<div class="account-admin-summary"><div><strong>${esc(u.email)}</strong><small>Joined ${fmtDate(u.created_at,true)} · ${u.project_count} projects · ${u.session_count} active sessions</small></div><div class="project-tags"><span class="tag">${esc(u.role)}</span><span class="tag">${esc(u.account_status)}</span>${u.force_password_reset?'<span class="tag">PASSWORD RESET REQUIRED</span>':''}${u.anonymized_at?'<span class="tag">ANONYMIZED</span>':''}</div></div>
    <form id="admin-user-form" class="form-grid"><div class="field"><label>Role</label><select name="role" ${ownerLocked?'disabled':''}>${['Member','Supporter','Moderator','Editor','Administrator','Owner'].map(x=>`<option ${u.role===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Account state</label><select name="accountStatus" ${isSelf?'disabled':''}>${['Active','Suspended','Banned','Disabled'].map(x=>`<option ${(u.account_status||'Active')===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Administrative reason / note</label><textarea name="reason" rows="2" placeholder="Required for security or destructive actions.">${esc(u.admin_note||'')}</textarea></div><div class="field full"><button class="button-secondary">SAVE ROLE / STATE</button></div></form>
    <div class="admin-action-grid"><button class="button-secondary" data-account-action="reset-link">EMAIL + GENERATE RESET LINK</button><button class="button-secondary" data-account-action="force-reset" ${isSelf?'disabled':''}>FORCE RESET NEXT LOGIN</button><button class="button-secondary" data-account-action="sessions" ${isSelf?'disabled':''}>SIGN OUT ALL SESSIONS</button><button class="button danger" data-account-action="anonymize" ${isSelf||ownerLocked?'disabled':''}>ANONYMIZE + REMOVE LOGIN</button></div>
    <div class="admin-reset-output" id="admin-reset-output" hidden></div>
    <section class="admin-account-history"><div class="section-head"><h3>Recent Account Audit</h3><p>${d.audits.length} events</p></div>${d.audits.length?d.audits.map(a=>`<div class="admin-history-row"><strong>${esc(a.action)}</strong><span>${fmtDate(a.created_at,true)}</span><small>${esc(a.details?.reason||'')}</small></div>`).join(''):'<p class="muted-copy">No account-level administrative actions recorded.</p>'}</section>`,onOpen:m=>{
      const form=$('#admin-user-form',m);form.addEventListener('submit',async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(form));if(!f.role)f.role=u.role;if(!f.accountStatus)f.accountStatus=u.account_status;try{await api(`/api/admin/users/${id}`,{method:'PUT',body:JSON.stringify(f)});closeOverlay();toast('Member state updated.');renderAdmin()}catch(err){toast(err.message,'error')}});
      $$('[data-account-action]',m).forEach(b=>b.addEventListener('click',async()=>{const action=b.dataset.accountAction;let reason=form.reason.value.trim();if(!reason){form.reason.focus();return toast('Enter an administrative reason first.','error')}if(action==='anonymize'){const confirm=prompt('Permanent privacy removal preserves audit/project history under “Removed member”. Type ANONYMIZE to continue.');if(confirm!=='ANONYMIZE')return;try{await api(`/api/admin/users/${id}/anonymize`,{method:'POST',body:JSON.stringify({reason,confirm})});closeOverlay();toast('Account anonymized and login permanently removed.');renderAdmin()}catch(err){toast(err.message,'error')}return}try{const payload={reason};if(action==='reset-link')payload.invalidateSessions=confirm('Also sign this member out of all current sessions?');const result=await api(`/api/admin/users/${id}/${action}`,{method:'POST',body:JSON.stringify(payload)});if(action==='reset-link'){const out=$('#admin-reset-output',m);out.hidden=false;out.innerHTML=`<strong>ONE-TIME RESET LINK · ${result.expiresMinutes} MINUTES</strong><textarea readonly rows="3">${esc(result.resetUrl)}</textarea><button class="text-button" type="button" id="copy-admin-reset">COPY LINK</button><p>${result.emailDeliveryConfigured?'The reset message was queued for email delivery. The link remains available here as an administrative fallback.':'Email delivery is not configured, so use the link above through a trusted channel.'}</p>`;$('#copy-admin-reset',out).addEventListener('click',()=>navigator.clipboard?.writeText(result.resetUrl).then(()=>toast('Reset link copied.')).catch(()=>toast('Select and copy the link manually.')))}else{toast(action==='force-reset'?'Password reset required; existing sessions revoked.':'Sessions revoked.');closeOverlay();renderAdmin()}}catch(err){toast(err.message,'error')}}));
    }});
}
function adminReportRow(r){return `<div class="admin-row report-row"><div><strong>${esc(r.item_type)} · ${esc(r.reason)}</strong><small>${esc(r.reporter)} · ${fmtDate(r.created_at,true)}</small></div><span class="tag">${esc(r.priority||'Normal')}</span><span class="tag">${esc(r.status)}</span><button class="text-button" data-action="admin-report" data-id="${r.id}">REVIEW</button></div>`}
async function adminReport(id){const d=await api('/api/admin/reports'),r=d.items.find(x=>x.id===id);if(!r)return toast('Report not found.','error');modal({title:'Review Report',eyebrow:`${r.item_type} · ${r.item_id}`,size:'sm',body:`<form id="admin-report-form" class="form-grid"><div class="field"><label>Status</label><select name="status">${['Open','Reviewing','Resolved','Dismissed'].map(x=>`<option ${r.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Priority</label><select name="priority">${['Normal','High','Urgent'].map(x=>`<option ${(r.priority||'Normal')===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Moderator notes</label><textarea name="notes">${esc(r.moderator_notes||'')}</textarea></div><div class="field full"><label>Action</label><select name="action"><option value="">Record review only</option><option>Warn member</option><option>Suspend member</option><option>Ban member</option><option>Remove content</option><option>No action needed</option></select></div><div class="field full"><button class="button">SAVE REVIEW</button></div></form>`,onOpen:m=>$('#admin-report-form',m).addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/admin/reports/${id}`,{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast('Moderation review recorded.');renderAdmin()}catch(err){toast(err.message,'error')}})})}
async function adminEmail(){try{const d=await api('/api/admin/email');const status=d.configured?'READY':'NOT CONFIGURED';modal({title:'Email Delivery',eyebrow:'TRANSACTIONAL NOTIFICATIONS',size:'lg',body:`<div class="grid two"><div class="detail-card"><div class="technical-index">DELIVERY</div><h3>${esc(status)}</h3><dl class="detail-list"><dt>Provider</dt><dd>${esc(d.provider)}</dd><dt>From</dt><dd>${esc(d.from)}</dd><dt>Admin recipient</dt><dd>${esc(d.adminEmail||'Not set')}</dd></dl>${d.configured?'':'<p class="danger-note">Configure WORKSHOP_EMAIL_PROVIDER and provider credentials in Railway before expecting external mail.</p>'}</div><div class="detail-card"><form id="admin-email-settings" class="form-grid"><div class="field full"><label>Administrative notification email</label><input name="adminEmail" type="email" value="${esc(d.adminEmail||'')}" placeholder="mike@greenshoegarage.com"></div><label class="field full"><input type="checkbox" name="emailCrewRequests" ${d.settings.emailCrewRequests?'checked':''}> Email new Maker Crew requests</label><label class="field full"><input type="checkbox" name="emailModerationReports" ${d.settings.emailModerationReports?'checked':''}> Email new moderation reports</label><div class="field full"><button class="button">SAVE EMAIL SETTINGS</button></div></form><button class="button-secondary" data-action="admin-email-test">SEND TEST EMAIL</button></div></div><section class="section"><div class="section-head"><h3>Recent Deliveries</h3><p>Sent, failed, and skipped messages</p></div>${d.recent.length?`<div class="admin-table">${d.recent.map(x=>`<div class="admin-row"><div><strong>${esc(x.subject)}</strong><small>${esc(x.recipient)} · ${fmtDate(x.created_at,true)}${x.error?` · ${esc(x.error)}`:''}</small></div><span class="tag">${esc(x.kind)}</span><span class="tag">${esc(x.status)}</span></div>`).join('')}</div>`:'<p class="muted-copy">No email deliveries recorded yet.</p>'}</section>`,onOpen:m=>{$('#admin-email-settings',m).addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{await api('/api/admin/email',{method:'PUT',body:JSON.stringify({adminEmail:fd.get('adminEmail'),emailCrewRequests:fd.has('emailCrewRequests'),emailModerationReports:fd.has('emailModerationReports')})});closeOverlay();toast('Email settings saved.');adminEmail()}catch(err){toast(err.message,'error')}})}})}catch(err){toast(err.message,'error')}}
async function adminAudit(){const d=await api('/api/admin/audit');modal({title:'Audit Trail',eyebrow:'ACCOUNTABLE OPERATIONS',size:'lg',body:`<div class="audit-list">${d.items.map(a=>`<div class="audit-row"><strong>${esc(a.action)}</strong><span>${esc(a.actor||a.actor_id||'system')}</span><span>${esc(a.target_type||'')} ${esc(a.target_id||'')}</span><time>${fmtDate(a.created_at,true)}</time></div>`).join('')||'<p>No administrative events yet.</p>'}</div>`})}
