function showStart(){
  modal({title:'Start Something',eyebrow:'THERE IS AN EMPTY BENCH OVER THERE',size:'lg',body:`<div class="start-something-v4">
    <div class="start-intro"><span class="technical-index">WHAT ARE YOU STARTING?</span><h3>Start with the thing, not the paperwork.</h3><p>Choose the shape of the work. You can add details, files, collaborators, and metadata after it is on the bench.</p></div>
    <div class="start-grid-v4">
      ${startChoice('new-project','◇','Project','Build something over time.','IDEA → BUILD')}
      ${startChoice('new-experiment','⌁','Experiment','Try something and record what happens.','TRY → OBSERVE')}
      ${startChoice('new-repair','⌇','Repair','Diagnose a problem and bring something back.','FIND → FIX')}
      ${startChoice('new-question','?','Question','Ask the Workshop when you are stuck.','ASK → LEARN')}
      ${startChoice('new-teardown','⌖','Teardown','Take something apart to understand it.','OPEN → UNDERSTAND')}
      ${startChoice('new-critique','△','Design Critique','Ask for another pair of eyes.','SHOW → IMPROVE')}
      ${startChoice('new-showtell','✦','Show & Tell','Share a result, finished or otherwise.','MAKE → SHARE')}
      ${startChoice('new-build-log','▤','Build Log','Continue something already on your bench.','CONTINUE')}
    </div>
    <div class="start-secondary-v4">
      ${startChoice('new-brief-response','→','Open Brief Response','Start from the current design brief.')}
      ${state.me&&['Owner','Administrator','Editor'].includes(state.me.role)?startChoice('new-shop-note','✎','Shop Note','Publish a quick note from the Green Shoe Garage bench.'):''}
    </div>
  </div>`});
}
