function showLogin(){
  modal({title:'Enter the Workshop',eyebrow:'ACCOUNT',size:'sm',body:`<div class="auth-tabs"><button class="button-secondary compact" data-auth-tab="login">SIGN IN</button><button class="button-secondary compact" data-auth-tab="register">CREATE ACCOUNT</button></div><form id="login-form" class="form-grid"><div class="field full"><label>Email</label><input name="email" type="email" required autocomplete="email"></div><div class="field full"><label>Password</label><input name="password" type="password" required autocomplete="current-password"></div><div class="field full"><button class="button" type="submit">ENTER THE WORKSHOP</button></div><div class="field full"><button class="text-button" type="button" data-action="forgot-password">FORGOT PASSWORD</button></div></form><form id="register-form" class="form-grid" hidden><div class="field full"><label>Email</label><input name="email" type="email" required autocomplete="email"></div><div class="field full"><label>Display name</label><input name="displayName" required autocomplete="nickname"></div><div class="field full"><label>Password</label><input name="password" type="password" minlength="10" required autocomplete="new-password"><small class="field-help">At least 10 characters.</small></div><div class="field full"><label class="check-line signup-age-confirm"><input type="checkbox" name="age18" value="yes" required> <span>I confirm that I am 18 years of age or older.</span></label><small class="field-help">You must be 18 or older to create a WORKSHOP account.</small></div><div class="field full"><label class="check-line signup-age-confirm"><input type="checkbox" name="terms" value="yes" required> <span>I agree to the <a href="#/terms" target="_blank" rel="noopener">Terms &amp; Community Conduct</a>.</span></label><small class="field-help">The short version: be decent, be lawful, make safely, respect other people and their work.</small></div><div class="field full"><button class="button" type="submit">CREATE ACCOUNT</button></div></form><div class="dev-auth"><button class="text-button" data-action="dev-login">LOCAL DEV · ENTER AS MIKE</button></div>`,onOpen:m=>{const login=$('#login-form',m),reg=$('#register-form',m);$$('[data-auth-tab]',m).forEach(b=>b.addEventListener('click',()=>{const isReg=b.dataset.authTab==='register';login.hidden=isReg;reg.hidden=!isReg;}));login.addEventListener('submit',async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(login));try{const d=await api('/api/auth/login',{method:'POST',body:JSON.stringify(f)});state.me=d.user;updateUserUI();closeOverlay();toast(`Bench open, ${state.me.displayName}.`);await renderRoute();enforceAccountRequirements();}catch(err){toast(err.message,'error')}});reg.addEventListener('submit',async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(reg));try{const d=await api('/api/auth/register',{method:'POST',body:JSON.stringify(f)});toast('Account created. You can sign in after verification is configured.');if(d.devVerifyToken){await api('/api/auth/verify',{method:'POST',body:JSON.stringify({token:d.devVerifyToken})});toast('Development email verification completed.');login.hidden=false;reg.hidden=true;login.email.value=f.email;} }catch(err){toast(err.message,'error')}});}});
}
