function forgotPassword(){modal({title:'Reset password',eyebrow:'ACCOUNT RECOVERY',size:'sm',body:`<form id="forgot-form" class="form-grid"><div class="field full"><label>Email</label><input name="email" type="email" required></div><div class="field full"><button class="button">REQUEST RESET</button></div></form>`,onOpen:m=>$('#forgot-form',m).addEventListener('submit',async e=>{e.preventDefault();try{const d=await api('/api/auth/forgot',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});if(d.devResetToken){closeOverlay();resetPasswordForm(d.devResetToken)}else{closeOverlay();toast('If that account exists, a reset message has been issued.')}}catch(err){toast(err.message,'error')}})});}
