async function renderResetRoute(token){setTitle('Reset password');view.innerHTML=`<div class="view narrow">${pageHead('ACCOUNT RECOVERY','Choose a new password','This one-time reset link expires after 30 minutes.')}<div class="detail-card"><form id="route-reset-form" class="form-grid"><div class="field full"><label>New password</label><input name="password" type="password" minlength="10" autocomplete="new-password" required></div><div class="field full"><label>Confirm new password</label><input name="confirm" type="password" minlength="10" autocomplete="new-password" required></div><div class="field full"><button class="button">SAVE NEW PASSWORD</button></div></form></div></div>`;$('#route-reset-form').addEventListener('submit',async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));if(f.password!==f.confirm)return toast('Passwords do not match.','error');try{await api('/api/auth/reset',{method:'POST',body:JSON.stringify({token,password:f.password})});toast('Password reset. Sign in with the new password.');location.hash='#/home';setTimeout(showLogin,100)}catch(err){toast(err.message,'error')}})}
function showForcedPasswordReset(){if(!state.me?.forcePasswordReset)return;modal({title:'Password change required',eyebrow:'ACCOUNT SECURITY',size:'sm',body:`<p class="muted-copy">An administrator has required a password change before you continue. Choose a new password of at least 10 characters.</p><form id="forced-reset-form" class="form-grid"><div class="field full"><label>New password</label><input name="newPassword" type="password" minlength="10" autocomplete="new-password" required></div><div class="field full"><label>Confirm new password</label><input name="confirmNewPassword" type="password" minlength="10" autocomplete="new-password" required></div><div class="field full"><button class="button">CHANGE PASSWORD</button></div></form>`,onOpen:m=>{$('.close-btn',m).hidden=true;const form=$('#forced-reset-form',m);form.addEventListener('submit',async e=>{e.preventDefault();try{const d=await api('/api/account/forced-password',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(form)))});state.me=d.user;updateUserUI();closeOverlay();toast('Password changed. Other sessions were signed out.')}catch(err){toast(err.message,'error')}})}})}
