async function inviteCollaborator(pid){if(!requireSignIn())return;try{const d=await api('/api/people');const people=d.people.filter(x=>x.id!==state.me.id);modal({title:'Invite a Collaborator',eyebrow:'SHARED PROJECT',size:'sm',body:`<form id="invite-form" class="form-grid"><div class="field full"><label>Member</label><select name="toUserId" required><option value="">Choose someone…</option>${people.map(p=>`<option value="${esc(p.id)}">${esc(p.display_name)}</option>`).join('')}</select></div><div class="field full"><label>Role</label><select name="role">${['Project Lead','Mechanical','Electronics','Software','Fabrication','Testing','Documentation','Research','Photography','Other'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field full"><label>Message</label><textarea name="message" placeholder="What would you like to work on together?"></textarea></div><div class="field full"><button class="button">SEND INVITATION</button></div></form>`,onOpen:m=>$('#invite-form',m).addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/projects/${pid}/collaboration-invites`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast('Collaboration invitation sent.')}catch(err){toast(err.message,'error')}})});}catch(err){toast(err.message,'error')}}
async function collaborationInviteStatus(id,status){try{await api(`/api/collaboration-invites/${id}`,{method:'PUT',body:JSON.stringify({status})});toast(status==='Accepted'?'You joined the project.':'Invitation declined.');renderRoute()}catch(err){toast(err.message,'error')}}
async function removeCollaborator(pid,uid){if(!confirm('Remove this collaborator from the project? Their existing contributions stay in the project record.'))return;try{await api(`/api/projects/${pid}/collaborators/${uid}`,{method:'DELETE'});toast('Collaboration ended.');renderProject(pid)}catch(err){toast(err.message,'error')}}
async function projectTaskForm(pid,existing=null){const d=await api(`/api/projects/${pid}`),people=[{id:d.project.ownerId,name:d.project.owner},...(d.collaborators||[]).map(x=>({id:x.user_id,name:x.display_name}))],t=existing||{};modal({title:existing?'Edit Task':'Add Project Task',eyebrow:'LIGHTWEIGHT TASKS',size:'sm',body:`<form id="task-form" class="form-grid"><div class="field full"><label>Action</label><input name="title" required value="${esc(t.title||'')}" placeholder="Prototype removable side rail"></div><div class="field"><label>Status</label><select name="status">${['To Do','Doing','Done'].map(x=>`<option ${t.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Assigned to</label><select name="assigneeId"><option value="">Unassigned</option>${people.map(p=>`<option value="${esc(p.id)}" ${t.assignee_id===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field full"><label>Note</label><textarea name="notes">${esc(t.notes||'')}</textarea></div><div class="field full"><button class="button">${existing?'SAVE TASK':'ADD TASK'}</button></div></form>`,onOpen:m=>$('#task-form',m).addEventListener('submit',async e=>{e.preventDefault();try{const body=Object.fromEntries(new FormData(e.currentTarget));await api(existing?`/api/project-tasks/${existing.id}`:`/api/projects/${pid}/tasks`,{method:existing?'PUT':'POST',body:JSON.stringify(body)});closeOverlay();toast(existing?'Task updated.':'Task added.');renderProject(pid)}catch(err){toast(err.message,'error')}})});}
async function editProjectTask(pid,id){const d=await api(`/api/projects/${pid}`),t=(d.tasks||[]).find(x=>x.id===id);if(t)projectTaskForm(pid,t)}
async function advanceTask(pid,id,status){const next=status==='To Do'?'Doing':status==='Doing'?'Done':'To Do';try{await api(`/api/project-tasks/${id}`,{method:'PUT',body:JSON.stringify({status:next})});renderProject(pid)}catch(err){toast(err.message,'error')}}

