async function buildLogForm(pid,failure=false,existing=null){
  if(!requireSignIn())return;
  let projects=[]; if(!pid){try{projects=(await api('/api/projects?mine=1')).projects;}catch(err){return toast(err.message,'error')} if(!projects.length)return projectForm();}
  const d=existing||{}, initialType=d.type||(failure?'Failure':'Build');
  const typeOptions=['Idea','Design','Prototype','Experiment','Test','Failure','Revision','Build','Discovery','Decision','Result','Question'];
  modal({title:existing?'Edit Notebook Entry':failure?'This Didn’t Work':'Add to the Project',eyebrow:failure?'FAILURE IS USEFUL KNOWLEDGE':'PROJECT NOTEBOOK',size:'lg',body:`<form id="log-form" class="form-grid notebook-compose">${!pid?`<div class="field full"><label>Project</label><select name="projectId">${projects.map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('')}</select></div>`:''}
    <div class="field"><label>Entry type</label><select name="type" id="notebook-type">${typeOptions.map(x=>`<option ${initialType===x?'selected':''}>${x}</option>`).join('')}</select></div>
    <div class="field"><label>Short title</label><input name="title" value="${esc(d.title||(failure?'THIS DIDN’T WORK':''))}" placeholder="What changed?"></div>
    <div class="field full notebook-prompt"><div class="compose-cue" id="compose-cue"><strong>${esc(logKindMeta(initialType)[0])}</strong><span>${esc(logKindMeta(initialType)[1])}</span></div><label id="notebook-body-label">${failure?'What were you trying to do? What happened? Why? What next?':'Notebook entry'}</label><textarea name="body" required rows="8" placeholder="Write what happened while it is still fresh.">${esc(d.body||'')}</textarea></div>
    <div class="field full deep-only"><div class="notebook-field-grid evidence-compose"><div class="field"><label>Measurements</label><textarea name="measurements" placeholder="18.4 N · 12.1 V · 3.2 mm…">${esc(d.measurements||'')}</textarea></div><div class="field"><label>Observations</label><textarea name="observations" placeholder="What did you notice?">${esc(d.observations||'')}</textarea></div><div class="field"><label>Test results</label><textarea name="testResults" placeholder="What did the test show?">${esc(d.test_results||'')}</textarea></div><div class="field"><label>Problems</label><textarea name="problems" placeholder="What is still wrong?">${esc(d.problems||'')}</textarea></div><div class="field"><label>Decisions</label><textarea name="decisions" placeholder="What did you decide, and why?">${esc(d.decisions||'')}</textarea></div><div class="field"><label>Questions / next test</label><textarea name="questions" placeholder="What happens next?">${esc(d.questions||'')}</textarea></div></div></div>
    <div class="field full deep-only"><label>Attachment references</label><input name="attachments" value="${esc((d.attachments||[]).join(', '))}" placeholder="drawing-v2.pdf, test-photo.jpg, https://…"><small class="field-help">Reference uploaded project files or useful external evidence.</small></div>
    <div class="field full"><div class="form-actions"><span class="autosave-state" id="draft-state"><i></i><b>UNSAVED</b></span><button class="button">${existing?'SAVE NOTEBOOK ENTRY':failure?'DOCUMENT THE FAILURE':'ADD TO BUILD LOG'}</button></div></div></form>`,onOpen:m=>{const f=$('#log-form',m),key=`workshop-draft-log-${existing?.id||pid||'select'}`,type=$('#notebook-type',m),cue=$('#compose-cue',m),label=$('#notebook-body-label',m);restoreDraft(f,key,{});wireAutosave(f,key);
      const updateCue=()=>{const [a,b]=logKindMeta(type.value);cue.innerHTML=`<strong>${esc(a)}</strong><span>${esc(b)}</span>`;label.textContent=type.value==='Failure'?'What were you trying to do? What happened? Why do you think it happened? What will you try next?':type.value==='Decision'?'Record the decision and the reasoning behind it.':type.value==='Test'?'Describe the test, conditions, and what you learned.':'Notebook entry';}; type.addEventListener('change',updateCue); updateCue();
      f.addEventListener('submit',async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(f)),target=pid||b.projectId;try{if(existing)await api(`/api/projects/${target}/logs/${existing.id}`,{method:'PUT',body:JSON.stringify(b)});else await api(`/api/projects/${target}/logs`,{method:'POST',body:JSON.stringify(b)});localStorage.removeItem(key);closeOverlay();toast(existing?'Notebook entry updated.':b.type==='Failure'?'Failure documented. Good.':'Build log updated.');location.hash=`#/projects/${target}`;renderProject(target);}catch(err){toast(err.message,'error')}});}});
}

