const WORKSHOP_AREAS={
  DESIGN:['Mechanical','Electronics','Software','Industrial Design','User Experience','Materials','Architecture'],
  MAKE:['Machining','3D Printing','Woodworking','Laser Fabrication','Metalworking','Electronics Fabrication','PCB Fabrication','Casting','Textiles','Printmaking','Ceramics','Traditional Crafts'],
  FIX:['Troubleshooting','Repair','Restoration','Reverse Engineering','Diagnostics'],
  THINK:['Engineering Ethics','Design Philosophy','Right to Repair','Appropriate Technology','Sustainability','Craftsmanship','Privacy','Technology and Society'],
  ODDITIES:['Unusual Mechanisms','Obsolete Technology','Strange Components','Beautiful Engineering','Mystery Objects','Forgotten Tools']
};
function chipSection(title,items=[],emptyCopy='Nothing listed yet.'){
  return `<div class="detail-card bench-detail"><h3>${esc(title)}</h3>${items?.length?`<div class="project-tags">${tags(items,30)}</div>`:`<p class="muted-copy">${esc(emptyCopy)}</p>`}</div>`;
}
function craftMark(craft={},memberName='Maker'){
  const level=craft.currentLevel||'';
  const src=level==='master'?'/craft-master.png?v=7.1.1':level==='journeyman'?'/craft-journeyman.png?v=7.1.1':level==='apprentice'?'/craft-apprentice.png?v=7.1.1':'/craft-default-wood.png?v=7.1.1';
  const label=level?`${craft.currentLabel} · ${craft.metal}`:'Craft path in progress';
  return `<div class="craft-mark craft-${esc(level||'neutral')}" role="img" aria-label="${esc(memberName)} · ${esc(label)}" title="${esc(label)}"><img src="${src}" alt=""><span>${esc(level?craft.currentLabel.toUpperCase():'CRAFT PATH')}</span></div>`;
}
function craftPathView(craft={}){
  const levels=craft.levels||[];
  return `<section class="craft-path-section" aria-labelledby="craft-path-title"><div class="editorial-head"><div><span class="section-number">00</span><h2 id="craft-path-title">Craft Path</h2></div><span>SELF-TRACKED PRACTICE · NO POINTS OR LEADERBOARD</span></div><p class="craft-path-intro">Track your own development through documented making, reflection, participation, and teaching. Check an expectation when you believe you have met it; add an optional note or link so your future self can remember the evidence. A level is earned only when every expectation in that level—and every earlier level—is complete.</p><div class="craft-level-grid">${levels.map(level=>`<article class="craft-level-card craft-level-${esc(level.id)} ${level.earned?'earned':''}"><header><img src="${level.id==='master'?'/craft-master.png?v=7.1.1':level.id==='journeyman'?'/craft-journeyman.png?v=7.1.1':'/craft-apprentice.png?v=7.1.1'}" alt=""><div><span class="technical-index">${esc(level.metal.toUpperCase())} LEVEL</span><h3>${esc(level.label)}</h3><p>${esc(level.description)}</p></div><strong>${level.done}/${level.total}</strong></header><div class="craft-requirements">${level.requirements.map(req=>`<div class="craft-requirement ${req.checked?'done':''}" data-craft-row="${esc(req.id)}"><label class="craft-check"><input type="checkbox" data-craft-check="${esc(req.id)}" ${req.checked?'checked':''}><span><strong>${esc(req.title)}</strong><small>${esc(req.expectation)}</small></span></label><div class="craft-evidence-row"><input data-craft-evidence="${esc(req.id)}" value="${esc(req.evidenceNote||'')}" placeholder="Optional evidence note or link"><button class="text-button" data-action="craft-save" data-id="${esc(req.id)}">SAVE</button></div></div>`).join('')}</div>${level.earned?`<footer>✓ ${esc(level.label.toUpperCase())} EARNED</footer>`:`<footer>${level.done} OF ${level.total} EXPECTATIONS COMPLETE</footer>`}</article>`).join('')}</div></section>`;
}
