function discussionCard(t){return `<a class="discussion-row" href="#/discussion/${encodeURIComponent(t.id)}"><div class="discussion-area"><strong>${esc(t.area)}</strong><span>${esc(t.category)}</span></div><div class="discussion-copy"><h3>${esc(t.title)}</h3><p>${esc(t.body)}</p><small>${esc(t.author)}${t.project_title?` · linked to ${esc(t.project_title)}`:''} · ${ago(t.updated_at)}</small></div><div class="discussion-count"><strong>${Number(t.reply_count||0)}</strong><span>${Number(t.reply_count)===1?'reply':'replies'}</span></div></a>`;}
async function renderWorkshop(){
  setTitle('Workshop'); const d=await api('/api/discussions');
  view.innerHTML=`<div class="view">${pageHead('Conversation with a workbench attached','Workshop','Design, make, fix, think, and get pleasantly distracted by oddities.',state.me?`<button class="button" data-action="new-discussion" data-area="DESIGN">+ START DISCUSSION</button>`:`<button class="button" data-action="login">ENTER THE WORKSHOP</button>`)}
    <section class="section workshop-areas"><div class="grid workshop-area-grid">${Object.entries(WORKSHOP_AREAS).map(([area,cats])=>`<article class="workshop-area-card"><div class="label">${area}</div><h3>${area==='DESIGN'?'Figure out what it should be.':area==='MAKE'?'Turn materials into things.':area==='FIX'?'Understand why it stopped working.':area==='THINK'?'Question the choices around the work.':'Bring the strange thing over here.'}</h3><p>${cats.slice(0,5).join(' · ')}</p>${state.me?`<button class="text-button" data-action="new-discussion" data-area="${area}">+ TALK ABOUT ${area}</button>`:''}</article>`).join('')}</div></section>
    <section class="section"><div class="section-head"><h2>Recent Workshop Talk</h2><p>${d.topics.length} conversations</p></div><div class="filter-bar" id="discussion-filters"><button class="active" data-discussion-filter="all">All</button>${Object.keys(WORKSHOP_AREAS).map(a=>`<button data-discussion-filter="${a}">${a}</button>`).join('')}</div><div id="discussion-list">${d.topics.length?d.topics.map(t=>`<div data-discussion-area="${esc(t.area)}">${discussionCard(t)}</div>`).join(''):empty('NOTHING ON THIS BENCH YET','Start a useful discussion, not a performance.')}</div></section>
    <section class="section"><div class="brief-card"><div class="label">Need troubleshooting help?</div><h3>Ask the Workshop</h3><p>The structured question system remains the best place for a concrete problem: what you are trying to do, what you tried, what happened, and what kind of help you need.</p><button class="button-secondary compact" data-action="new-question">ASK THE WORKSHOP →</button></div></section><section class="section"><div class="brief-card"><div class="label">Design review</div><h3>Request Critique</h3><p>Ask for specific, structured feedback on a project: what works, what should be questioned, what someone would try, and what questions remain.</p><div class="head-actions"><a class="button-secondary compact" href="#/critiques">BROWSE CRITIQUES →</a>${state.me?'<button class="button-secondary compact" data-action="new-critique">REQUEST CRITIQUE</button>':''}</div></div></section>
  </div>`;
}
function discussionForm(defaultArea='DESIGN'){
  if(!requireSignIn())return; const area=WORKSHOP_AREAS[defaultArea]?defaultArea:'DESIGN';
  modal({title:'Start a Workshop Discussion',eyebrow:'USEFUL CONVERSATION OVER ENGAGEMENT',size:'lg',body:`<form id="discussion-form" class="form-grid"><div class="field"><label>Area</label><select name="area" id="discussion-area-select">${Object.keys(WORKSHOP_AREAS).map(a=>`<option ${a===area?'selected':''}>${a}</option>`).join('')}</select></div><div class="field"><label>Category</label><select name="category" id="discussion-category-select"></select></div><div class="field full"><label>Topic</label><input name="title" required placeholder="What should we talk through?"></div><div class="field full"><label>Opening note</label><textarea name="body" required placeholder="Show your thinking, context, tradeoffs, or question. @mentions work for simple member handles."></textarea></div><div class="field full"><label>Link one of your projects · optional</label><select name="projectId" id="discussion-project-select"><option value="">No linked project</option></select></div><div class="field full"><div class="form-actions"><span class="autosave-state" id="draft-state"><i></i><b>UNSAVED</b></span><button class="button">PUT IT ON THE WORKSHOP BOARD</button></div></div></form>`,onOpen:async m=>{const f=$('#discussion-form',m),areaSel=$('#discussion-area-select',m),cat=$('#discussion-category-select',m),proj=$('#discussion-project-select',m),key='workshop-draft-discussion'; const fill=()=>{cat.innerHTML=WORKSHOP_AREAS[areaSel.value].map(x=>`<option>${esc(x)}</option>`).join('')};fill();areaSel.addEventListener('change',fill);try{const d=await api('/api/projects?mine=1');proj.innerHTML+=""+d.projects.map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('')}catch{} restoreDraft(f,key,{});wireAutosave(f,key);f.addEventListener('submit',async e=>{e.preventDefault();try{const d=await api('/api/discussions',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(f)))});localStorage.removeItem(key);closeOverlay();toast('Discussion is on the board.');location.hash=`#/discussion/${d.id}`;}catch(err){toast(err.message,'error')}})}});
}
async function renderDiscussion(id){
  const d=await api(`/api/discussions/${encodeURIComponent(id)}`),t=d.topic;setTitle(t.title);
  const children=new Map();d.replies.forEach(r=>{const k=r.parent_id||'';if(!children.has(k))children.set(k,[]);children.get(k).push(r)});
  const replyHtml=(r,nested=false)=>`<article class="discussion-reply ${nested?'nested':''}"><div class="reply-avatar">${esc(r.avatar_seed||initials(r.author))}</div><div><div class="reply-head"><strong>${esc(r.author)}</strong><span>${ago(r.created_at)}</span></div><p>${esc(r.body)}</p><div class="reply-tools">${state.me?`<button class="text-button" data-action="reply-discussion" data-id="${esc(t.id)}" data-parent-id="${esc(r.id)}">REPLY</button><button class="text-button" data-action="report-content" data-item-type="discussion_reply" data-id="${esc(r.id)}">REPORT</button>`:''}</div>${(children.get(r.id)||[]).map(x=>replyHtml(x,true)).join('')}</div></article>`;
  view.innerHTML=`<div class="view narrow"><header class="discussion-topic-head"><div class="eyebrow">${esc(t.area)} · ${esc(t.category)}</div><h1>${esc(t.title)}</h1><div class="topic-byline">${esc(t.author)} · ${fmtDate(t.created_at,true)}</div><p>${esc(t.body)}</p>${t.project_id?`<a class="linked-project" href="#/projects/${t.project_id}">↗ Linked project: ${esc(t.project_title||'Open project')}</a>`:''}<div class="head-actions">${state.me?`<button class="button" data-action="reply-discussion" data-id="${esc(t.id)}">+ REPLY</button><button class="button-secondary" data-action="report-content" data-item-type="discussion_topic" data-id="${esc(t.id)}">REPORT</button>`:`<button class="button" data-action="login">ENTER TO REPLY</button>`}</div></header><section class="section"><div class="section-head"><h2>Workshop Replies</h2><p>${d.replies.length}</p></div><div class="discussion-replies">${(children.get('')||[]).map(x=>replyHtml(x)).join('')||empty('NO REPLIES YET','Add a useful direction, disagreement, question, or example.')}</div></section></div>`;
}
function discussionReplyForm(topicId,parentId=''){
  if(!requireSignIn())return;modal({title:parentId?'Reply to This Note':'Add to the Discussion',eyebrow:'CONSTRUCTIVE DISAGREEMENT IS WELCOME',body:`<form id="reply-form" class="form-grid"><div class="field full"><label>Your reply</label><textarea name="body" required placeholder="Add context, a useful question, an alternative, or something you have actually tried."></textarea><input type="hidden" name="parentId" value="${esc(parentId)}"></div><div class="field full"><button class="button">ADD REPLY</button></div></form>`,onOpen:m=>{$('#reply-form',m).addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/discussions/${topicId}/replies`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast('Added to the discussion.');renderDiscussion(topicId);}catch(err){toast(err.message,'error')}})}});
}
function reportForm(itemType,itemId){
  if(!requireSignIn())return;modal({title:'Report to the Moderation Queue',eyebrow:'REPORT THE PROBLEM, NOT THE PERSON',size:'sm',body:`<form id="report-form" class="form-grid"><div class="field full"><label>Why are you reporting this?</label><select name="reason"><option>Harassment or personal attack</option><option>Hate or discriminatory content</option><option>Spam</option><option>Unsafe encouragement</option><option>Illegal material</option><option>Plagiarism / licensing concern</option><option>Other moderation concern</option></select></div><div class="field full"><p class="muted-copy">This stores a real moderation-queue report. The full moderator console arrives in the administration batch.</p><button class="button">SEND REPORT</button></div></form>`,onOpen:m=>{$('#report-form',m).addEventListener('submit',async e=>{e.preventDefault();try{const reason=new FormData(e.currentTarget).get('reason');await api('/api/reports',{method:'POST',body:JSON.stringify({itemType,itemId,reason})});closeOverlay();toast('Report sent to the moderation queue.');}catch(err){toast(err.message,'error')}})}});
}


// v1.9.0 — Design Critique + Live From the Garage
const CRITIQUE_TYPES=['mechanical design','manufacturability','aesthetics','electronics','usability','accessibility','material choice','software architecture','cost','repairability','sustainability','safety'];
const DESIGN_STATES=['Early Idea','Concept','Design Review','Prototype Review','Pre-Build Review','Final Review'];
function critiqueCard(c){return `<a class="discussion-row" href="#/critique/${esc(c.id)}"><div class="discussion-area"><strong>CRITIQUE</strong><span>${esc(c.design_state)}</span></div><div class="discussion-copy"><h3>${esc(c.project_title)}</h3><p>${esc(c.prompt)}</p><div class="project-tags">${tags(c.feedback_types||[],4)}</div><small>${esc(c.author)} · ${ago(c.updated_at)}</small></div><div class="discussion-count"><strong>${Number(c.response_count||0)}</strong><span>${Number(c.response_count)===1?'response':'responses'}</span></div></a>`}
async function renderCritiques(){setTitle('Design Critique');const d=await api('/api/critiques');view.innerHTML=`<div class="view">${pageHead('CONSTRUCTIVE REVIEW','Design Critique','Ask for the kind of feedback that helps the work move forward.',state.me?'<button class="button" data-action="new-critique">+ REQUEST CRITIQUE</button>':'<button class="button" data-action="login">ENTER THE WORKSHOP</button>')}<section class="section"><div class="section-head"><h2>Open Review Requests</h2><p>No scores. No pile-ons. Specific feedback.</p></div>${d.items.length?`<div class="admin-table">${d.items.map(critiqueCard).join('')}</div>`:empty('NOTHING UP FOR REVIEW','Put a real project on the table and say what kind of scrutiny would help.')}</section></div>`}
async function critiqueForm(projectId=''){
  if(!requireSignIn())return;let projects=[];try{projects=(await api('/api/projects?mine=1')).projects}catch(err){return toast(err.message,'error')}if(!projects.length)return toast('Start a project before requesting critique.','error');
  modal({title:'Request Critique',eyebrow:'ASK FOR THE FEEDBACK YOU ACTUALLY NEED',size:'lg',body:`<form id="critique-form" class="form-grid"><div class="field full"><label>Project</label><select name="projectId">${projects.map(p=>`<option value="${p.id}" ${p.id===projectId?'selected':''}>${esc(p.title)}</option>`).join('')}</select></div><div class="field"><label>Design state</label><select name="designState">${DESIGN_STATES.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field full"><label>What kind of feedback?</label><div class="check-grid">${CRITIQUE_TYPES.map(x=>`<label><input type="checkbox" name="feedbackType" value="${esc(x)}"> ${esc(x)}</label>`).join('')}</div></div><div class="field full"><label>What should people look at?</label><textarea name="prompt" required placeholder="Give enough context to make the critique useful. What decisions are still movable? What are you worried about?"></textarea></div><div class="field full"><button class="button">PUT IT UP FOR CRITIQUE</button></div></form>`,onOpen:m=>$('#critique-form',m).addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),body={projectId:fd.get('projectId'),designState:fd.get('designState'),feedbackTypes:fd.getAll('feedbackType'),prompt:fd.get('prompt')};try{const out=await api('/api/critiques',{method:'POST',body:JSON.stringify(body)});closeOverlay();toast('Critique request is on the table.');location.hash=`#/critique/${out.id}`}catch(err){toast(err.message,'error')}})})
}
async function renderCritique(id){const d=await api(`/api/critiques/${id}`),c=d.critique;setTitle(`Critique · ${c.project_title}`);const mine=state.me&&state.me.id===c.user_id;view.innerHTML=`<div class="view narrow"><header class="discussion-topic-head"><div class="eyebrow">DESIGN CRITIQUE · ${esc(c.design_state)} · ${esc(c.status)}</div><h1>${esc(c.project_title)}</h1><div class="project-tags">${tags(c.feedback_types,12)}</div><p>${esc(c.prompt)}</p><a class="linked-project" href="#/projects/${esc(c.project_id)}">↗ OPEN PROJECT</a><div class="head-actions">${state.me&&c.status==='Open'?`<button class="button" data-action="respond-critique" data-id="${esc(c.id)}">ADD STRUCTURED FEEDBACK</button>`:''}${mine?`<button class="button-secondary" data-action="edit-critique" data-id="${esc(c.id)}">EDIT REQUEST</button>`:''}</div></header><section class="section"><div class="section-head"><h2>Critique</h2><p>${d.responses.length} responses</p></div>${d.responses.length?d.responses.map(r=>`<article class="critique-response"><div class="reply-head"><strong>${esc(r.author)}</strong><span>${ago(r.created_at)}</span></div>${r.works?`<div class="notebook-detail"><strong>WHAT WORKS</strong><p>${esc(r.works)}</p></div>`:''}${r.question?`<div class="notebook-detail"><strong>WHAT I WOULD QUESTION</strong><p>${esc(r.question)}</p></div>`:''}${r.try_next?`<div class="notebook-detail"><strong>WHAT I WOULD TRY</strong><p>${esc(r.try_next)}</p></div>`:''}${r.questions?`<div class="notebook-detail"><strong>QUESTIONS</strong><p>${esc(r.questions)}</p></div>`:''}</article>`).join(''):empty('NO RESPONSES YET','Good critique takes a little thought.')}</section></div>`}
function critiqueResponseForm(id){if(!requireSignIn())return;modal({title:'Structured Critique',eyebrow:'BE SPECIFIC · BE USEFUL · QUESTION THE WORK, NOT THE PERSON',size:'lg',body:`<form id="critique-response-form" class="form-grid"><div class="field full"><label>WHAT WORKS</label><textarea name="works"></textarea></div><div class="field full"><label>WHAT I WOULD QUESTION</label><textarea name="question"></textarea></div><div class="field full"><label>WHAT I WOULD TRY</label><textarea name="tryNext"></textarea></div><div class="field full"><label>QUESTIONS</label><textarea name="questions"></textarea></div><div class="field full"><button class="button">ADD CRITIQUE</button></div></form>`,onOpen:m=>$('#critique-response-form',m).addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/critiques/${id}/responses`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast('Critique added.');renderCritique(id)}catch(err){toast(err.message,'error')}})})}
async function editCritique(id){const {critique:c}=await api(`/api/critiques/${id}`);modal({title:'Edit Critique Request',eyebrow:'KEEP THE REVIEW TARGET CLEAR',size:'lg',body:`<form id="edit-critique-form" class="form-grid"><div class="field"><label>Design state</label><select name="designState">${DESIGN_STATES.map(x=>`<option ${c.design_state===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Status</label><select name="status">${['Open','Closed'].map(x=>`<option ${c.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Feedback types</label><input name="feedbackTypes" value="${esc(c.feedback_types.join(', '))}"></div><div class="field full"><label>Review prompt</label><textarea name="prompt" required>${esc(c.prompt)}</textarea></div><div class="field full"><button class="button">SAVE CRITIQUE REQUEST</button></div></form>`,onOpen:m=>$('#edit-critique-form',m).addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/critiques/${id}`,{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast('Critique request updated.');renderCritique(id)}catch(err){toast(err.message,'error')}})})}
function gearheadTypeLabel(type='Field Note'){return String(type||'Field Note').toUpperCase();}
function gearheadCard(g){return `<a class="gearhead-card ${g.locked?'locked':''}" href="#/gearhead/${encodeURIComponent(g.id)}">${g.heroUrl?`<img src="${esc(imageSrc(g.heroUrl))}" alt="" loading="lazy" decoding="async">`:g.posterUrl?`<img src="${esc(imageSrc(g.posterUrl))}" alt="" loading="lazy" decoding="async">`:''}<div class="gearhead-card-copy"><div class="gearhead-stamp">${g.locked?'GEARHEAD CREW ONLY':'CREW ACCESS'} · ${esc(gearheadTypeLabel(g.entryType))}</div><h3>${esc(g.title)}</h3><p>${esc(g.deck)}</p>${g.runtimeText?`<div class="gearhead-card-meta"><span>${esc(g.runtimeText)}</span></div>`:''}</div></a>`}
