async function renderGearhead(){setTitle('The GearHead Crew');const d=await api('/api/gearhead');const s=d.sections||{};view.innerHTML=`<div class="view gearhead-view"><header class="gearhead-hero"><div><div class="gearhead-stamp large">THE GEARHEAD CREW</div><h1>The people who help keep Green Shoe Garage building.</h1><p>Deeper process, tutorials, shop films, files, early Field Instruments, experiments, and After Hours sessions.</p><strong>${esc(d.principle)}</strong></div><div class="gearhead-access-card">${d.active?`<div class="gearhead-stamp">GEARHEAD CREW ACCESS</div><h2>YOU'RE ON THE CREW.</h2><p>${d.gearhead.since?`Supporting since ${fmtDate(d.gearhead.since)}`:'Thanks for helping keep the shop moving.'}</p>`:`<div class="gearhead-stamp">GEARHEAD CREW ONLY</div><h2>GET CLOSER TO THE WORK.</h2><p>The community remains open. GearHead Crew unlocks deeper Green Shoe Garage material.</p><button class="button" data-action="membership">JOIN THE GEARHEAD CREW</button>`}${d.active?'<a class="button-secondary" href="#/gearhead-vault">FILE VAULT →</a><a class="button-secondary" href="#/gearhead-projects">CREW PROJECTS →</a><a class="button-secondary" href="#/gearhead-contributions">CONTRIBUTIONS →</a><a class="button-secondary" href="#/gearhead-requests">REQUEST FROM THE CREW →</a>':''}<a class="button-secondary" href="#/gearhead-archive">GEARHEAD ARCHIVE →</a>${state.me?'<button class="button-secondary" data-action="membership">MY GEARHEAD CREW</button>':''}${d.canEdit?'<button class="button" data-action="gearhead-quick">POST TO GEARHEAD CREW</button><button class="button-secondary deep-only" data-action="gearhead-studio">GEARHEAD CREW STUDIO</button>':''}</div></header>${d.continueItem?`<section class="gearhead-continue"><div><span class="technical-index">CONTINUE WHERE YOU LEFT OFF</span><h2>${esc(d.continueItem.title)}</h2><p>${esc(d.continueItem.deck)}</p></div><a class="button-secondary" href="#/gearhead/${encodeURIComponent(d.continueItem.id)}">CONTINUE →</a></section>`:''}${gearheadSection('NEW THIS WEEK','LATEST FROM THE SHOP',d.entries||[])}${gearheadSection('DEEP DIVES','TUTORIALS + FULL PROCESS',s.deepDives)}${gearheadSection('SHOP FILMS','LONGER VIDEO',s.shopFilms)}${gearheadSection('BENCH CAM','ROUGH FOOTAGE FROM THE BENCH',s.benchCam)}${gearheadSection('BENCH ROLLS','PHOTO STORIES',s.benchRolls)}${gearheadSection('FIELD NOTES','OBSERVATIONS + BEHIND THE SCENES',s.fieldNotes)}${gearheadSection('FILES FROM THE BENCH','DOWNLOADS',s.downloads)}${gearheadSection('EARLY ACCESS','PREVIEWS + FIELD INSTRUMENTS',s.earlyAccess)}<section class="section"><div class="section-head"><div><div class="technical-index">AFTER HOURS</div><h2>CREW SESSIONS</h2></div></div>${d.afterHours.length?`<div class="gearhead-grid">${d.afterHours.map(e=>`<a class="gearhead-card ${e.locked?'locked':''}" href="#/live/${encodeURIComponent(e.id)}"><div class="gearhead-card-copy"><div class="gearhead-stamp">GEARHEAD CREW ONLY · AFTER HOURS</div><h3>${esc(e.title)}</h3><p>${esc(e.description||'')}</p><div class="gearhead-card-meta"><span>${esc(e.status)}</span><span>${fmtDate(e.starts_at,true)}</span></div></div></a>`).join('')}</div>`:empty('LIGHTS ARE OFF','No After Hours session is scheduled yet.')}</section></div>`;}
function gearheadStepView(s,i,canEdit){return `<article class="deep-dive-step"><header><div><div class="technical-index">STEP ${String(i+1).padStart(2,'0')}</div><h2>${esc(s.title)}</h2></div>${canEdit?`<div class="head-actions deep-only"><button class="text-button" data-action="gearhead-edit-step" data-id="${esc(s.id)}">EDIT</button><button class="text-button danger-text" data-action="gearhead-delete-step" data-id="${esc(s.id)}">REMOVE</button></div>`:''}</header>${s.warning?`<div class="safety-card"><strong>WATCH FOR THIS</strong><p>${esc(s.warning)}</p></div>`:''}<p>${esc(s.body)}</p>${s.image_url?`<img src="${esc(imageSrc(s.image_url))}" alt="" loading="lazy">`:''}${s.media_url?`<p><a class="button-secondary compact" href="${esc(s.media_url)}" target="_blank" rel="noopener">OPEN STEP MEDIA ↗</a></p>`:''}${s.tools?.length?`<div class="step-callout"><strong>TOOLS</strong>${tags(s.tools,12)}</div>`:''}${s.materials?.length?`<div class="step-callout"><strong>MATERIALS</strong>${tags(s.materials,12)}</div>`:''}${s.measurements?`<div class="notebook-detail"><strong>MEASUREMENTS / SETTINGS</strong><p>${esc(s.measurements)}</p></div>`:''}${s.code_text?`<pre class="gearhead-code"><code>${esc(s.code_text)}</code></pre>`:''}${s.safety_note?`<div class="safety-card"><strong>SAFETY NOTE</strong><p>${esc(s.safety_note)}</p></div>`:''}</article>`}
async function renderGearheadEntry(id){setTitle('GearHead Crew');const d=await api(`/api/gearhead/entries/${encodeURIComponent(id)}`),g=d.item;setTitle(g.title);if(d.locked){view.innerHTML=`<div class="view narrow"><article class="gearhead-locked"><div class="gearhead-stamp large">GEARHEAD CREW ONLY</div><h1>${esc(g.title)}</h1><p>${esc(g.deck)}</p>${g.previewMediaUrl?`<img class="gearhead-preview-image" src="${esc(imageSrc(g.previewMediaUrl))}" alt="" decoding="async">`:''}${g.previewText?`<div class="gearhead-public-preview"><span class="technical-index">PUBLIC PREVIEW</span><p>${esc(g.previewText)}</p></div>`:'<div class="locked-lines"><span></span><span></span><span></span></div>'}<p>This material is available to the people helping keep Green Shoe Garage building, experimenting, documenting, and teaching.</p><button class="button" data-action="membership">JOIN THE GEARHEAD CREW</button><a class="text-button" href="#/gearhead">BACK TO THE GEARHEAD CREW</a></article></div>`;return;}const embed=trustedEmbed(g.mediaUrl);view.innerHTML=`<div class="view narrow gearhead-entry"><header><div class="gearhead-stamp large">GEARHEAD CREW ONLY · ${esc(gearheadTypeLabel(g.entryType))}</div><h1>${esc(g.title)}</h1><p>${esc(g.deck)}</p><div class="topic-byline">${esc(g.author)} · ${fmtDate(g.createdAt,true)}${g.runtimeText?` · ${esc(g.runtimeText)}`:''}</div>${d.canEdit?`<div class="head-actions deep-only"><button class="button-secondary" data-action="gearhead-edit" data-id="${esc(g.id)}">EDIT</button>${g.entryType==='Tutorial'?`<button class="button-secondary" data-action="gearhead-add-step" data-id="${esc(g.id)}">+ STEP</button>`:''}${g.entryType==='Bench Roll'?`<button class="button-secondary" data-action="gearhead-add-media" data-id="${esc(g.id)}">+ PHOTO</button>`:''}<button class="button-secondary" data-action="gearhead-upload" data-id="${esc(g.id)}">+ FILE</button><button class="button-secondary" data-action="gearhead-video-upload" data-id="${esc(g.id)}">+ VIDEO</button><button class="button-secondary" data-action="gearhead-duplicate" data-id="${esc(g.id)}">DUPLICATE</button><button class="button-secondary" data-action="gearhead-template-save" data-id="${esc(g.id)}">SAVE TEMPLATE</button></div>`:''}</header>${g.heroUrl?`<img class="gearhead-hero-image" src="${esc(imageSrc(g.heroUrl))}" alt="${esc(g.title)}" decoding="async">`:''}${embed?`<div class="gearhead-video">${g.posterUrl?`<img class="video-poster" src="${esc(imageSrc(g.posterUrl))}" alt="">`:''}<div class="live-player"><iframe src="${esc(embed)}" title="${esc(g.title)}" allowfullscreen></iframe></div></div>`:g.mediaUrl?(g.mediaUrl.startsWith('/gearhead-media/')?`<video class="gearhead-native-video" controls playsinline preload="metadata" ${g.posterUrl?`poster="${esc(g.posterUrl)}"`:''}><source src="${esc(g.mediaUrl)}"></video>`:`<a class="button-secondary" href="${esc(g.mediaUrl)}" target="_blank" rel="noopener">OPEN MEDIA ↗</a>`):''}${g.chapters?.length?`<nav class="video-chapters"><strong>CHAPTERS</strong>${g.chapters.map(x=>`<span>${esc(x)}</span>`).join('')}</nav>`:''}<article class="gearhead-body"><p>${esc(g.body).replace(/\n\n+/g,'</p><p>')}</p></article>${d.media?.filter(m=>m.media_type==='Image').length?`<section class="bench-roll"><div class="section-head"><div><div class="technical-index">BENCH ROLL</div><h2>FROM THE WORKBENCH</h2></div></div><div class="bench-roll-grid">${d.media.filter(m=>m.media_type==='Image').map((m,i)=>`<figure><img src="${esc(imageSrc(m.url))}" alt="${esc(m.caption||`${g.title} image ${i+1}`)}" loading="lazy" decoding="async"><figcaption><span>${String(i+1).padStart(2,'0')}</span>${esc(m.caption||'')}</figcaption></figure>`).join('')}</div></section>`:''}${d.steps.length?`<section class="gearhead-steps">${d.steps.map((s,i)=>gearheadStepView(s,i,d.canEdit)).join('')}</section>`:''}${g.transcript?`<details class="gearhead-transcript"><summary>TRANSCRIPT</summary><p>${esc(g.transcript)}</p></details>`:''}${['Early Access','Field Instrument Preview'].includes(g.entryType)?`<section class="early-access-details"><div class="gearhead-stamp">${esc(g.earlyStatus||'Experimental')}</div>${g.requirements?`<div><strong>REQUIREMENTS</strong><p>${esc(g.requirements)}</p></div>`:''}${g.knownIssues?`<div><strong>KNOWN ISSUES</strong><p>${esc(g.knownIssues)}</p></div>`:''}${g.releaseNotes?`<div><strong>RELEASE NOTES</strong><p>${esc(g.releaseNotes)}</p></div>`:''}${g.publicTargetAt?`<div><strong>PUBLIC TARGET</strong><p>${esc(g.publicTargetAt)}</p></div>`:''}</section><section class="gearhead-feedback-cta"><div><span class="technical-index">EARLY ACCESS FEEDBACK</span><h2>TEST IT. TELL US WHAT HAPPENED.</h2><p>Worked, broke, confusing, feature request—useful evidence beats applause.</p></div><button class="button-secondary" data-action="gearhead-feedback" data-id="${esc(g.id)}">SEND FEEDBACK</button></section>`:''}${d.files.length?`<section class="section"><div class="section-head"><div><div class="technical-index">TAKE THIS WITH YOU</div><h2>FILES FROM THE BENCH</h2></div></div><div class="gearhead-files">${d.files.map(f=>`<a href="${esc(f.url)}" target="_blank" rel="noopener"><strong>${esc(f.logical_name)} · v${f.version}</strong><span>${esc(f.mime_type)} · ${Math.max(1,Math.round(f.size_bytes/1024))} KB</span></a>`).join('')}</div></section>`:''}</div>`;}
function gearheadEntryForm(existing=null,preset={}){if(!state.me||!['Owner','Administrator','Editor'].includes(state.me.role))return toast('Editor access required.','error');const d={...preset,...(existing||{})};modal({title:existing?'Edit GearHead Crew Entry':'New GearHead Crew Entry',eyebrow:'GEARHEAD CREW ONLY',size:'xl',body:`<form id="gearhead-entry-form" class="form-grid"><div class="field full"><label>Title</label><input name="title" required value="${esc(d.title||'')}"></div><div class="field full"><label>Deck</label><textarea name="deck">${esc(d.deck||'')}</textarea></div><div class="field full"><label>Public preview text</label><textarea name="previewText">${esc(d.previewText||'')}</textarea></div><div class="field full"><label>Public preview image / media URL</label><input name="previewMediaUrl" value="${esc(d.previewMediaUrl||'')}"></div><div class="field"><label>Format</label><select name="entryType">${['Tutorial','Shop Film','Bench Cam','Bench Roll','Field Note','Download','Early Access','Field Instrument Preview','Behind the Scenes','Crew Update'].map(v=>`<option ${(d.entryType||'Field Note')===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Status</label><select name="status">${['Draft','Published','Archived'].map(v=>`<option ${(d.status||'Draft')===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field full"><label>Body / introduction</label><textarea name="body" rows="10">${esc(d.body||'')}</textarea></div><div class="field"><label>Hero image URL</label><input name="heroUrl" value="${esc(d.heroUrl||'')}"></div><div class="field"><label>Video / media URL</label><input name="mediaUrl" value="${esc(d.mediaUrl||'')}"></div><div class="field"><label>Video poster URL</label><input name="posterUrl" value="${esc(d.posterUrl||'')}"></div><div class="field"><label>Runtime</label><input name="runtimeText" value="${esc(d.runtimeText||'')}" placeholder="18 min"></div><div class="field full"><label>Video chapters · comma separated</label><input name="chapters" value="${esc((d.chapters||[]).join(', '))}" placeholder="00:00 Setup, 04:20 First cut"></div><div class="field full"><label>Transcript · optional</label><textarea name="transcript" rows="5">${esc(d.transcript||'')}</textarea></div><div class="field full"><label>Bench Roll image URLs · one per line · optional caption after |</label><textarea name="photoUrls" rows="4" placeholder="https://.../photo.jpg | First fixture setup"></textarea></div><div class="field full"><label>Tags</label><input name="tags" value="${esc((d.tags||[]).join(', '))}"></div><div class="field"><label>GearHead-only until</label><input type="datetime-local" name="publicReleaseAt" value="${d.publicReleaseAt?esc(new Date(d.publicReleaseAt).toISOString().slice(0,16)):''}"></div><div class="field"><label>Access</label><select name="accessLevel"><option value="GearHead" ${d.accessLevel!=='Public'?'selected':''}>GearHead Crew Only</option><option value="Public" ${d.accessLevel==='Public'?'selected':''}>Public</option></select></div><div class="field full"><button class="button">${existing?'SAVE ENTRY':'CREATE ENTRY'}</button></div></form>`,onOpen:m=>$('#gearhead-entry-form',m).addEventListener('submit',async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));b.feedbackOpen=Boolean(b.feedbackOpen);b.photoUrls=String(b.photoUrls||'').split(/\n+/).map(x=>x.trim()).filter(Boolean);if(b.publicReleaseAt)b.publicReleaseAt=new Date(b.publicReleaseAt).toISOString();try{const r=await api(existing?`/api/gearhead/entries/${existing.id}`:'/api/gearhead/entries',{method:existing?'PUT':'POST',body:JSON.stringify(b)});closeOverlay();toast(existing?'GearHead entry updated.':'GearHead entry created.');location.hash=`#/gearhead/${existing?.id||r.id}`;}catch(err){toast(err.message,'error')}})})}
function gearheadQuickPublish(){modal({title:'Post to GearHead Crew',eyebrow:'FAST PUBLISHING',size:'lg',body:`<div class="quick-publish-grid">${[['Field Note','QUICK NOTE','A short observation from the shop.'],['Bench Roll','PHOTO SET','A sequence of photos with captions.'],['Bench Cam','VIDEO','Rough footage from the bench.'],['Tutorial','DEEP DIVE','Structured instruction and process.'],['Download','DOWNLOAD','Files with a short explanation.'],['Early Access','EARLY ACCESS','A preview before public release.'],['After Hours','AFTER HOURS','Schedule a Crew-only live session.']].map(([type,label,copy])=>`<button class="quick-publish-card" data-action="gearhead-quick-type" data-type="${esc(type)}"><strong>${esc(label)}</strong><span>${esc(copy)}</span></button>`).join('')}</div>`})}
async function editGearheadEntry(id){const d=await api(`/api/gearhead/entries/${id}`);gearheadEntryForm(d.item)}
function gearheadStepForm(id,existing=null){const s=existing||{};modal({title:existing?'Edit Tutorial Step':'Add Tutorial Step',eyebrow:'DEEP DIVE BUILDER',size:'lg',body:`<form id="gearhead-step-form" class="form-grid"><div class="field"><label>Order</label><input type="number" name="sortOrder" value="${Number(s.sort_order||10)}"></div><div class="field full"><label>Step title</label><input name="title" required value="${esc(s.title||'')}"></div><div class="field full"><label>Instruction / note</label><textarea name="body">${esc(s.body||'')}</textarea></div><div class="field"><label>Image URL</label><input name="imageUrl" value="${esc(s.image_url||'')}"></div><div class="field"><label>Step media URL</label><input name="mediaUrl" value="${esc(s.media_url||'')}"></div><div class="field full"><label>Tools</label><input name="tools" value="${esc((s.tools||[]).join(', '))}"></div><div class="field full"><label>Materials</label><input name="materials" value="${esc((s.materials||[]).join(', '))}"></div><div class="field full"><label>Measurements / settings</label><textarea name="measurements">${esc(s.measurements||'')}</textarea></div><div class="field full"><label>Code / commands</label><textarea name="codeText" rows="5">${esc(s.code_text||'')}</textarea></div><div class="field full"><label>Watch for this</label><textarea name="warning">${esc(s.warning||'')}</textarea></div><div class="field full"><label>Safety note</label><textarea name="safetyNote">${esc(s.safety_note||'')}</textarea></div><div class="field full"><button class="button">${existing?'SAVE STEP':'ADD STEP'}</button></div></form>`,onOpen:m=>$('#gearhead-step-form',m).addEventListener('submit',async e=>{e.preventDefault();await api(existing?`/api/gearhead/steps/${existing.id}`:`/api/gearhead/entries/${id}/steps`,{method:existing?'PUT':'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();renderGearheadEntry(id)})})}
async function editGearheadStep(stepId){const entryId=routeParts()[1],d=await api(`/api/gearhead/entries/${entryId}`),s=d.steps.find(x=>x.id===stepId);if(s)gearheadStepForm(entryId,s)}
async function deleteGearheadStep(stepId){const entryId=routeParts()[1];if(!confirm('Remove this tutorial step?'))return;await api(`/api/gearhead/steps/${stepId}`,{method:'DELETE'});toast('Step removed.');renderGearheadEntry(entryId)}
function gearheadMediaForm(id){modal({title:'Add Bench Roll Photo',eyebrow:'PHOTO SET',size:'md',body:`<form id="gearhead-media-form" class="form-grid"><div class="field full"><label>Upload image</label><input name="file" type="file" accept="image/*" capture="environment"></div><div class="field full"><label>Or image URL</label><input name="url" placeholder="https://..."></div><div class="field"><label>Order</label><input name="sortOrder" type="number" value="10"></div><div class="field full"><label>Caption</label><textarea name="caption"></textarea></div><div class="field full"><button class="button">ADD PHOTO</button></div></form>`,onOpen:m=>$('#gearhead-media-form',m).addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),file=fd.get('file'),url=String(fd.get('url')||'').trim();try{if(file instanceof File&&file.size){const r=await fetch(`/api/gearhead/entries/${id}/media-upload`,{method:'POST',headers:{'Content-Type':file.type||'image/jpeg','X-File-Name':encodeURIComponent(file.name),'X-Caption':encodeURIComponent(fd.get('caption')||''),'X-Sort-Order':String(fd.get('sortOrder')||0)},body:file});const d=await r.json();if(!r.ok)throw new Error(d.error||'Upload failed.');}else if(url){await api(`/api/gearhead/entries/${id}/media`,{method:'POST',body:JSON.stringify({url,caption:fd.get('caption'),sortOrder:fd.get('sortOrder')})});}else throw new Error('Choose an image or add an image URL.');closeOverlay();renderGearheadEntry(id)}catch(err){toast(err.message,'error')}})})}
function gearheadFileUpload(id){modal({title:'Add GearHead Crew File',eyebrow:'FILES FROM THE BENCH',body:`<form id="gearhead-file-form" class="form-grid"><div class="field full"><label>File</label><input type="file" name="file" required></div><div class="field full"><label>Logical name</label><input name="logicalName"></div><div class="field full"><label>Revision note</label><input name="notes"></div><div class="field full"><label>License</label><input name="license"></div><div class="field full"><button class="button">UPLOAD GEARHEAD FILE</button></div></form>`,onOpen:m=>$('#gearhead-file-form',m).addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),file=fd.get('file');if(!(file instanceof File)||!file.size)return toast('Choose a file.','error');const res=await fetch(`/api/gearhead/entries/${id}/files`,{method:'POST',headers:{'Content-Type':file.type||'application/octet-stream','X-File-Name':encodeURIComponent(file.name),'X-Logical-Name':encodeURIComponent(fd.get('logicalName')||file.name),'X-File-Notes':encodeURIComponent(fd.get('notes')||''),'X-File-License':encodeURIComponent(fd.get('license')||'')},body:file});const d=await res.json();if(!res.ok)return toast(d.error||'Upload failed','error');closeOverlay();renderGearheadEntry(id)})})}
async function gearheadStudio(){const [h,a]=await Promise.all([api('/api/gearhead'),api('/api/gearhead/analytics')]);modal({title:'GearHead Crew Studio',eyebrow:'EDITORIAL + OPERATIONS',size:'xl',body:`<div class="studio-layout"><section><div class="studio-head"><div><span>ACTIVE GEARHEADS</span><strong>${a.activeGearheads}</strong></div><div><span>PUBLISHED</span><strong>${a.publishedEntries}</strong></div><div><span>FILES</span><strong>${a.files}</strong></div><div><span>AFTER HOURS</span><strong>${a.upcomingAfterHours}</strong></div></div><button class="button" data-action="gearhead-quick">POST TO GEARHEAD CREW</button><button class="button-secondary" data-action="gearhead-new">FULL ENTRY EDITOR</button><button class="button-secondary" data-action="new-live-event">+ AFTER HOURS EVENT</button><button class="button-secondary" data-action="gearhead-send-digest">SEND GEARHEAD DIGEST</button><button class="button-secondary" data-action="gearhead-studio2">OPEN STUDIO 2.0</button><button class="button-secondary" data-action="gearhead-templates">TEMPLATES</button></section><section>${h.entries.map(x=>`<div class="studio-row"><span>GHC</span><div><strong>${esc(x.title)}</strong><small>${esc(x.entryType)} · ${x.locked?'GearHead Crew Only':'Public'}</small></div><a class="text-button" href="#/gearhead/${encodeURIComponent(x.id)}" data-action="close-overlay">OPEN</a></div>`).join('')}</section></div>`})}

function liveCard(e){return `<a class="project-card live-card ${e.locked?'locked':''}" href="#/live/${esc(e.id)}"><div class="project-visual"><span>${e.event_type==='Project Clinic'?'⌕':e.status==='Live'?'●':'▶'}</span></div><div class="project-body"><div class="kicker-row"><span class="stage-badge">${esc(e.status)}</span><span>${esc(e.event_type)}</span>${e.locked?'<span class="gearhead-stamp">GEARHEAD CREW ONLY</span>':''}</div><h3>${esc(e.title)}</h3><p>${esc(e.description)}</p><div class="project-footer"><span>${fmtDate(e.starts_at,true)}</span><span>${Number(e.comment_count||0)} shop talk</span></div></div></a>`}

async function renderGearheadArchive(){setTitle('GearHead Archive');const d=await api('/api/gearhead/archive');view.innerHTML=`<div class="view gearhead-vault">${pageHead('DIG THROUGH THE DRAWERS','GearHead Archive','Search tutorials, films, Bench Rolls, field notes, downloads, and previews.',`<a class="button-secondary" href="#/gearhead">GEARHEAD HOME →</a>`)}<section class="section"><div class="vault-filter archive-controls"><input id="gearhead-archive-q" placeholder="Search the archive"><select id="gearhead-archive-type"><option value="">All formats</option>${d.types.map(x=>`<option>${esc(x)}</option>`).join('')}</select><select id="gearhead-archive-year"><option value="">All years</option>${d.years.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div id="gearhead-archive-list" class="gearhead-grid">${d.items.map(gearheadCard).join('')||empty('NOTHING IN THE DRAWER','Try a broader search.')}</div></section></div>`;const reload=async()=>{const q=$('#gearhead-archive-q').value.trim(),type=$('#gearhead-archive-type').value,year=$('#gearhead-archive-year').value,r=await api(`/api/gearhead/archive?q=${encodeURIComponent(q)}&type=${encodeURIComponent(type)}&year=${encodeURIComponent(year)}`);$('#gearhead-archive-list').innerHTML=r.items.map(gearheadCard).join('')||empty('NOTHING IN THE DRAWER','Try a broader search.')};let timer;$('#gearhead-archive-q')?.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(reload,220)});$('#gearhead-archive-type')?.addEventListener('change',reload);$('#gearhead-archive-year')?.addEventListener('change',reload)}
async function sendGearheadDigest(){if(!confirm('Send a GearHead Crew digest using each member’s saved digest preference?'))return;try{const r=await api('/api/admin/gearhead/digest',{method:'POST',body:JSON.stringify({days:30})});toast(`GearHead digest queued for ${r.sent} member${r.sent===1?'':'s'}.`)}catch(err){toast(err.message,'error')}}
function gearheadVideoUpload(entryId){modal({title:'Upload GearHead Video',eyebrow:'NATIVE VIDEO · PROTECTED',size:'sm',body:`<form id="gh-video-form" class="form-grid"><div class="field full"><label>Video file</label><input name="file" type="file" accept="video/*" required><small class="field-help">WORKSHOP will inspect runtime and attempt to generate a poster frame.</small></div><div class="field full"><button class="button">UPLOAD VIDEO</button></div></form>`,onOpen:m=>$('#gh-video-form',m).addEventListener('submit',async e=>{e.preventDefault();const file=e.currentTarget.file.files[0];if(!file)return;try{toast('Uploading video…');const r=await fetch(`/api/gearhead/entries/${encodeURIComponent(entryId)}/video-upload`,{method:'POST',headers:{'Content-Type':file.type||'video/mp4','X-File-Name':encodeURIComponent(file.name)},body:file});const d=await r.json();if(!r.ok)throw new Error(d.error||'Upload failed.');closeOverlay();toast(`Video uploaded${d.runtime?` · ${d.runtime}`:''}.`);await renderRoute();}catch(err){toast(err.message,'error')}})})}
async function gearheadSaveTemplate(entryId){const name=prompt('Template name');if(!name)return;try{await api('/api/gearhead/templates',{method:'POST',body:JSON.stringify({entryId,name})});toast('Template saved.')}catch(err){toast(err.message,'error')}}
async function gearheadTemplates(){try{const d=await api('/api/gearhead/templates');modal({title:'GearHead Templates',eyebrow:'REUSE THE STRUCTURE · NOT THE CONTENT',size:'md',body:`<div class="request-board">${d.items.map(t=>`<article class="request-card"><div><span class="gearhead-stamp">${esc(t.entry_type)}</span><h3>${esc(t.name)}</h3><p>${esc(t.description||'Reusable GearHead publishing structure.')}</p></div><button class="button-secondary" data-template-use="${esc(t.id)}">USE TEMPLATE</button></article>`).join('')||'<p class="muted-copy">Save any GearHead entry as a template to start here.</p>'}</div>`,onOpen:m=>$$('[data-template-use]',m).forEach(b=>b.addEventListener('click',async()=>{const title=prompt('New draft title');if(!title)return;try{const r=await api(`/api/gearhead/templates/${b.dataset.templateUse}/create-entry`,{method:'POST',body:JSON.stringify({title})});closeOverlay();location.hash=`#/gearhead/${r.id}`}catch(err){toast(err.message,'error')}}))})}catch(err){toast(err.message,'error')}}
async function renderGearheadVault(){setTitle('GearHead File Vault');if(!state.me){view.innerHTML=`<div class="view narrow">${pageHead('TAKE THIS WITH YOU','GearHead File Vault','Protected, revisioned files from the bench.')}<button class="button" data-action="login">ENTER THE WORKSHOP</button></div>`;return;}try{const d=await api('/api/gearhead/vault');view.innerHTML=`<div class="view gearhead-vault">${pageHead('FILES FROM THE BENCH','GearHead File Vault','Protected downloads tied back to the work that produced them.',`<a class="button-secondary" href="#/gearhead">GEARHEAD HOME →</a>`)}<section class="section"><div class="vault-filter"><input id="vault-q" placeholder="Search files, projects, notes, licenses"><span>${d.items.length} files</span></div><div id="vault-list" class="gearhead-files vault-list">${d.items.map(vaultRow).join('')||empty('THE DRAWER IS EMPTY','GearHead downloads will collect here.')}</div></section></div>`;const q=$('#vault-q');q?.addEventListener('input',()=>{const term=q.value.toLowerCase();$$('[data-vault-row]').forEach(el=>el.hidden=!el.dataset.vaultRow.includes(term))})}catch(err){view.innerHTML=`<div class="view narrow">${pageHead('GEARHEAD CREW ONLY','File Vault',err.message)}<button class="button" data-action="membership">JOIN THE GEARHEAD CREW</button></div>`}}
function vaultRow(f){const key=esc((f.logical_name+' '+f.entry_title+' '+f.notes+' '+f.license).toLowerCase());return `<a class="vault-row" data-vault-row="${key}" href="${esc(f.url)}" target="_blank" rel="noopener"><div><span class="gearhead-stamp">${esc(f.entry_type)}</span><strong>${esc(f.logical_name)} · v${f.version}</strong><small>${esc(f.entry_title)}${f.license?` · ${esc(f.license)}`:''}</small></div><div><span>${Math.max(1,Math.round(f.size_bytes/1024))} KB</span><span>DOWNLOAD ↓</span></div></a>`}
async function renderGearheadRequests(){setTitle('Requests from the Crew');if(!state.me){view.innerHTML=`<div class="view narrow">${pageHead('GEARHEAD CREW ONLY','Request from the Crew','GearHeads can ask for tutorials, files, Field Instruments, and After Hours topics.')}<button class="button" data-action="login">ENTER THE WORKSHOP</button></div>`;return;}try{const d=await api('/api/gearhead/requests');view.innerHTML=`<div class="view narrow">${pageHead('WHAT SHOULD WE OPEN UP NEXT?','Request from the Crew','Ask for something useful. No voting or popularity queue.',`<button class="button" data-action="gearhead-request-new">+ MAKE A REQUEST</button><a class="button-secondary" href="#/gearhead">GEARHEAD HOME →</a>`)}<section class="section"><div class="request-board">${d.items.map(r=>`<article class="request-card"><div><span class="gearhead-stamp">${esc(r.request_type)}</span><h3>${esc(r.title)}</h3><p>${esc(r.details)}</p><small>${esc(r.author)} · ${fmtDate(r.created_at,true)}</small></div><div class="request-status"><strong>${esc(r.status)}</strong>${r.response_note?`<p>${esc(r.response_note)}</p>`:''}${d.canManage?`<button class="text-button" data-action="gearhead-request-edit" data-id="${esc(r.id)}">UPDATE STATUS</button>`:''}</div></article>`).join('')||empty('NOTHING REQUESTED YET','Ask for the tutorial, file, or deep dive that would actually help.')}</div></section></div>`}catch(err){view.innerHTML=`<div class="view narrow">${pageHead('GEARHEAD CREW ONLY','Request from the Crew',err.message)}<button class="button" data-action="membership">JOIN THE GEARHEAD CREW</button></div>`}}
function gearheadRequestForm(){modal({title:'Request from the Crew',eyebrow:'GEARHEAD CREW ONLY',size:'md',body:`<form id="gh-request-form" class="form-grid"><div class="field"><label>Request type</label><select name="requestType">${['Tutorial request','Project deep dive','File request','Tool / process question','Field Instrument request','After Hours topic'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field full"><label>Short title</label><input name="title" required></div><div class="field full"><label>What would make this useful?</label><textarea name="details"></textarea></div><div class="field full"><button class="button">SEND REQUEST</button></div></form>`,onOpen:m=>$('#gh-request-form',m).addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/gearhead/requests',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast('Request is on the Crew board.');renderGearheadRequests()}catch(err){toast(err.message,'error')}})})}
async function gearheadRequestStatus(id){const d=await api('/api/gearhead/requests'),r=d.items.find(x=>x.id===id);if(!r)return;modal({title:'Update Crew Request',eyebrow:'EDITORIAL STATUS',size:'sm',body:`<form id="gh-request-status" class="form-grid"><div class="field full"><label>Status</label><select name="status">${['Considering','On the Bench','Planned','Published','Not Planned'].map(x=>`<option ${r.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Response note</label><textarea name="responseNote">${esc(r.response_note||'')}</textarea></div><div class="field full"><button class="button">SAVE STATUS</button></div></form>`,onOpen:m=>$('#gh-request-status',m).addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/gearhead/requests/${id}`,{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();renderGearheadRequests()}catch(err){toast(err.message,'error')}})})}
function gearheadFeedbackForm(entryId){modal({title:'Early Access Feedback',eyebrow:'TEST → REPORT → IMPROVE',size:'md',body:`<form id="gh-feedback-form" class="form-grid"><div class="field"><label>What kind?</label><select name="feedbackType">${['Worked','Broke','Confusing','Feature request','Other'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Browser / platform</label><input name="platform" placeholder="Safari · iPhone"></div><div class="field full"><label>What happened?</label><textarea name="body" required></textarea></div><div class="field full"><button class="button">SEND FEEDBACK</button></div></form>`,onOpen:m=>$('#gh-feedback-form',m).addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/gearhead/entries/${entryId}/feedback`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast('Feedback recorded. Thanks for testing the rough edges.')}catch(err){toast(err.message,'error')}})})}
async function gearheadRsvp(eventId){try{const d=await api(`/api/live/${eventId}/gearhead-rsvp`);modal({title:'After Hours RSVP',eyebrow:'GEARHEAD CREW ONLY',size:'sm',body:`<form id="gh-rsvp-form" class="form-grid"><div class="field full"><label>Status</label><select name="status">${['Going','Interested','Not Going'].map(x=>`<option ${d.mine?.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label class="check-line"><input type="checkbox" name="reminderRequested" ${d.mine?.reminder_requested!==0?'checked':''}> <span>Remember that I want an event reminder.</span></label></div><div class="field full"><button class="button">SAVE RSVP</button></div></form><p class="field-help">${d.count} Crew member${d.count===1?'':'s'} going or interested.</p>`,onOpen:m=>$('#gh-rsvp-form',m).addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),body={status:fd.get('status'),reminderRequested:fd.get('reminderRequested')==='on'};try{await api(`/api/live/${eventId}/gearhead-rsvp`,{method:'POST',body:JSON.stringify(body)});closeOverlay();toast('After Hours RSVP saved.')}catch(err){toast(err.message,'error')}})})}catch(err){toast(err.message,'error')}}

async function renderLive(){setTitle('Live From the Garage');const d=await api('/api/live'),up=d.items.filter(x=>x.status!=='Archived'),archive=d.items.filter(x=>x.status==='Archived');const canEdit=state.me&&['Owner','Administrator','Editor'].includes(state.me.role);view.innerHTML=`<div class="view">${pageHead('LIVE FROM THE GARAGE','Live','Shop streams, Project Clinics, design reviews, teardowns, demos, and guest maker sessions.',`<a class="button-secondary" href="#/clinic">PROJECT CLINIC →</a>${canEdit?'<button class="button" data-action="new-live-event">+ SCHEDULE EVENT</button>':''}`)}<section class="section"><div class="section-head"><h2>On the Calendar</h2><p>${up.length} upcoming / live</p></div><div class="grid projects">${up.map(liveCard).join('')||empty('THE CAMERA IS OFF','The next live bench session will appear here.')}</div></section><section class="section"><div class="section-head"><h2>Archive</h2><p>Recordings stay connected to the work.</p></div><div class="grid projects">${archive.map(liveCard).join('')||empty('NO ARCHIVE YET','Past sessions will collect here.')}</div></section></div>`}
function trustedEmbed(url=''){try{const u=new URL(url);if(['www.youtube.com','youtube.com','www.youtube-nocookie.com'].includes(u.hostname)){let id='';if(u.pathname.startsWith('/watch'))id=u.searchParams.get('v')||'';if(u.pathname.startsWith('/embed/'))id=u.pathname.split('/')[2]||'';if(id)return `https://www.youtube-nocookie.com/embed/${encodeURIComponent(id)}`;}if(u.hostname==='youtu.be'){const id=u.pathname.slice(1);if(id)return `https://www.youtube-nocookie.com/embed/${encodeURIComponent(id)}`;}if(u.hostname==='player.vimeo.com'&&u.pathname.startsWith('/video/'))return u.href;}catch{}return ''}
async function renderLiveEvent(id){const d=await api(`/api/live/${id}`),e=d.event;setTitle(e.title);const canEdit=state.me&&['Owner','Administrator','Editor'].includes(state.me.role),media=e.status==='Archived'?(e.archive_url||e.stream_url):e.stream_url,embed=trustedEmbed(media);view.innerHTML=`<div class="view narrow"><header class="discussion-topic-head"><div class="eyebrow">${esc(e.event_type)} · ${esc(e.status)}</div><h1>${esc(e.title)}</h1><div class="topic-byline">${esc(e.host)} · ${fmtDate(e.starts_at,true)}</div><p>${esc(e.description)}</p>${e.project_id?`<a class="linked-project" href="#/projects/${esc(e.project_id)}">↗ Linked project: ${esc(e.project_title||'Open project')}</a>`:''}<div class="head-actions">${e.event_type==='After Hours'&&state.me?`<button class="button" data-action="gearhead-rsvp" data-id="${esc(e.id)}">RSVP / REMINDER</button>`:''}${canEdit?`<button class="button-secondary" data-action="edit-live-event" data-id="${esc(e.id)}">EDIT EVENT</button>`:''}</div></header>${media?`<section class="section live-player">${embed?`<iframe src="${esc(embed)}" title="${esc(e.title)}" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen></iframe>`:`<a class="feature-card" href="${esc(media)}" target="_blank" rel="noopener"><div class="feature-copy"><div class="label">${e.status==='Archived'?'RECORDING':'STREAM'}</div><h3>Open video</h3><p>This event uses an external media host that is not embedded directly.</p></div><div class="feature-art">▶</div></a>`}</section>`:''}<section class="section"><div class="section-head"><h2>${e.status==='Archived'?'Session Discussion':'Live Workshop Talk'}</h2><p>${d.comments.length}</p></div><div class="discussion-replies">${d.comments.map(c=>`<article class="discussion-reply"><div class="reply-avatar">${esc(c.avatar_seed||initials(c.author))}</div><div><div class="reply-head"><strong>${esc(c.author)}</strong><span>${ago(c.created_at)}</span></div><p>${esc(c.body)}</p></div></article>`).join('')||empty('QUIET BENCH','The discussion stays with the event and archive.')}</div>${state.me?`<button class="button" data-action="live-comment" data-id="${esc(e.id)}">+ ADD TO THE DISCUSSION</button>`:'<button class="button" data-action="login">ENTER TO JOIN</button>'}</section></div>`}
async function liveEventForm(existing=null){if(!state.me||!['Owner','Administrator','Editor'].includes(state.me.role))return toast('Editor access required.','error');let projects=[];try{projects=(await api('/api/projects')).projects}catch{};const d=existing||{};modal({title:existing?'Edit Live Event':'Schedule Live Event',eyebrow:'LIVE FROM THE GARAGE',size:'lg',body:`<form id="live-event-form" class="form-grid"><div class="field full"><label>Title</label><input name="title" required value="${esc(d.title||'')}"></div><div class="field"><label>Event type</label><select name="eventType">${['Shop Stream','Project Clinic','Build Along','Design Review','Teardown','Q&A','Workshop Tour','Field Instrument Demo','Guest Maker Session','After Hours'].map(x=>`<option ${(d.event_type||'Shop Stream')===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Status</label><select name="status">${['Scheduled','Live','Archived','Cancelled'].map(x=>`<option ${(d.status||'Scheduled')===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Access</label><select name="visibility"><option value="Public" ${(d.visibility||'Public')==='Public'?'selected':''}>Public</option><option value="GearHead" ${d.visibility==='GearHead'?'selected':''}>GEARHEAD CREW ONLY</option></select></div><div class="field full"><label>Description</label><textarea name="description">${esc(d.description||'')}</textarea></div><div class="field"><label>Starts</label><input name="startsAt" type="datetime-local" required value="${d.starts_at?esc(new Date(d.starts_at).toISOString().slice(0,16)):''}"></div><div class="field"><label>Ends · optional</label><input name="endsAt" type="datetime-local" value="${d.ends_at?esc(new Date(d.ends_at).toISOString().slice(0,16)):''}"></div><div class="field full"><label>Related project · optional</label><select name="projectId"><option value="">No linked project</option>${projects.map(p=>`<option value="${p.id}" ${d.project_id===p.id?'selected':''}>${esc(p.title)}</option>`).join('')}</select></div><div class="field full"><label>Stream URL</label><input name="streamUrl" value="${esc(d.stream_url||'')}" placeholder="YouTube or Vimeo URL"></div><div class="field full"><label>Archive URL</label><input name="archiveUrl" value="${esc(d.archive_url||'')}" placeholder="Recording URL once archived"></div><div class="field full"><button class="button">${existing?'SAVE EVENT':'PUT IT ON THE CALENDAR'}</button></div></form>`,onOpen:m=>$('#live-event-form',m).addEventListener('submit',async ev=>{ev.preventDefault();const body=Object.fromEntries(new FormData(ev.currentTarget));for(const k of ['startsAt','endsAt'])if(body[k])body[k]=new Date(body[k]).toISOString();try{const out=await api(existing?`/api/live/${existing.id}`:'/api/live',{method:existing?'PUT':'POST',body:JSON.stringify(body)});closeOverlay();toast(existing?'Live event updated.':'Live event scheduled.');location.hash=`#/live/${existing?.id||out.id}`;renderRoute()}catch(err){toast(err.message,'error')}})})}
async function editLiveEvent(id){const d=await api(`/api/live/${id}`);liveEventForm(d.event)}
function liveCommentForm(id){if(!requireSignIn())return;modal({title:'Add to the Live Discussion',eyebrow:'KEEP IT USEFUL TO THE BENCH',body:`<form id="live-comment-form" class="form-grid"><div class="field full"><label>Your note</label><textarea name="body" required></textarea></div><div class="field full"><button class="button">ADD TO DISCUSSION</button></div></form>`,onOpen:m=>$('#live-comment-form',m).addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/live/${id}/comments`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast('Added to the event discussion.');renderLiveEvent(id)}catch(err){toast(err.message,'error')}})})}



// v2.1.0 — Project Clinic + Skill Exchange
function clinicCard(c){
  return `<a class="discussion-row" href="#/clinic/${esc(c.id)}"><div class="discussion-area"><strong>CLINIC</strong><span>${esc(c.status)}</span></div><div class="discussion-copy"><h3>${esc(c.project_title)}</h3><p>${esc(c.problem)}</p><small>${esc(c.author)}${c.event_title?` · ${esc(c.event_title)}`:''} · ${ago(c.updated_at)}</small></div><div class="discussion-count"><strong>?</strong><span>case</span></div></a>`;
}
async function renderClinics(){
  setTitle('Project Clinic'); const d=await api('/api/clinics');
  const selected=d.items.filter(x=>['Selected','Reviewed'].includes(x.status)), mine=state.me?d.items.filter(x=>x.user_id===state.me.id):[];
  view.innerHTML=`<div class="view">${pageHead('BRING THE STUCK PART TO THE BENCH','Project Clinic','Submit a specific problem, preserve the evidence, and carry the live review back into the project.',state.me?'<button class="button" data-action="new-clinic">+ SUBMIT A PROJECT PROBLEM</button>':'<button class="button" data-action="login">ENTER THE WORKSHOP</button>')}
    <section class="section"><div class="section-head"><h2>Selected / Reviewed Cases</h2><p>Problems chosen for live bench review.</p></div>${selected.length?`<div class="admin-table">${selected.map(clinicCard).join('')}</div>`:empty('NO CASES ON THE CLINIC BENCH','Submitted cases selected for a Project Clinic appear here.')}</section>
    ${state.me?`<section class="section"><div class="section-head"><h2>My Submissions</h2><p>${mine.length}</p></div>${mine.length?`<div class="admin-table">${mine.map(clinicCard).join('')}</div>`:empty('NOTHING SUBMITTED','When a project gets genuinely stuck, bring the evidence.')}</section>`:''}
    ${d.canManage?`<section class="section deep-only"><div class="section-head"><h2>Clinic Queue</h2><p>Editorial / moderator review</p></div><div class="admin-table">${d.items.map(clinicCard).join('')}</div></section>`:''}
  </div>`;
}
async function clinicForm(){
  if(!requireSignIn())return; let projects=[]; try{projects=(await api('/api/projects?mine=1')).projects}catch(err){return toast(err.message,'error')}
  if(!projects.length)return toast('Start a project before submitting it to Project Clinic.','error');
  modal({title:'Submit to Project Clinic',eyebrow:'PROJECT → PROBLEM → EVIDENCE → QUESTION',size:'lg',body:`<form id="clinic-form" class="form-grid"><div class="field full"><label>Project</label><select name="projectId">${projects.map(p=>`<option value="${esc(p.id)}">${esc(p.title)}</option>`).join('')}</select></div><div class="field full"><label>Problem</label><textarea name="problem" required placeholder="What is actually stuck, broken, confusing, or undecided?"></textarea></div><div class="field full"><label>Evidence</label><textarea name="evidence" placeholder="Measurements, observations, images/file references, failure modes, test results."></textarea></div><div class="field full"><label>What have you tried?</label><textarea name="tried"></textarea></div><div class="field full"><label>Specific question</label><textarea name="question" required placeholder="What would be useful to leave the clinic knowing?"></textarea></div><div class="field full"><button class="button">SUBMIT TO PROJECT CLINIC</button></div></form>`,onOpen:m=>$('#clinic-form',m).addEventListener('submit',async e=>{e.preventDefault();try{const out=await api('/api/clinics',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast('Project Clinic submission added.');location.hash=`#/clinic/${out.id}`}catch(err){toast(err.message,'error')}})})
}
async function renderClinic(id){
  const d=await api(`/api/clinics/${id}`),c=d.item;setTitle(`Clinic · ${c.project_title}`);
  view.innerHTML=`<div class="view narrow"><header class="discussion-topic-head"><div class="eyebrow">PROJECT CLINIC · ${esc(c.status)}</div><h1>${esc(c.project_title)}</h1><div class="topic-byline">${esc(c.author)} · ${fmtDate(c.created_at,true)}</div><p>${esc(c.problem)}</p><a class="linked-project" href="#/projects/${esc(c.project_id)}">↗ OPEN PROJECT</a>${c.event_id?`<a class="linked-project" href="#/live/${esc(c.event_id)}">▶ ${esc(c.event_title||'OPEN CLINIC EVENT')}</a>`:''}<div class="head-actions">${d.canManage?`<button class="button" data-action="manage-clinic" data-id="${esc(c.id)}">MANAGE CASE</button>`:''}</div></header>
    <section class="section"><div class="notebook-details">${detailText('Evidence',c.evidence)}${detailText('What has been tried',c.tried)}${detailText('Specific question',c.question)}</div></section>
    ${c.recommendations?`<section class="section"><div class="section-head"><h2>Clinic Recommendations</h2><p>Attached back to the project after review.</p></div><article class="library-body">${esc(c.recommendations).replace(/\n/g,'<br>')}</article>${c.event_archive?`<p><a class="button-secondary" href="${esc(c.event_archive)}" target="_blank" rel="noopener">OPEN RECORDING ↗</a></p>`:''}</section>`:c.status==='Reviewed'?empty('NO RECOMMENDATIONS ATTACHED','The clinic was marked reviewed without written recommendations.'):''}
  </div>`;
}
async function manageClinic(id){
  const d=await api(`/api/clinics/${id}`),c=d.item;let live=[];try{live=(await api('/api/live')).items.filter(x=>x.event_type==='Project Clinic')}catch{}
  modal({title:'Manage Project Clinic Case',eyebrow:'SELECT → REVIEW → ATTACH THE RESULT',size:'lg',body:`<form id="manage-clinic-form" class="form-grid"><div class="field"><label>Status</label><select name="status">${['Submitted','Selected','Reviewed','Declined'].map(x=>`<option ${c.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Clinic event</label><select name="eventId"><option value="">No event yet</option>${live.map(x=>`<option value="${esc(x.id)}" ${c.event_id===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div><div class="field full"><label>Recommendations / outcome</label><textarea name="recommendations" placeholder="What should the maker try, change, measure, or decide next?">${esc(c.recommendations||'')}</textarea></div><div class="field full"><button class="button">SAVE CLINIC OUTCOME</button></div></form>`,onOpen:m=>$('#manage-clinic-form',m).addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/clinics/${id}`,{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast('Clinic case updated.');renderClinic(id)}catch(err){toast(err.message,'error')}})})
}

function skillPersonCard(p){
  const overlap=[...(p.matchGive||[]),...(p.matchReceive||[])];
  return `<article class="person-card"><a href="#/bench/${esc(p.id)}"><div class="person-top"><div class="person-avatar">${esc(p.avatar_seed||initials(p.display_name))}</div><div><h3>${esc(p.display_name)}</h3><div class="region">${esc(p.city_region||'Location hidden')}</div></div></div></a><p>${esc(p.bio||'A member of the workshop.')}</p>${(p.can_help||[]).length?`<div class="notebook-detail"><strong>I CAN HELP WITH</strong><p>${esc(p.can_help.join(', '))}</p></div>`:''}${(p.want_learn||[]).length?`<div class="notebook-detail"><strong>I WANT TO LEARN</strong><p>${esc(p.want_learn.join(', '))}</p></div>`:''}${overlap.length?`<div class="project-tags">${tags(overlap,5)}</div>`:''}${state.me&&state.me.id!==p.id?`<button class="button-secondary compact" data-action="skill-request" data-id="${esc(p.id)}" data-name="${esc(p.display_name)}">CONTACT REQUEST</button>`:''}</article>`;
}
async function renderSkillExchange(){
  setTitle('Skill Exchange'); const d=await api('/api/skill-exchange'); let req={incoming:[],outgoing:[]}; if(state.me)try{req=await api('/api/skill-contact-requests')}catch{}
  view.innerHTML=`<div class="view">${pageHead('HELP MOVES BOTH DIRECTIONS','Skill Exchange','Find useful connections between what people can share and what they want to learn. Contact information stays private.','<a class="button-secondary" href="#/people">PEOPLE →</a>')}
    ${state.me&&d.matches.length?`<section class="section"><div class="section-head"><h2>Useful Crossovers</h2><p>Based only on declared help / learning interests.</p></div><div class="grid people">${d.matches.map(skillPersonCard).join('')}</div></section>`:''}
    <section class="section"><div class="section-head"><h2>Workshop Skills</h2><p>No scores. No expertise ranking.</p></div><div class="field"><input id="skill-filter" placeholder="Filter by skill, topic, or person"></div><div class="grid people" id="skill-grid">${d.people.map(p=>`<div data-skill-text="${esc([p.display_name,p.bio,...(p.skills||[]),...(p.can_help||[]),...(p.want_learn||[])].join(' ').toLowerCase())}">${skillPersonCard(p)}</div>`).join('')}</div></section>
    ${state.me?`<section class="section"><div class="section-head"><h2>Contact Requests</h2><p>Requests do not reveal private email addresses.</p></div><div class="grid two"><article class="brief-card"><div class="label">INCOMING</div>${req.incoming.length?req.incoming.map(r=>`<div class="request-row"><strong>${esc(r.from_name)} · ${esc(r.topic)}</strong><p>${esc(r.message||r.request||'')}</p><small>${esc(r.status)}</small>${r.status==='Pending'?`<div class="head-actions"><button class="button-secondary compact" data-action="skill-request-status" data-id="${r.id}" data-status="Accepted">ACCEPT</button><button class="text-button" data-action="skill-request-status" data-id="${r.id}" data-status="Declined">DECLINE</button></div>`:''}</div>`).join(''):'<p>Nothing waiting.</p>'}</article><article class="brief-card"><div class="label">OUTGOING</div>${req.outgoing.length?req.outgoing.map(r=>`<div class="request-row"><strong>${esc(r.to_name)} · ${esc(r.topic)}</strong><p>${esc(r.message||r.request||'')}</p><small>${esc(r.status)}</small></div>`).join(''):'<p>No requests sent.</p>'}</article></div></section>`:''}
  </div>`;
  const input=$('#skill-filter');if(input)input.addEventListener('input',()=>{const q=input.value.trim().toLowerCase();$$('#skill-grid>[data-skill-text]').forEach(x=>x.hidden=q&&!x.dataset.skillText.includes(q))});
}
