async function renderWeeklyQuestions(){setTitle('Question of the Week');const d=await api('/api/question-of-the-week');view.innerHTML=`<div class="view">${pageHead('ONE GOOD QUESTION · NO STREAKS','Question of the Week','A lightweight prompt for showing, remembering, and talking about how we make.',d.canEdit?'<button class="button deep-only" data-action="new-weekly-question">+ NEW QUESTION</button>':'')}<div class="grid two">${d.items.map(q=>`<a class="brief-card" href="#/weekly/${esc(q.id)}"><div class="label">QUESTION OF THE WEEK</div><h2>${esc(q.prompt)}</h2><p>${q.starts_at?fmtDate(q.starts_at,true):fmtDate(q.created_at,true)}${q.ends_at?` → ${fmtDate(q.ends_at,true)}`:''}</p><div class="project-footer"><span>${q.response_count} responses</span><span>OPEN →</span></div></a>`).join('')||empty('NO QUESTION POSTED','The workshop is between prompts right now.')}</div></div>`}
