function weeklyQuestionForm(existing=null){if(!requireSignIn())return;const q=existing||{};modal({title:existing?'Edit Weekly Question':'New Question of the Week',eyebrow:'LIGHTWEIGHT COMMUNITY PROMPT',size:'lg',body:`<form id="weekly-form" class="form-grid"><div class="field full"><label>Question</label><textarea name="prompt" required>${esc(q.prompt||'')}</textarea></div><div class="field full"><label>Image URL · optional</label><input name="imageUrl" value="${esc(q.image_url||'')}"></div><div class="field"><label>Visibility</label><select name="visibility"><option ${q.visibility!=='Members'?'selected':''}>Public</option><option ${q.visibility==='Members'?'selected':''}>Members</option></select></div><div class="field"><label>Status</label><select name="status"><option ${q.status!=='Draft'?'selected':''}>Published</option><option ${q.status==='Draft'?'selected':''}>Draft</option></select></div><div class="field"><label>Starts</label><input type="date" name="startsAt" value="${esc((q.starts_at||'').slice(0,10))}"></div><div class="field"><label>Ends</label><input type="date" name="endsAt" value="${esc((q.ends_at||'').slice(0,10))}"></div><div class="field full"><button class="button">${existing?'SAVE QUESTION':'POST QUESTION'}</button></div></form>`,onOpen:m=>$('#weekly-form',m).addEventListener('submit',async e=>{e.preventDefault();try{const out=await api(existing?`/api/question-of-the-week/${existing.id}`:'/api/question-of-the-week',{method:existing?'PUT':'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast(existing?'Question updated.':'Question posted.');location.hash=`#/weekly/${existing?.id||out.id}`}catch(err){toast(err.message,'error')}})})}
