function sessionStatusClass(x='Draft'){return `session-${String(x).toLowerCase().replace(/\s+/g,'-')}`}
function assignmentCard(a){return `<a class="assignment-card" href="#/assignment/${encodeURIComponent(a.id)}"><div class="assignment-number">${String(Number(a.sort_order||0)).padStart(2,'0')}</div><div><div class="technical-index">${esc(a.status)}${a.estimated_time?` · ${esc(a.estimated_time)}`:''}</div><h3>${esc(a.title)}</h3><p>${esc(a.purpose||a.brief)}</p><div class="assignment-counts"><span>${Number(a.project_count||0)} projects</span><span>${Number(a.submission_count||0)} showed work</span></div></div></a>`}
async function renderSessions(){setTitle('Sessions');const d=await api('/api/sessions');view.innerHTML=`<div class="view sessions-view">${pageHead('Green Shoe Garage programs','WORKSHOP SESSIONS','A Session gives the shop a temporary shared question. Do the work, document it, and see what other benches discover.',d.canEdit?'<button class="button deep-only" data-action="new-session">NEW SESSION</button>':'')}<div class="session-list">${d.items.length?d.items.map(s=>`<a class="session-card ${sessionStatusClass(s.status)}" href="#/session/${encodeURIComponent(s.id)}"><div class="technical-index">${esc(s.status)} · ${esc(s.theme||'WORKSHOP SESSION')}</div><h2>${esc(s.title)}</h2><p>${esc(s.description)}</p><div class="session-stats"><span>${s.assignments.length} assignments</span><span>${s.projectCount} projects</span><span>${s.submissionCount} work records</span></div><span class="session-open">ENTER SESSION →</span></a>`).join(''):empty('No Sessions yet','The shop is between programs.')}</div></div>`}
async function renderSession(id){setTitle('Session');const d=await api(`/api/sessions/${encodeURIComponent(id)}`),s=d.item;setTitle(s.title);const liveIds=[...new Set(s.assignments.map(a=>a.live_event_id).filter(Boolean))];view.innerHTML=`<div class="view session-view"><header class="session-hero"><div class="technical-index">${esc(s.status)} · ${fmtDate(s.starts_at,true)}${s.ends_at?` → ${fmtDate(s.ends_at,true)}`:''}</div><h1>${esc(s.title)}</h1><h2>${esc(s.theme)}</h2><p>${esc(s.description)}</p><div class="session-stats"><span>${s.assignments.length} assignments</span><span>${s.projectCount} projects started</span><span>${s.submissionCount} showed the work</span></div>${d.canEdit?`<div class="head-actions deep-only"><button class="button-secondary" data-action="edit-session" data-id="${esc(s.id)}">EDIT SESSION</button><button class="button" data-action="new-assignment" data-id="${esc(s.id)}">ADD ASSIGNMENT</button><button class="button-secondary" data-action="session-studio" data-id="${esc(s.id)}">SESSION STUDIO</button></div>`:''}</header><section class="session-section"><div class="section-kicker">ASSIGNMENTS</div><div class="assignment-list">${s.assignments.map(assignmentCard).join('')||empty('No assignments yet','The Session brief is being prepared.')}</div></section>${s.resources.length?`<section class="session-section"><div class="section-kicker">REFERENCE MATERIAL</div><div class="resource-grid">${s.resources.map(x=>`<a class="resource-card" href="#/library/${encodeURIComponent(x.id)}"><div class="technical-index">${esc(x.type)} · ${esc(x.section)}</div><h3>${esc(x.title)}</h3><p>${esc(x.summary)}</p></a>`).join('')}</div></section>`:''}${s.wall_exhibition_id?`<section class="session-section final-exhibition"><div class="section-kicker">FINAL EXHIBITION</div><h2>THE WORK GOES ON THE WALL.</h2><a class="button-secondary" href="#/wall/${encodeURIComponent(s.wall_exhibition_id)}">VIEW EXHIBITION →</a></section>`:''}</div>`}
async function renderAssignment(id){setTitle('Assignment');const d=await api(`/api/assignments/${encodeURIComponent(id)}`),a=d.item;setTitle(a.title);const mine=d.myProject;view.innerHTML=`<div class="view assignment-view"><header class="assignment-hero"><div class="assignment-number huge">${String(Number(a.sort_order||0)).padStart(2,'0')}</div><div><div class="technical-index"><a href="#/session/${encodeURIComponent(a.session.id)}">${esc(a.session.title)}</a> · ${esc(a.status)}</div><h1>${esc(a.title)}</h1><p class="assignment-purpose">${esc(a.purpose)}</p></div></header><div class="assignment-layout"><main><section class="assignment-brief"><div class="section-kicker">THE BRIEF</div><p>${esc(a.brief)}</p></section>${a.constraints.length?`<section class="assignment-box"><h3>CONSTRAINTS</h3><ul>${a.constraints.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`:''}${a.optionalConstraints.length?`<section class="assignment-box quiet"><h3>OPTIONAL CONSTRAINTS</h3><ul>${a.optionalConstraints.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`:''}${a.safety_notes?`<section class="safety-card"><strong>SAFETY NOTES</strong><p>${esc(a.safety_notes)}</p></section>`:''}${a.projects.length?`<section class="session-section"><div class="section-kicker">WORK FROM THE WORKSHOP</div><div class="project-grid">${a.projects.slice(0,8).map(projectCard).join('')}</div></section>`:''}</main><aside class="assignment-actions"><div class="technical-index">DO THE WORK</div>${!state.me?'<button class="button" data-action="login">SIGN IN TO START</button>':mine?`<a class="button" href="#/projects/${encodeURIComponent(mine.id)}">OPEN MY PROJECT →</a>${mine.confirmation_code?`<div class="work-receipt mini"><span>WORK RECORDED</span><strong>${esc(mine.confirmation_code)}</strong></div>`:`<button class="button-secondary" data-action="show-work" data-id="${esc(a.id)}" data-project-id="${esc(mine.id)}">SHOW THE WORK</button>`}<button class="text-button" data-action="walk-benches" data-id="${esc(a.id)}">WALK THE BENCHES →</button>`:`<button class="button" data-action="start-assignment" data-id="${esc(a.id)}">START ASSIGNMENT</button>`}${a.estimated_time?`<dl><dt>Expected time</dt><dd>${esc(a.estimated_time)}</dd></dl>`:''}${a.suggestedTools.length?`<div><span class="technical-index">TOOLS</span>${tags(a.suggestedTools,8)}</div>`:''}${a.suggestedMaterials.length?`<div><span class="technical-index">MATERIALS</span>${tags(a.suggestedMaterials,8)}</div>`:''}${d.canEdit?`<button class="text-button deep-only" data-action="edit-assignment" data-id="${esc(a.id)}">EDIT ASSIGNMENT</button>`:''}</aside></div></div>`}
function sessionForm(existing=null){if(!requireSignIn())return;const d=existing||{};modal({title:existing?'Edit Session':'New Session',eyebrow:'SESSION STUDIO',size:'lg',body:`<form id="session-form" class="form-grid"><div class="field full"><label>Session title</label><input name="title" required value="${esc(d.title||'')}"></div><div class="field full"><label>Theme</label><input name="theme" value="${esc(d.theme||'')}"></div><div class="field"><label>Access</label><select name="visibility"><option value="Public" ${(d.visibility||'Public')==='Public'?'selected':''}>Public</option><option value="GearHead" ${d.visibility==='GearHead'?'selected':''}>GEARHEAD CREW ONLY</option></select></div><div class="field full"><label>Description</label><textarea name="description">${esc(d.description||'')}</textarea></div><div class="field"><label>Status</label><select name="status">${['Draft','Upcoming','Active','Complete','Archived'].map(x=>`<option ${d.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Visibility</label><select name="visibility">${['Public','Members'].map(x=>`<option ${d.visibility===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Starts</label><input type="date" name="startsAt" value="${esc((d.starts_at||'').slice(0,10))}"></div><div class="field"><label>Ends</label><input type="date" name="endsAt" value="${esc((d.ends_at||'').slice(0,10))}"></div><div class="field full"><label>Final Wall exhibition ID (optional)</label><input name="wallExhibitionId" value="${esc(d.wall_exhibition_id||'')}"></div><div class="field full"><button class="button">${existing?'SAVE SESSION':'CREATE SESSION'}</button></div></form>`,onOpen:m=>$('#session-form',m).addEventListener('submit',async e=>{e.preventDefault();try{const body=Object.fromEntries(new FormData(e.currentTarget));const r=await api(existing?`/api/sessions/${existing.id}`:'/api/sessions',{method:existing?'PUT':'POST',body:JSON.stringify(body)});closeOverlay();toast(existing?'Session updated.':'Session created.');location.hash=`#/session/${existing?.id||r.id}`}catch(err){toast(err.message,'error')}})})}
async function editSession(id){const d=await api(`/api/sessions/${id}`);sessionForm(d.item)}
function assignmentForm(sessionId,existing=null){if(!requireSignIn())return;const d=existing||{};modal({title:existing?'Edit Assignment':'Add Assignment',eyebrow:'SESSION STUDIO',size:'lg',body:`<form id="assignment-form" class="form-grid"><div class="field full"><label>Assignment title</label><input name="title" required value="${esc(d.title||'')}"></div><div class="field full"><label>Purpose</label><input name="purpose" value="${esc(d.purpose||'')}"></div><div class="field full"><label>Brief</label><textarea name="brief" required>${esc(d.brief||'')}</textarea></div><div class="field full"><label>Constraints (comma or line separated)</label><textarea name="constraints">${esc((d.constraints||[]).join('\n'))}</textarea></div><div class="field full"><label>Optional constraints</label><textarea name="optionalConstraints">${esc((d.optionalConstraints||[]).join('\n'))}</textarea></div><div class="field"><label>Suggested tools</label><input name="suggestedTools" value="${esc((d.suggestedTools||[]).join(', '))}"></div><div class="field"><label>Suggested materials</label><input name="suggestedMaterials" value="${esc((d.suggestedMaterials||[]).join(', '))}"></div><div class="field"><label>Expected time</label><input name="estimatedTime" value="${esc(d.estimated_time||'')}"></div><div class="field"><label>Order</label><input type="number" name="sortOrder" min="1" value="${esc(d.sort_order||'')}"></div><div class="field full"><label>Safety notes</label><textarea name="safetyNotes">${esc(d.safety_notes||'')}</textarea></div><div class="field"><label>Release date</label><input type="date" name="releaseAt" value="${esc((d.release_at||'').slice(0,10))}"></div><div class="field"><label>Due date (soft)</label><input type="date" name="dueAt" value="${esc((d.due_at||'').slice(0,10))}"></div><div class="field"><label>Status</label><select name="status">${['Draft','Published','Archived'].map(x=>`<option ${d.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><button class="button">${existing?'SAVE ASSIGNMENT':'ADD ASSIGNMENT'}</button></div></form>`,onOpen:m=>$('#assignment-form',m).addEventListener('submit',async e=>{e.preventDefault();try{const body=Object.fromEntries(new FormData(e.currentTarget));const r=await api(existing?`/api/assignments/${existing.id}`:`/api/sessions/${sessionId}/assignments`,{method:existing?'PUT':'POST',body:JSON.stringify(body)});closeOverlay();toast(existing?'Assignment updated.':'Assignment added.');location.hash=`#/session/${encodeURIComponent(sessionId||existing.session_id)}`}catch(err){toast(err.message,'error')}})})}
async function editAssignment(id){const d=await api(`/api/assignments/${id}`);assignmentForm(d.item.session_id,d.item)}
async function startAssignment(id){if(!requireSignIn())return;try{const r=await api(`/api/assignments/${id}/start`,{method:'POST',body:JSON.stringify({})});toast(r.existing?'Your Assignment project is already on the bench.':'Assignment project started.');location.hash=`#/projects/${r.project.id}`}catch(err){toast(err.message,'error')}}
function showWorkForm(assignmentId,projectId){modal({title:'Show the Work',eyebrow:'DO → DOCUMENT → REFLECT',size:'md',body:`<form id="show-work-form" class="form-grid"><div class="field full"><label>What did you make or do?</label><textarea name="did" required></textarea></div><div class="field full"><label>What happened?</label><textarea name="happened"></textarea></div><div class="field full"><label>What did you learn?</label><textarea name="learned" required></textarea></div><div class="field full"><label>What would you change next time?</label><textarea name="changeNext"></textarea></div><div class="field full"><label>Primary image URL (optional)</label><input name="imageUrl" placeholder="Paste an uploaded/image URL"></div><input type="hidden" name="projectId" value="${esc(projectId)}"><div class="field full"><button class="button">RECORD THE WORK</button></div></form>`,onOpen:m=>$('#show-work-form',m).addEventListener('submit',async e=>{e.preventDefault();try{const r=await api(`/api/assignments/${assignmentId}/show-work`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();modal({title:'Work Recorded',eyebrow:'THE WORKSHOP',size:'sm',body:`<div class="work-receipt"><span>WORK RECORDED</span><strong>${esc(r.confirmationCode)}</strong><p>Your reflection is also preserved in the Project notebook.</p><a class="button" href="#/projects/${encodeURIComponent(projectId)}" data-action="close-overlay">OPEN PROJECT</a></div>`})}catch(err){toast(err.message,'error')}})})}
async function walkBenches(assignmentId){if(!requireSignIn())return;try{const d=await api(`/api/assignments/${assignmentId}/benches`);modal({title:'Walk the Benches',eyebrow:'LOOK CLOSELY · LEARN SOMETHING',size:'xl',body:d.projects.length?`<div class="walk-grid">${d.projects.map(p=>`<article class="walk-project">${projectCard(p)}<button class="button-secondary" data-action="peer-reflection" data-assignment-id="${esc(assignmentId)}" data-id="${esc(p.id)}">WHAT DID THIS TEACH YOU?</button></article>`).join('')}</div>`:empty('Nothing else on the benches yet','Come back after more makers have shown their work.')})}catch(err){toast(err.message,'error')}}
function peerReflectionForm(assignmentId,projectId){modal({title:'What did this teach you?',eyebrow:'WALK THE BENCHES',size:'sm',body:`<form id="reflection-form" class="form-grid"><div class="field full"><label>Recognition</label><select name="recognition">${['Useful Technique','Clever Use of Materials','Strong Documentation','Interesting Failure','I Want to Try This','I Have a Suggestion'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field full"><label>Optional note</label><textarea name="body" placeholder="What specifically was useful or interesting?"></textarea></div><input type="hidden" name="projectId" value="${esc(projectId)}"><div class="field full"><button class="button">LEAVE A NOTE</button></div></form>`,onOpen:m=>$('#reflection-form',m).addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/assignments/${assignmentId}/reflections`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast('Bench note shared. No score was created.')}catch(err){toast(err.message,'error')}})})}
async function renderMakerId(uid=''){setTitle('Maker ID');const d=await api(`/api/maker-id${uid?`/${encodeURIComponent(uid)}`:''}`),m=d.member;view.innerHTML=`<div class="view maker-id-view"><article class="maker-id-card"><header><div class="maker-id-mark"><span class="workshop-mark" aria-hidden="true"></span></div><div><span>GREEN SHOE GARAGE</span><strong>THE WORKSHOP</strong></div></header><div class="maker-id-name"><div class="avatar xl">${esc(initials(m.displayName))}</div><div><div class="technical-index">MAKER ID · MEMBER SINCE ${new Date(m.createdAt||Date.now()).getFullYear()}</div><h1>${esc(m.displayName)}</h1><p>${esc(m.cityRegion||'')}</p></div></div>${d.crew?`<section><span class="maker-id-label">LOCAL CREW</span><a class="maker-id-crew" href="#/crew/${encodeURIComponent(d.crew.id)}"><strong>${esc(d.crew.code)}</strong><span>${esc(d.crew.name)}${d.crew.cityRegion?` · ${esc(d.crew.cityRegion)}`:''}</span></a></section>`:''}${m.supporter?`<section><span class="maker-id-label">GEARHEAD CREW</span><strong>Supporting Green Shoe Garage</strong></section>`:''}<section><span class="maker-id-label">PRACTICES</span><div class="tag-row">${tags(m.skills||[],12)}</div></section>${d.currentProject?`<section><span class="maker-id-label">CURRENTLY ON THE BENCH</span><a class="maker-id-project" href="#/projects/${encodeURIComponent(d.currentProject.id)}">${esc(d.currentProject.title)} <span>${esc(d.currentProject.stage)}</span></a></section>`:''}<section><span class="maker-id-label">WORKSHOP PARTICIPATION</span><div class="maker-id-metrics"><div><strong>${d.participation.assignmentsStarted}</strong><span>Assignments started</span></div><div><strong>${d.participation.showedWork}</strong><span>Showed the work</span></div><div><strong>${d.participation.benchWalks}</strong><span>Benches walked</span></div><div><strong>${d.participation.buildAlongs+d.participation.openBriefs}</strong><span>Build Alongs + Briefs</span></div></div>${d.sessions.length?`<div class="maker-session-list">${d.sessions.map(s=>`<a href="#/session/${encodeURIComponent(s.id)}"><strong>${esc(s.title)}</strong><span>${esc(s.theme)}</span></a>`).join('')}</div>`:''}</section><footer><span>PARTICIPATION, NOT RANK.</span><span>THE WORKSHOP · GREEN SHOE GARAGE</span></footer></article></div>`}
async function sessionStudio(id){const [sd,lib,live,wall]=await Promise.all([api(`/api/sessions/${id}`),api('/api/library'),api('/api/live'),api('/api/wall')]);const s=sd.item;modal({title:'Session Studio',eyebrow:'EDITORIAL WORKBENCH',size:'xl',body:`<div class="studio-layout"><section><div class="technical-index">SESSION</div><h2>${esc(s.title)}</h2><p>${esc(s.theme)}</p><button class="button-secondary" data-action="edit-session" data-id="${esc(s.id)}">EDIT SESSION</button></section><section><div class="studio-head"><div><span>ASSIGNMENTS</span><strong>${s.assignments.length}</strong></div><button class="button" data-action="new-assignment" data-id="${esc(s.id)}">ADD</button></div>${s.assignments.map(a=>`<div class="studio-row"><span>${String(a.sort_order).padStart(2,'0')}</span><div><strong>${esc(a.title)}</strong><small>${esc(a.status)} · ${a.project_count} projects</small></div><button class="text-button" data-action="edit-assignment" data-id="${esc(a.id)}">EDIT</button></div>`).join('')}</section><section><div class="technical-index">RESOURCES</div>${s.resources.map(r=>`<div class="studio-row"><span>↗</span><div><strong>${esc(r.title)}</strong><small>${esc(r.section)}</small></div></div>`).join('')||'<p class="muted-copy">No resources attached yet.</p>'}<form id="studio-resource" class="inline-form"><select name="libraryItemId">${lib.items.filter(x=>!s.resources.some(r=>r.id===x.id)).map(x=>`<option value="${esc(x.id)}">${esc(x.title)}</option>`).join('')}</select><button class="button-secondary">ATTACH RESOURCE</button></form></section><section><div class="technical-index">FINAL EXHIBITION</div>${s.wall_exhibition_id?`<a href="#/wall/${encodeURIComponent(s.wall_exhibition_id)}">View linked Wall exhibition →</a>`:'<p class="muted-copy">Link an existing Wall exhibition from Edit Session.</p>'}</section></div>`,onOpen:m=>{$('#studio-resource',m)?.addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/sessions/${id}/resources`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast('Resource attached.');sessionStudio(id)}catch(err){toast(err.message,'error')}})}})}


// v4.8–v5.6 — Maker Crews
function crewBadge(c){return c?`<span class="crew-badge">${esc(c.code)}</span>`:''}
async function renderCrews(postal=''){
  setTitle('Maker Crews');const d=await api(`/api/crews${postal?`?postal=${encodeURIComponent(postal)}`:''}`);
  const cards=d.items.map(c=>`<a class="crew-card" href="#/crew/${encodeURIComponent(c.id)}"><div class="crew-code">${esc(c.code)}</div><div><span class="technical-index">${c.exactPostalMatch?'SERVES THIS ZIP':'MAKER CREW'}${c.distanceMiles!=null?` · ~${c.distanceMiles} mi`:''}</span><h2>${esc(c.name)}</h2><p>${esc(c.city_region||c.anchor_postal_code)}</p><div class="crew-card-meta"><span>${c.memberCount} members</span><span>${c.projectCount} active projects</span>${c.nextEvent?`<span>${esc(c.nextEvent.title)}</span>`:''}</div></div><strong>OPEN CREW →</strong></a>`).join('');
  view.innerHTML=`<div class="view crews-view">${pageHead('FIND MAKERS NEAR YOU','Maker Crews','Local affiliation for makers who want to find another pair of hands, a useful skill, spare material, or people to make with—without publishing anyone’s home address.',state.me?'<button class="button-secondary" data-action="request-crew">REQUEST A CREW</button>':'<button class="button" data-action="login">ENTER THE WORKSHOP</button>')}
    ${d.myCrew?`<a class="my-crew-banner" href="#/crew/${encodeURIComponent(d.myCrew.id)}"><span>MY PRIMARY CREW</span><strong>${esc(d.myCrew.code)} · ${esc(d.myCrew.name)}</strong><b>WHAT’S HAPPENING NEARBY? →</b></a>`:''}
    <section class="crew-finder"><div><span class="technical-index">ZIP / POSTAL SEARCH</span><h2>Find a local bench.</h2><p>ZIP codes are search anchors and Crew identities—not proof of residence and never a member’s exact location.</p></div><form id="crew-search-form"><input name="postal" value="${esc(postal)}" placeholder="21502" autocomplete="postal-code" aria-label="ZIP or postal code"><button class="button">FIND CREWS</button></form></section>
    <div class="crew-list">${cards||empty('NO CREW FOUND','Request one, or search another nearby ZIP.')}</div>
  </div>`;
  $('#crew-search-form')?.addEventListener('submit',e=>{e.preventDefault();const q=new FormData(e.currentTarget).get('postal').trim();location.hash=q?`#/crews/${encodeURIComponent(q)}`:'#/crews'});
}
async function renderCrew(id,section=''){
  setTitle('Maker Crew');const d=await api(`/api/crews/${encodeURIComponent(id)}`),c=d.item,m=c.membership,member=Boolean(m);
  const skills=[...new Set(c.members.flatMap(x=>x.canHelp||[]))].slice(0,12);
  view.innerHTML=`<div class="view crew-view">
    <header class="crew-hero"><div class="crew-code huge">${esc(c.code)}</div><div><div class="technical-index">MAKER CREW · ${esc(c.anchor_postal_code)} · ${esc(c.city_region)}</div><h1>${esc(c.name)}</h1><p>${esc(c.description)}</p><div class="crew-coverage">SERVES ${c.coverage.map(z=>`<span>${esc(z.postal_code)}</span>`).join('')}</div><div class="head-actions">${state.me?(member?`<button class="button-secondary" data-action="leave-crew" data-id="${esc(c.id)}">LEAVE CREW</button>`:`<button class="button" data-action="join-crew" data-id="${esc(c.id)}">JOIN ${esc(c.code)}</button>`):'<button class="button" data-action="login">ENTER TO JOIN</button>'}${c.canOrganize?`<button class="button-secondary deep-only" data-action="crew-studio" data-id="${esc(c.id)}">CREW STUDIO</button>`:''}</div></div></header>
    <section class="crew-nearby"><div class="editorial-head"><div><span class="section-number">01</span><h2>WHAT’S HAPPENING NEARBY?</h2></div><span>${c.memberCount} CREW MEMBERS</span></div><div class="crew-pulse-grid">${c.nextEvent?`<a href="#/crew/${encodeURIComponent(c.id)}/meetups"><span>NEXT MEETUP</span><strong>${esc(c.nextEvent.title)}</strong><small>${fmtDate(c.nextEvent.starts_at,true)}</small></a>`:''}<a href="#/crew/${encodeURIComponent(c.id)}/bench"><span>LOCAL BENCH</span><strong>${c.projectCount}</strong><small>active Crew projects</small></a><a href="#/crew/${encodeURIComponent(c.id)}/skills"><span>SKILLS NEARBY</span><strong>${skills.length}</strong><small>ways members can help</small></a><a href="#/crew/${encodeURIComponent(c.id)}/scrap"><span>LOCAL SCRAP</span><strong>${c.scrap.length}</strong><small>available listings</small></a></div></section>
    ${c.announcements.length?`<section class="crew-announcements"><div class="technical-index">CREW ANNOUNCEMENTS</div>${c.announcements.map(a=>`<article><strong>${esc(a.title)}</strong><p>${esc(a.body)}</p><small>${esc(a.author)} · ${ago(a.created_at)}</small></article>`).join('')}</section>`:''}
    <section class="editorial-section" id="crew-meetups"><div class="editorial-head"><div><span class="section-number">02</span><h2>MEETUPS</h2></div>${c.canOrganize?`<button class="text-button" data-action="crew-event" data-id="${esc(c.id)}">+ SCHEDULE MEETUP</button>`:''}</div>${c.events.length?`<div class="crew-event-grid">${c.events.map(e=>`<article class="crew-event"><div><span class="technical-index">${esc(e.event_type)} · ${esc(e.status)}</span><h3>${esc(e.title)}</h3><p>${esc(e.description)}</p><dl class="detail-list"><dt>When</dt><dd>${fmtDate(e.starts_at,true)}</dd><dt>Where</dt><dd>${esc(e.venue_name||e.city_region||'Location shared by organizer')}${e.exact_address?`<br>${esc(e.exact_address)}`:''}</dd><dt>Going</dt><dd>${Number(e.attendee_count||0)}</dd></dl></div>${member?`<div class="head-actions"><button class="button-secondary compact" data-action="crew-rsvp" data-id="${esc(e.id)}" data-crew-id="${esc(c.id)}" data-status="Interested">INTERESTED</button><button class="button compact" data-action="crew-rsvp" data-id="${esc(e.id)}" data-crew-id="${esc(c.id)}" data-status="Going">${e.myAttendance?.approved?'GOING':e.approval_required?'REQUEST TO ATTEND':'I’M GOING'}</button></div>`:''}</article>`).join('')}</div>`:'<p class="muted-copy">No Crew meetup is scheduled yet.</p>'}</section>
    <section class="editorial-section" id="crew-local-bench"><div class="editorial-head"><div><span class="section-number">03</span><h2>ON THE LOCAL BENCH</h2></div>${member?`<button class="text-button" data-action="new-crew-project" data-id="${esc(c.id)}">+ CREW PROJECT</button>`:''}</div>${c.projects.length?`<div class="grid projects">${c.projects.map(projectCard).join('')}</div>`:empty('LOCAL BENCH IS CLEAR','Start a repair, build, experiment, or shared Crew project.')}</section>
    <section class="editorial-section" id="crew-skills"><div class="editorial-head"><div><span class="section-number">04</span><h2>SKILLS NEARBY</h2></div><span>INTRODUCTIONS, NOT RANKINGS</span></div><div class="crew-member-grid">${c.members.map(p=>`<article><div class="person-card-head"><div class="person-avatar-v4">${esc(p.avatar_seed||initials(p.display_name))}</div><div><strong>${esc(p.display_name)}</strong><small>${esc(p.role)}</small></div></div>${p.canHelp.length?`<div><span>CAN HELP WITH</span><p>${esc(p.canHelp.slice(0,5).join(' · '))}</p></div>`:''}${p.wantLearn.length?`<div><span>WANTS TO LEARN</span><p>${esc(p.wantLearn.slice(0,4).join(' · '))}</p></div>`:''}<div class="head-actions"><a class="text-button" href="#/bench/${esc(p.user_id)}">VISIT BENCH</a>${state.me&&state.me.id!==p.user_id?`<button class="text-button" data-action="skill-request" data-id="${esc(p.user_id)}" data-name="${esc(p.display_name)}">INTRODUCTION</button>`:''}</div></article>`).join('')}</div></section>
    <section class="editorial-section" id="crew-tools"><div class="editorial-head"><div><span class="section-number">05</span><h2>TOOLS THAT CAN HELP LOCALLY</h2></div><span>LOCATION STAYS PRIVATE</span></div>${c.tools.length?`<div class="crew-tool-grid">${c.tools.map(t=>`<article><span class="technical-index">${esc(t.local_availability)}</span><h3>${esc([t.manufacturer,t.model].filter(Boolean).join(' '))}</h3><p>${esc(t.category)} · ${esc(t.owner)}</p><small>${esc(t.notes||'Contact the maker to arrange help.')}</small></article>`).join('')}</div>`:'<p class="muted-copy">Nobody has marked a Tool Cabinet item as locally available yet.</p>'}</section>
    <section class="editorial-section" id="crew-scrap"><div class="editorial-head"><div><span class="section-number">06</span><h2>LOCAL SCRAP BIN</h2></div>${member?`<button class="text-button" data-action="crew-scrap" data-id="${esc(c.id)}">+ OFFER LOCALLY</button>`:''}</div>${c.scrap.length?`<div class="grid projects">${c.scrap.map(x=>`<a class="project-card" href="#/scrap/${esc(x.id)}"><div class="project-visual"><span>♲</span></div><div class="project-body"><div class="kicker-row"><span class="stage-badge">${esc(x.exchange_type)}</span><span>${esc(x.category)}</span></div><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p><div class="project-footer"><span>${esc(x.city_region||c.city_region)}</span><span>${esc(x.owner)}</span></div></div></a>`).join('')}</div>`:'<p class="muted-copy">No local listings right now.</p>'}</section>
    <section class="editorial-section" id="crew-questions"><div class="editorial-head"><div><span class="section-number">07</span><h2>ASK LOCALLY</h2></div>${member?`<button class="text-button" data-action="crew-question" data-id="${esc(c.id)}">+ ASK ${esc(c.code)}</button>`:''}</div>${c.questions.length?`<div class="question-list">${c.questions.map(q=>`<a class="question-row" href="#/question/${esc(q.id)}"><div class="row-content"><span class="technical-index">${esc(q.author)} · ${ago(q.updated_at)}</span><strong>${esc(q.title)}</strong><p>${esc(q.help_needed||q.trying)}</p></div><span class="question-status">${Number(q.answer_count)} answers</span></a>`).join('')}</div>`:'<p class="muted-copy">No local questions yet.</p>'}</section>
    <section class="editorial-section crew-bulletin" id="crew-bulletin"><div class="editorial-head"><div><span class="section-number">08</span><h2>CREW BULLETIN BOARD</h2></div>${member?`<button class="text-button" data-action="crew-bulletin" data-id="${esc(c.id)}">+ PIN A NOTE</button>`:''}</div>${c.bulletin.length?`<div class="bulletin-grid">${c.bulletin.map(b=>`<article><span>${esc(b.post_type)}</span><h3>${esc(b.title)}</h3><p>${esc(b.body)}</p><small>${esc(b.author)} · ${ago(b.created_at)}</small></article>`).join('')}</div>`:'<p class="muted-copy">The corkboard is empty.</p>'}</section>
    ${c.sessions.length?`<section class="editorial-section" id="crew-sessions"><div class="editorial-head"><div><span class="section-number">09</span><h2>CREW SESSIONS</h2></div>${c.canOrganize?`<button class="text-button" data-action="crew-session" data-id="${esc(c.id)}">+ SESSION</button>`:''}</div><div class="session-list">${c.sessions.map(x=>`<a class="session-card" href="#/session/${esc(x.id)}"><span class="technical-index">${esc(c.code)} · ${esc(x.status)}</span><h2>${esc(x.title)}</h2><p>${esc(x.theme||x.description)}</p><span class="session-open">ENTER SESSION →</span></a>`).join('')}</div></section>`:c.canOrganize?`<section class="editorial-section"><button class="button-secondary" data-action="crew-session" data-id="${esc(c.id)}">START A CREW SESSION</button></section>`:''}
  </div>`;
  if(section){const sectionMap={meetups:'crew-meetups',bench:'crew-local-bench',skills:'crew-skills',tools:'crew-tools',scrap:'crew-scrap',questions:'crew-questions',bulletin:'crew-bulletin',sessions:'crew-sessions'};const targetId=sectionMap[section];if(targetId)requestAnimationFrame(()=>document.getElementById(targetId)?.scrollIntoView({behavior:'smooth',block:'start'}));}
}
async function joinCrew(id){if(!requireSignIn())return;modal({title:'Join Maker Crew',eyebrow:'LOCAL AFFILIATION, YOUR CHOICE',size:'sm',body:`<form id="join-crew-form" class="form-grid"><div class="field full"><label>Who can see this Crew affiliation?</label><select name="visibility"><option>Members</option><option>Public</option><option>Private</option></select></div><div class="field full"><label class="check-line"><input type="checkbox" name="primary" checked> Make this my primary Crew</label></div><div class="field full"><p class="muted-copy">Joining does not expose your home address, GPS location, or exact tool locations.</p><button class="button">JOIN CREW</button></div></form>`,onOpen:m=>$('#join-crew-form',m).addEventListener('submit',async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));f.primary=Boolean(f.primary);try{await api(`/api/crews/${id}/join`,{method:'POST',body:JSON.stringify(f)});closeOverlay();toast('Crew joined.');renderCrew(id)}catch(err){toast(err.message,'error')}})})}
async function leaveCrew(id){if(!confirm('Leave this Maker Crew? Your projects and past participation remain intact.'))return;try{await api(`/api/crews/${id}/join`,{method:'DELETE'});toast('Crew affiliation removed.');renderCrew(id)}catch(err){toast(err.message,'error')}}

async function renderGearheadContributions(){setTitle('GearHead Contributions');if(!state.me){view.innerHTML=`<div class="view narrow">${pageHead('GEARHEAD CREW ONLY','Contributions','GearHeads can help test, correct, review, and extend the work.')}<button class="button" data-action="login">ENTER THE WORKSHOP</button></div>`;return;}try{const d=await api('/api/gearhead/contributions');view.innerHTML=`<div class="view narrow">${pageHead('HELP MOVE THE WORK FORWARD','GearHead Contributions','Testing notes, corrections, tutorial reviews, BOM checks, and alternate process notes.',`<button class="button" data-action="gearhead-contribution-new">+ CONTRIBUTE</button><a class="button-secondary" href="#/gearhead">GEARHEAD HOME →</a>`)}<section class="section"><div class="request-board">${d.items.map(c=>`<article class="request-card"><div><span class="gearhead-stamp">${esc(c.contribution_type)}</span><h3>${esc(c.title)}</h3><p>${esc(c.body)}</p><small>${esc(c.author)}${c.entry_title?` · ${esc(c.entry_title)}`:''}${c.project_title?` · ${esc(c.project_title)}`:''} · ${fmtDate(c.created_at,true)}</small></div><div class="request-status"><strong>${esc(c.status)}</strong>${c.editor_note?`<p>${esc(c.editor_note)}</p>`:''}${d.canManage?`<button class="text-button" data-action="gearhead-contribution-review" data-id="${esc(c.id)}">REVIEW</button>`:''}</div></article>`).join('')||empty('NO CONTRIBUTIONS YET','Test something, correct something, or document an alternate way through it.')}</div></section></div>`}catch(err){view.innerHTML=`<div class="view narrow">${pageHead('GEARHEAD CREW ONLY','Contributions',err.message)}<button class="button" data-action="membership">JOIN THE GEARHEAD CREW</button></div>`}}
function gearheadContributionForm(entryId='',projectId=''){modal({title:'Contribute to the Crew',eyebrow:'GEARHEAD CREW ONLY',size:'md',body:`<form id="gh-contribution-form" class="form-grid"><div class="field"><label>Contribution type</label><select name="contributionType">${['Testing note','Correction','Tutorial review','BOM check','Alternate process','Documentation','Other'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field full"><label>Title</label><input name="title" required></div><div class="field full"><label>What did you find or improve?</label><textarea name="body" required></textarea></div><input type="hidden" name="entryId" value="${esc(entryId)}"><input type="hidden" name="projectId" value="${esc(projectId)}"><div class="field full"><button class="button">SEND CONTRIBUTION</button></div></form>`,onOpen:m=>$('#gh-contribution-form',m).addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/gearhead/contributions',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast('Contribution sent to the bench.');location.hash='#/gearhead-contributions'}catch(err){toast(err.message,'error')}})})}
async function gearheadContributionReview(id){const d=await api('/api/gearhead/contributions'),c=d.items.find(x=>x.id===id);if(!c)return;modal({title:'Review Contribution',eyebrow:'GEARHEAD STUDIO',size:'sm',body:`<form id="gh-contribution-review" class="form-grid"><div class="field full"><label>Status</label><select name="status">${['Submitted','Reviewing','Accepted','Published','Declined'].map(x=>`<option ${c.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Editor note</label><textarea name="editorNote">${esc(c.editor_note||'')}</textarea></div><div class="field full"><button class="button">SAVE REVIEW</button></div></form>`,onOpen:m=>$('#gh-contribution-review',m).addEventListener('submit',async e=>{e.preventDefault();await api(`/api/gearhead/contributions/${id}`,{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();renderGearheadContributions()})})}

async function renderGearheadCrewProjects(){setTitle('GearHead Crew Projects');const d=await api('/api/gearhead/crew-projects');view.innerHTML=`<div class="view gearhead-view">${pageHead('MAKE SOMETHING TOGETHER','GearHead Crew Projects','Occasional shared builds for the people helping keep Green Shoe Garage moving.',`${d.canManage?'<button class="button" data-action="gearhead-crew-project-new">+ NEW CREW PROJECT</button>':''}<a class="button-secondary" href="#/gearhead">GEARHEAD HOME →</a>`)}<section class="section"><div class="gearhead-grid">${d.items.map(c=>`<article class="gearhead-card"><div class="gearhead-card-copy"><div class="gearhead-stamp">GEARHEAD CREW PROJECT · ${esc(c.status)}</div><h3>${esc(c.title)}</h3><p>${esc(c.brief)}</p><div class="gearhead-card-meta"><span>${c.response_count} linked project${c.response_count===1?'':'s'}</span>${c.ends_at?`<span>Ends ${fmtDate(c.ends_at)}</span>`:''}</div>${c.myProjectId?`<a class="button-secondary" href="#/projects/${encodeURIComponent(c.myProjectId)}">OPEN MY VERSION →</a>`:d.active&&c.status==='Active'?`<button class="button" data-action="gearhead-crew-project-start" data-id="${esc(c.id)}">START MY VERSION</button>`:'<span class="gearhead-stamp">GEARHEAD CREW ONLY</span>'}</div></article>`).join('')||empty('NO CREW PROJECT ON THE BENCH','The next shared build will show up here.')}</div></section></div>`}
function gearheadCrewProjectForm(){modal({title:'New GearHead Crew Project',eyebrow:'EDITORIAL',size:'md',body:`<form id="gh-crew-project-form" class="form-grid"><div class="field full"><label>Title</label><input name="title" required></div><div class="field full"><label>Brief</label><textarea name="brief" required></textarea></div><div class="field"><label>Status</label><select name="status"><option>Active</option><option>Upcoming</option><option>Complete</option><option>Archived</option></select></div><div class="field"><label>Starts</label><input type="date" name="startsAt"></div><div class="field"><label>Ends</label><input type="date" name="endsAt"></div><div class="field full"><label>Reference project ID · optional</label><input name="referenceProjectId"></div><div class="field full"><button class="button">CREATE CREW PROJECT</button></div></form>`,onOpen:m=>$('#gh-crew-project-form',m).addEventListener('submit',async e=>{e.preventDefault();const r=await api('/api/gearhead/crew-projects',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast('Crew Project is on the bench.');location.hash='#/gearhead-projects'})})}
async function gearheadCrewProjectStart(id){try{const r=await api(`/api/gearhead/crew-projects/${id}/start`,{method:'POST',body:'{}'});toast('Your version is on the bench.');location.hash=`#/projects/${r.projectId}`}catch(err){toast(err.message,'error')}}

async function gearheadStudio2(){const [a,c,f,r,p]=await Promise.all([api('/api/gearhead/studio2'),api('/api/gearhead/contributions'),api('/api/gearhead/feedback').catch(()=>({items:[]})),api('/api/gearhead/requests'),api('/api/gearhead/crew-projects')]);modal({title:'GearHead Crew Studio 2.0',eyebrow:'PUBLISHING · PROGRAM · MEMBERSHIP · HEALTH',size:'xl',body:`<div class="studio-layout"><section><div class="studio-head"><div><span>ACTIVE GEARHEADS</span><strong>${a.activeGearheads}</strong></div><div><span>DRAFTS</span><strong>${a.drafts}</strong></div><div><span>GOING PUBLIC</span><strong>${a.goingPublic}</strong></div><div><span>AFTER HOURS</span><strong>${a.afterHours}</strong></div></div><div class="head-actions"><button class="button" data-action="gearhead-quick">POST TO GEARHEAD CREW</button><button class="button-secondary" data-action="gearhead-crew-project-new">NEW CREW PROJECT</button><button class="button-secondary" data-action="gearhead-send-digest">SEND DIGEST</button></div></section><section class="studio-health"><h3>NEEDS ATTENTION</h3><div class="maker-id-metrics"><div><strong>${a.contributions}</strong><span>Contributions</span></div><div><strong>${a.feedback}</strong><span>Early feedback</span></div><div><strong>${a.requests}</strong><span>Crew requests</span></div><div><strong>${a.providerFailures}</strong><span>Provider failures</span></div></div></section><section><h3>CONTRIBUTIONS</h3>${c.items.slice(0,6).map(x=>`<div class="studio-row"><span>HELP</span><div><strong>${esc(x.title)}</strong><small>${esc(x.contribution_type)} · ${esc(x.status)}</small></div><button class="text-button" data-action="gearhead-contribution-review" data-id="${esc(x.id)}">REVIEW</button></div>`).join('')||'<p class="muted-copy">Nothing waiting.</p>'}</section><section><h3>CREW PROJECTS</h3>${p.items.slice(0,6).map(x=>`<div class="studio-row"><span>BUILD</span><div><strong>${esc(x.title)}</strong><small>${esc(x.status)} · ${x.response_count} responses</small></div></div>`).join('')||'<p class="muted-copy">No active Crew Project.</p>'}</section></div>`})}

function crewRequestForm(){if(!requireSignIn())return;modal({title:'Request a Maker Crew',eyebrow:'START SOMETHING LOCAL',size:'lg',body:`<form id="crew-request-form" class="form-grid"><div class="field"><label>Anchor ZIP / postal code</label><input name="postalCode" required placeholder="21502"></div><div class="field"><label>Country</label><input name="country" value="US"></div><div class="field full"><label>Proposed name</label><input name="name" required placeholder="Cumberland Maker Crew"></div><div class="field"><label>City / region</label><input name="cityRegion" placeholder="Cumberland, MD"></div><div class="field"><label>Nearby ZIPs to serve</label><input name="nearbyPostalCodes" placeholder="21501, 21532"></div><div class="field full"><label>Why would this Crew be useful?</label><textarea name="rationale" required></textarea></div><div class="field"><label>Proposed organizers</label><input name="organizers"></div><div class="field"><label>Expected active participants</label><input type="number" name="estimatedParticipants" min="0"></div><div class="field full"><button class="button">SEND REQUEST</button></div></form>`,onOpen:m=>$('#crew-request-form',m).addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/crew-requests',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast('Crew request sent for review.')}catch(err){toast(err.message,'error')}})})}
function crewProjectForm(crewId){modal({title:'Start a Crew Project',eyebrow:'MAKE SOMETHING TOGETHER',size:'md',body:`<form id="crew-project-form" class="form-grid"><div class="field full"><label>Project</label><input name="title" required></div><div class="field full"><label>What are you trying to make?</label><textarea name="description"></textarea></div><div class="field"><label>Visibility</label><select name="visibility"><option>Members</option><option>Public</option><option>Private</option></select></div><div class="field"><label>Type</label><select name="projectType"><option>Project</option><option>Repair</option><option>Experiment</option><option>Community Build</option></select></div><div class="field full"><button class="button">PUT IT ON THE LOCAL BENCH</button></div></form>`,onOpen:m=>$('#crew-project-form',m).addEventListener('submit',async e=>{e.preventDefault();try{const r=await api(`/api/crews/${crewId}/projects`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();location.hash=`#/projects/${r.id}`}catch(err){toast(err.message,'error')}})})}
function crewQuestionForm(crewId){modal({title:'Ask Locally',eyebrow:'ANOTHER PAIR OF HANDS NEARBY',size:'md',body:`<form id="crew-question-form" class="form-grid"><div class="field full"><label>Question</label><input name="title" required></div><div class="field full"><label>What are you trying to do?</label><textarea name="trying" required></textarea></div><div class="field full"><label>What kind of local help would be useful?</label><textarea name="helpNeeded"></textarea></div><div class="field full"><button class="button">ASK THE CREW</button></div></form>`,onOpen:m=>$('#crew-question-form',m).addEventListener('submit',async e=>{e.preventDefault();try{const r=await api(`/api/crews/${crewId}/questions`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();location.hash=`#/question/${r.id}`}catch(err){toast(err.message,'error')}})})}
function crewScrapForm(crewId){modal({title:'Offer Locally',eyebrow:'LOCAL SCRAP BIN',size:'md',body:`<form id="crew-scrap-form" class="form-grid"><div class="field full"><label>What is available?</label><input name="title" required></div><div class="field"><label>Category</label><input name="category" placeholder="Motors"></div><div class="field"><label>Exchange</label><select name="exchangeType"><option>Free</option><option>Trade</option><option>Shipping cost</option><option>Local pickup</option></select></div><div class="field"><label>Access</label><select name="visibility"><option value="Public" ${(d.visibility||'Public')==='Public'?'selected':''}>Public</option><option value="GearHead" ${d.visibility==='GearHead'?'selected':''}>GEARHEAD CREW ONLY</option></select></div><div class="field full"><label>Description</label><textarea name="description"></textarea></div><div class="field"><label>Approximate city / region</label><input name="cityRegion"></div><div class="field"><label>Quantity</label><input name="quantityText"></div><div class="field full"><button class="button">PUT IT IN THE LOCAL BIN</button></div></form>`,onOpen:m=>$('#crew-scrap-form',m).addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/crews/${crewId}/scrap`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast('Offered to your Crew.');renderCrew(crewId)}catch(err){toast(err.message,'error')}})})}
function crewBulletinForm(crewId){modal({title:'Pin to the Crew Board',eyebrow:'SHORT-LIVED, LOCAL, USEFUL',size:'sm',body:`<form id="crew-bulletin-form" class="form-grid"><div class="field"><label>Type</label><select name="postType">${['Looking For','Can Help','Found','Going','Question','Announcement'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Expires (optional)</label><input type="date" name="expiresAt"></div><div class="field full"><label>Title</label><input name="title" required></div><div class="field full"><label>Note</label><textarea name="body" required></textarea></div><div class="field full"><button class="button">PIN NOTE</button></div></form>`,onOpen:m=>$('#crew-bulletin-form',m).addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/crews/${crewId}/bulletin`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();renderCrew(crewId)}catch(err){toast(err.message,'error')}})})}
function crewEventForm(crewId){modal({title:'Schedule a Crew Meetup',eyebrow:'MEET → MAKE → GO HOME WITH SOMETHING LEARNED',size:'lg',body:`<form id="crew-event-form" class="form-grid"><div class="field full"><label>Meetup title</label><input name="title" required></div><div class="field"><label>Type</label><select name="eventType">${['Open Bench','Repair Night','Show & Tell','Tool Swap','Build Session','Skill Share','Field Trip','Workshop Tour','Coffee & Projects','Teardown Night'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Start</label><input type="datetime-local" name="startsAt" required></div><div class="field"><label>Access</label><select name="visibility"><option value="Public" ${(d.visibility||'Public')==='Public'?'selected':''}>Public</option><option value="GearHead" ${d.visibility==='GearHead'?'selected':''}>GEARHEAD CREW ONLY</option></select></div><div class="field full"><label>Description</label><textarea name="description"></textarea></div><div class="field"><label>Venue name</label><input name="venueName"></div><div class="field"><label>City / region</label><input name="cityRegion"></div><div class="field full"><label>Exact address · optional</label><input name="exactAddress"></div><div class="field"><label>Who sees exact address?</label><select name="addressVisibility"><option value="Attendees">Approved attendees</option><option value="Public">Everyone</option><option value="Organizers">Organizers only</option></select></div><div class="field"><label>Capacity</label><input type="number" name="capacity" min="0"></div><div class="field full"><label class="check-line"><input type="checkbox" name="approvalRequired"> Require organizer approval to attend</label></div><div class="field full"><label>What to bring</label><textarea name="whatToBring"></textarea></div><div class="field full"><label>Safety notes</label><textarea name="safetyNotes"></textarea></div><div class="field full"><button class="button">SCHEDULE MEETUP</button></div></form>`,onOpen:m=>$('#crew-event-form',m).addEventListener('submit',async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));b.approvalRequired=Boolean(b.approvalRequired);try{await api(`/api/crews/${crewId}/events`,{method:'POST',body:JSON.stringify(b)});closeOverlay();toast('Meetup scheduled.');renderCrew(crewId)}catch(err){toast(err.message,'error')}})})}
async function crewRsvp(eventId,status,crewId){try{const r=await api(`/api/crew-events/${eventId}/attendance`,{method:'POST',body:JSON.stringify({status})});toast(r.pending?'Attendance request sent.':'Meetup response saved.');renderCrew(crewId)}catch(err){toast(err.message,'error')}}
function crewAnnouncementForm(crewId){modal({title:'Crew Announcement',eyebrow:'USEFUL SIGNAL, NOT BROADCAST NOISE',size:'sm',body:`<form id="crew-ann-form" class="form-grid"><div class="field full"><label>Title</label><input name="title" required></div><div class="field full"><label>Message</label><textarea name="body" required></textarea></div><div class="field"><label>Visibility</label><select name="visibility"><option>Members</option><option>Public</option></select></div><div class="field full"><button class="button">POST ANNOUNCEMENT</button></div></form>`,onOpen:m=>$('#crew-ann-form',m).addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/crews/${crewId}/announcements`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();renderCrew(crewId)}catch(err){toast(err.message,'error')}})})}
function crewSessionForm(crewId){modal({title:'Start a Crew Session',eyebrow:'LOCAL MAKING PROGRAM',size:'md',body:`<form id="crew-session-form" class="form-grid"><div class="field full"><label>Session title</label><input name="title" required></div><div class="field full"><label>Theme</label><input name="theme"></div><div class="field"><label>Access</label><select name="visibility"><option value="Public" ${(d.visibility||'Public')==='Public'?'selected':''}>Public</option><option value="GearHead" ${d.visibility==='GearHead'?'selected':''}>GEARHEAD CREW ONLY</option></select></div><div class="field full"><label>Description</label><textarea name="description"></textarea></div><div class="field"><label>Starts</label><input type="date" name="startsAt"></div><div class="field"><label>Ends</label><input type="date" name="endsAt"></div><div class="field"><label>Status</label><select name="status"><option>Draft</option><option>Upcoming</option><option>Active</option></select></div><input type="hidden" name="crewId" value="${esc(crewId)}"><div class="field full"><button class="button">CREATE CREW SESSION</button></div></form>`,onOpen:m=>$('#crew-session-form',m).addEventListener('submit',async e=>{e.preventDefault();try{const r=await api('/api/sessions',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();location.hash=`#/session/${r.id}`}catch(err){toast(err.message,'error')}})})}
async function crewStudio(crewId){const d=await api(`/api/crews/${crewId}`),c=d.item;modal({title:`${c.code} Crew Studio`,eyebrow:'LOCAL OPERATIONS',size:'xl',body:`<div class="studio-layout"><section><div class="technical-index">CREW</div><h2>${esc(c.name)}</h2><p>${esc(c.description)}</p><button class="button-secondary" data-action="crew-announcement" data-id="${esc(c.id)}">+ ANNOUNCEMENT</button></section><section><div class="studio-head"><div><span>MEMBERS</span><strong>${c.members.length}</strong></div></div>${c.members.map(m=>`<div class="studio-row"><span>${esc(m.role.slice(0,1))}</span><div><strong>${esc(m.display_name)}</strong><small>${esc(m.role)} · affiliation ${esc(m.affiliation_visibility)}</small></div><div class="head-actions">${m.role==='Member'?`<button class="text-button" data-action="crew-member-role" data-crew-id="${esc(c.id)}" data-id="${esc(m.user_id)}" data-role="Moderator">MAKE MODERATOR</button>`:`<button class="text-button" data-action="crew-member-role" data-crew-id="${esc(c.id)}" data-id="${esc(m.user_id)}" data-role="Member">MAKE MEMBER</button>`}</div></div>`).join('')}</section><section><div class="technical-index">COVERAGE ZIPS</div>${c.coverage.map(z=>`<div class="studio-row"><span>${z.is_anchor?'★':'·'}</span><div><strong>${esc(z.postal_code)}</strong><small>${z.latitude!=null?'centroid available':'distance unavailable until centroid added'}</small></div></div>`).join('')}<form id="coverage-form" class="inline-form"><input name="postalCode" placeholder="21532" required><button class="button-secondary">ADD ZIP</button></form></section><section><div class="technical-index">OPERATIONS</div><div class="crew-op-buttons"><button class="button-secondary" data-action="crew-event" data-id="${esc(c.id)}">SCHEDULE MEETUP</button><button class="button-secondary" data-action="crew-session" data-id="${esc(c.id)}">START SESSION</button><button class="button-secondary" data-action="crew-announcement" data-id="${esc(c.id)}">ANNOUNCEMENT</button></div></section></div>`,onOpen:m=>$('#coverage-form',m)?.addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/crews/${crewId}/postal-codes`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast('Coverage ZIP added.');crewStudio(crewId)}catch(err){toast(err.message,'error')}})})}
async function crewRequestsAdmin(){try{const d=await api('/api/crew-requests');modal({title:'Maker Crew Requests',eyebrow:'GLOBAL ADMIN',size:'lg',body:d.items.length?`<div class="admin-table">${d.items.map(r=>`<article class="admin-row"><div><strong>${esc(r.proposed_name)}</strong><small>${esc(r.proposed_postal_code)} · ${esc(r.city_region)} · ${esc(r.requester)}</small><p>${esc(r.rationale)}</p><small>${(r.nearbyPostalCodes||[]).length?`Nearby ZIPs: ${esc(r.nearbyPostalCodes.join(', '))}`:''}</small></div><div><span class="tag">${esc(r.status)}</span>${r.status==='Submitted'||r.status==='Reviewing'?`<div class="head-actions"><button class="text-button" data-action="crew-request-review" data-id="${esc(r.id)}" data-status="Approved" data-create-crew="1">APPROVE + CREATE</button><button class="text-button danger-text" data-action="crew-request-review" data-id="${esc(r.id)}" data-status="Declined">DECLINE</button></div>`:''}</div></article>`).join('')}</div>`:'<p class="muted-copy">No Maker Crew requests are waiting.</p>'})}catch(err){toast(err.message,'error')}}
async function crewRequestReview(id,status,createCrew=false){try{const r=await api(`/api/crew-requests/${id}`,{method:'PUT',body:JSON.stringify({status,createCrew})});closeOverlay();toast(status==='Approved'?'Crew request approved.':'Crew request declined.');if(r.crewId)location.hash=`#/crew/${r.crewId}`;else crewRequestsAdmin()}catch(err){toast(err.message,'error')}}
async function crewMemberRole(crewId,userId,role,status='Active'){try{await api(`/api/crews/${crewId}/members/${userId}`,{method:'PUT',body:JSON.stringify({role,status})});toast('Crew member updated.');renderCrew(crewId)}catch(err){toast(err.message,'error')}}
